# EMBYFLOW_PERFORMANCE_PATCH1_V1
# Risikoarme Performanceverbesserungen:
# - echte LRU-Nutzung für Bilddateien über gedrosseltes os.utime()
# - 10-Minuten-Negativcache für fehlende Bilder
# - globale Cachebereinigung höchstens alle 30 Sekunden
# - kleiner, kurzlebiger RAM-Cache für wiederholte Emby-GET-Antworten
EMBYFLOW_CACHE_TOUCH_INTERVAL = 30
EMBYFLOW_NEGATIVE_CACHE_TTL = 600
EMBYFLOW_CACHE_TUNE_INTERVAL = 30
EMBYFLOW_CACHE_LAST_TUNE = 0.0
EMBYFLOW_CACHE_TOUCHES = {}
EMBYFLOW_API_RAM_CACHE = {}
EMBYFLOW_API_RAM_CACHE_MAX = 48
EMBYFLOW_API_RAM_CACHE_LOCK = None

# EMBYFLOW_PERFORMANCE_PATCH21_AUTOTUNE_V1
# EMBYFLOW_PERFORMANCE_PATCH22_AUTOTUNE_RESERVE_V1
# Automatische Nachbereinigung nach abgeschlossenen Bild-Downloadlaeufen:
# - weiterhin hoechstens ein Cache-Scan pro 30 Sekunden
# - vor dem Scan zwei Sekunden Ruhe seit dem letzten Bild-Batch
# - automatische Bereinigung auf 99 MiB als Reserve unter dem harten 100-MiB-Limit
# - reale Groesse nach dem Scan erneut pruefen
# - bei erneutem Ueberschreiten genau ein zweiter, gedrosselter Kontrolllauf
EMBYFLOW_CACHE_AUTOTUNE_TARGET_BYTES = 99 * 1024 * 1024
EMBYFLOW_CACHE_AUTOTUNE_QUIET_SECONDS = 2.0
EMBYFLOW_CACHE_AUTOTUNE_VERIFY_DELAY = 0.50
EMBYFLOW_CACHE_TUNE_REQUEST_LOCK = None
EMBYFLOW_CACHE_TUNE_REQUEST_PENDING = False
EMBYFLOW_CACHE_TUNE_REQUEST_DIRTY = False
EMBYFLOW_CACHE_TUNE_REQUEST_LAST_ACTIVITY = 0.0
EMBYFLOW_CACHE_TUNE_REQUEST_LAST_REASON = "image-batch"


def embyflow_touch_cache_file(path, min_interval=EMBYFLOW_CACHE_TOUCH_INTERVAL):
    """Markiert nur echte Bild-Cachetreffer als zuletzt benutzt."""
    try:
        cache_path = str(path or "")
        if not cache_path or not os.path.isfile(cache_path):
            return False

        now = time.time()
        last_touch = float(
            EMBYFLOW_CACHE_TOUCHES.get(cache_path, 0.0)
            or 0.0
        )

        if now - last_touch < max(1, int(min_interval or 0)):
            return True

        os.utime(cache_path, None)
        EMBYFLOW_CACHE_TOUCHES[cache_path] = now

        # Die kleine RAM-Tabelle darf nicht unbegrenzt wachsen.
        if len(EMBYFLOW_CACHE_TOUCHES) > 512:
            cutoff = now - 3600
            for old_path, old_ts in list(
                EMBYFLOW_CACHE_TOUCHES.items()
            ):
                if float(old_ts or 0.0) < cutoff:
                    EMBYFLOW_CACHE_TOUCHES.pop(old_path, None)

        return True
    except Exception:
        return False


def embyflow_negative_cache_active(
    marker_path,
    ttl=EMBYFLOW_NEGATIVE_CACHE_TTL
):
    try:
        path = str(marker_path or "")
        if not path or not os.path.isfile(path):
            return False

        age = max(0.0, time.time() - os.path.getmtime(path))
        if age < max(1, int(ttl or 0)):
            return True

        try:
            os.remove(path)
        except Exception:
            pass
        return False
    except Exception:
        return False


def embyflow_mark_negative_cache(marker_path, reason="missing"):
    try:
        path = str(marker_path or "")
        if not path:
            return False
        ensure_dir(os.path.dirname(path))
        temporary = path + ".tmp"
        with open(temporary, "w") as handle:
            handle.write(str(reason or "missing"))
        try:
            os.replace(temporary, path)
        except AttributeError:
            try:
                os.remove(path)
            except Exception:
                pass
            os.rename(temporary, path)
        return True
    except Exception:
        return False


def embyflow_clear_negative_cache(marker_path):
    try:
        path = str(marker_path or "")
        if path and os.path.isfile(path):
            os.remove(path)
        return True
    except Exception:
        return False


# EMBYFLOW_PERFORMANCE_PATCH2_EPICLOAD_V1
# Normale Poster werden bereits passend vom Emby-Server angefordert und
# im GUI-Thread asynchron mit ePicLoad in die jeweilige Widgetgröße dekodiert.
# Aufwendige PIL-Normalisierung bleibt nur für echte Sonderfälle wie
# abgedunkelte Backdrops, Hero-Crops und Auto-Next-Artwork erhalten.
def embyflow_decode_image_to_widget(
    owner,
    widget_name,
    path,
    width,
    height,
    token="",
    is_current=None,
):
    try:
        image_path = str(path or "")
        if (
            not image_path
            or not os.path.isfile(image_path)
            or os.path.getsize(image_path) <= 500
        ):
            return False

        target_w = max(1, int(width or 1))
        target_h = max(1, int(height or 1))
        request_token = str(token or widget_name or image_path)

        state = getattr(owner, "_embyflow_picload_state", None)
        if not isinstance(state, dict):
            state = {}
            setattr(owner, "_embyflow_picload_state", state)

        request_id = str(uuid4())

        def apply_pixmap(data):
            try:
                if callable(is_current) and not is_current():
                    return False

                widget = owner[widget_name]
                instance = getattr(widget, "instance", None)
                if instance is None or data is None:
                    return False

                try:
                    instance.setPixmap(None)
                except Exception:
                    pass

                instance.setPixmap(data)

                try:
                    instance.setScale(1)
                except Exception:
                    pass

                try:
                    widget.show()
                    instance.show()
                    instance.invalidate()
                except Exception:
                    pass

                embyflow_touch_cache_file(image_path)
                return True

            except Exception:
                return False

        if ePicLoad is not None:
            loader = ePicLoad()
            state[request_token] = {
                "request_id": request_id,
                "loader": loader,
                "path": image_path,
            }

            def picture_ready(*_args):
                try:
                    current = state.get(request_token) or {}
                    if current.get("request_id") != request_id:
                        return
                    apply_pixmap(loader.getData())
                finally:
                    current = state.get(request_token) or {}
                    if current.get("request_id") == request_id:
                        state.pop(request_token, None)

            connected = False
            try:
                loader.PictureData.get().append(picture_ready)
                connected = True
            except Exception:
                try:
                    connection = loader.PictureData.connect(picture_ready)
                    state[request_token]["connection"] = connection
                    connected = True
                except Exception:
                    connected = False

            if connected:
                loader.setPara((
                    target_w,
                    target_h,
                    1,
                    1,
                    False,
                    1,
                    "#00000000",
                ))
                result = loader.startDecode(image_path)
                if result in (0, None):
                    return True

            state.pop(request_token, None)

        pixmap = LoadPixmap(image_path)
        return apply_pixmap(pixmap)

    except Exception:
        return False


def embyflow_cached_get_json(
    url,
    headers=None,
    params=None,
    ttl=30,
    timeout=10,
    verify=True,
    cache_key=""
):
    """Kleiner RAM-Cache nur für sichere, wiederholte GET-Abfragen."""
    global EMBYFLOW_API_RAM_CACHE_LOCK

    if not requests:
        return {}

    try:
        import copy
        import threading

        if EMBYFLOW_API_RAM_CACHE_LOCK is None:
            EMBYFLOW_API_RAM_CACHE_LOCK = threading.RLock()

        normalized_params = tuple(
            sorted(
                (str(key), str(value))
                for key, value in (params or {}).items()
            )
        )
        token_tail = str(
            (headers or {}).get("X-Emby-Token", "")
            or ""
        )[-8:]
        key = (
            str(cache_key or ""),
            str(url or ""),
            normalized_params,
            token_tail,
        )
        now = time.time()

        with EMBYFLOW_API_RAM_CACHE_LOCK:
            entry = EMBYFLOW_API_RAM_CACHE.get(key)
            if entry and now - float(entry.get("ts", 0.0) or 0.0) < max(1, int(ttl or 0)):
                entry["access"] = now
                return copy.deepcopy(entry.get("data") or {})

        response = embyflow_http_get(
            url,
            headers=headers,
            params=params,
            timeout=timeout,
            verify=verify,
        )
        if int(getattr(response, "status_code", 0) or 0) != 200:
            raise RuntimeError(
                "HTTP %s" % getattr(response, "status_code", "?")
            )

        data = response.json() or {}

        with EMBYFLOW_API_RAM_CACHE_LOCK:
            EMBYFLOW_API_RAM_CACHE[key] = {
                "ts": now,
                "access": now,
                "data": copy.deepcopy(data),
            }

            while len(EMBYFLOW_API_RAM_CACHE) > EMBYFLOW_API_RAM_CACHE_MAX:
                oldest_key = min(
                    EMBYFLOW_API_RAM_CACHE,
                    key=lambda candidate: float(
                        EMBYFLOW_API_RAM_CACHE[candidate].get(
                            "access",
                            0.0
                        )
                        or 0.0
                    )
                )
                del EMBYFLOW_API_RAM_CACHE[oldest_key]

        return data

    except Exception:
        raise

# EMBYFLOW_CACHE_TUNING_V1
EMBYFLOW_CACHE_LIMIT_BYTES = 100 * 1024 * 1024
EMBYFLOW_CACHE_PROTECTED_NAMES = set((
    "home_posters.json",
    "hero_slides.json",
    "poster1.jpg",
    "poster2.jpg",
    "poster3.jpg",
    "poster4.jpg",
    "poster5.jpg",
    "poster6.jpg",
))

def embyflow_tune_cache(
    limit_bytes=EMBYFLOW_CACHE_LIMIT_BYTES,
    force=False
):
    global EMBYFLOW_CACHE_LAST_TUNE

    result = {
        "before": 0,
        "after": 0,
        "deleted": 0,
        "freed": 0,
        "skipped": 0,
    }

    try:
        now = time.time()
        if (
            not force
            and now - float(EMBYFLOW_CACHE_LAST_TUNE or 0.0)
            < EMBYFLOW_CACHE_TUNE_INTERVAL
        ):
            result["skipped"] = 1
            return result
        EMBYFLOW_CACHE_LAST_TUNE = now
    except Exception:
        pass

    try:
        ensure_dir(CACHE_DIR)

        candidates = []
        total = 0

        for root, directories, files in os.walk(
            CACHE_DIR
        ):
            for filename in files:
                full_path = os.path.join(
                    root,
                    filename
                )

                try:
                    file_size = int(
                        os.path.getsize(full_path)
                    )

                    total += file_size
                    lower_name = filename.lower()

                    is_temporary = (
                        lower_name.endswith(
                            (".tmp", ".download")
                        )
                        or lower_name.startswith(
                            "hero_raw_"
                        )
                        or lower_name.startswith(
                            "raw_dynamic_"
                        )
                    )

                    if is_temporary:
                        try:
                            os.remove(full_path)
                            result["deleted"] += 1
                            result["freed"] += file_size
                            total -= file_size
                        except Exception:
                            pass

                        continue

                    if (
                        filename
                        in EMBYFLOW_CACHE_PROTECTED_NAMES
                        or lower_name.endswith(".json")
                    ):
                        continue

                    # EMBYFLOW_CACHE_HARD_LIMIT_V2
                    # Alle nicht geschützten Cache-Dateien dürfen bei
                    # Überschreitung nach Alter entfernt werden. Dadurch
                    # bleiben auch Dateien mit unbekannten Endungen nicht
                    # dauerhaft außerhalb der 100-MB-Begrenzung.
                    try:
                        access_time = max(
                            float(
                                os.path.getatime(
                                    full_path
                                )
                            ),
                            float(
                                os.path.getmtime(
                                    full_path
                                )
                            ),
                        )
                    except Exception:
                        access_time = 0.0

                    candidates.append(
                        (
                            access_time,
                            full_path,
                            file_size,
                        )
                    )

                except Exception:
                    pass

        result["before"] = (
            total + result["freed"]
        )

        if total > int(limit_bytes):
            candidates.sort(
                key=lambda entry: entry[0]
            )

            for access_time, full_path, file_size in candidates:
                if total <= int(limit_bytes):
                    break

                try:
                    os.remove(full_path)
                    total -= file_size
                    result["deleted"] += 1
                    result["freed"] += file_size
                except Exception:
                    pass

        result["after"] = max(0, total)

        try:
            with embyflow_open_log(
                "/tmp/embyflow_cache_tuning.log",
                "a"
            ) as log:
                log.write(
                    "before=%s after=%s "
                    "deleted=%s freed=%s "
                    "limit=%s\n"
                    % (
                        result["before"],
                        result["after"],
                        result["deleted"],
                        result["freed"],
                        int(limit_bytes),
                    )
                )
        except Exception:
            pass

    except Exception as error:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_cache_tuning_error.log",
                "a"
            ) as log:
                log.write(
                    "%s\n" % str(error)
                )
        except Exception:
            pass

    return result


def embyflow_cache_size_bytes():
    """Ermittelt die reale Summe der Dateigroessen im persistenten Cache."""
    total = 0

    try:
        ensure_dir(CACHE_DIR)

        for root, directories, files in os.walk(CACHE_DIR):
            for filename in files:
                full_path = os.path.join(root, filename)

                try:
                    total += int(os.path.getsize(full_path))
                except Exception:
                    pass

    except Exception:
        pass

    return max(0, int(total))


def embyflow_request_cache_tune(reason="image-batch"):
    """Fordert eine ruhige, gebuendelte und gedrosselte Nachbereinigung an."""
    global EMBYFLOW_CACHE_TUNE_REQUEST_LOCK
    global EMBYFLOW_CACHE_TUNE_REQUEST_PENDING
    global EMBYFLOW_CACHE_TUNE_REQUEST_DIRTY
    global EMBYFLOW_CACHE_TUNE_REQUEST_LAST_ACTIVITY
    global EMBYFLOW_CACHE_TUNE_REQUEST_LAST_REASON

    try:
        import threading

        if EMBYFLOW_CACHE_TUNE_REQUEST_LOCK is None:
            EMBYFLOW_CACHE_TUNE_REQUEST_LOCK = threading.RLock()

        with EMBYFLOW_CACHE_TUNE_REQUEST_LOCK:
            EMBYFLOW_CACHE_TUNE_REQUEST_DIRTY = True
            EMBYFLOW_CACHE_TUNE_REQUEST_LAST_ACTIVITY = time.time()
            EMBYFLOW_CACHE_TUNE_REQUEST_LAST_REASON = str(
                reason or "image-batch"
            )

            if EMBYFLOW_CACHE_TUNE_REQUEST_PENDING:
                return True

            EMBYFLOW_CACHE_TUNE_REQUEST_PENDING = True

        def tune_worker():
            global EMBYFLOW_CACHE_TUNE_REQUEST_PENDING
            global EMBYFLOW_CACHE_TUNE_REQUEST_DIRTY

            hard_retry_count = 0

            try:
                while True:
                    # Erst starten, wenn sowohl die globale 30-Sekunden-Sperre
                    # als auch zwei Sekunden Ruhe seit dem letzten Bild-Batch
                    # abgelaufen sind. Neue Requests setzen die Ruhezeit neu.
                    while True:
                        try:
                            now = time.time()

                            with EMBYFLOW_CACHE_TUNE_REQUEST_LOCK:
                                last_activity = float(
                                    EMBYFLOW_CACHE_TUNE_REQUEST_LAST_ACTIVITY
                                    or 0.0
                                )

                            tune_remaining = max(
                                0.0,
                                float(EMBYFLOW_CACHE_TUNE_INTERVAL)
                                - max(
                                    0.0,
                                    now
                                    - float(EMBYFLOW_CACHE_LAST_TUNE or 0.0)
                                )
                            )

                            quiet_remaining = max(
                                0.0,
                                float(EMBYFLOW_CACHE_AUTOTUNE_QUIET_SECONDS)
                                - max(0.0, now - last_activity)
                            )

                            wait_seconds = max(
                                tune_remaining,
                                quiet_remaining
                            )

                        except Exception:
                            wait_seconds = 0.0

                        if wait_seconds <= 0.0:
                            break

                        time.sleep(wait_seconds + 0.05)

                    # Alle bisherigen Anforderungen werden von diesem Scan
                    # abgedeckt. Nur neue Aktivitaet waehrend oder nach dem Scan
                    # setzt DIRTY erneut.
                    with EMBYFLOW_CACHE_TUNE_REQUEST_LOCK:
                        EMBYFLOW_CACHE_TUNE_REQUEST_DIRTY = False
                        run_reason = str(
                            EMBYFLOW_CACHE_TUNE_REQUEST_LAST_REASON
                            or reason
                            or "image-batch"
                        )

                    result = embyflow_tune_cache(
                        EMBYFLOW_CACHE_AUTOTUNE_TARGET_BYTES
                    ) or {}

                    if result.get("skipped"):
                        time.sleep(0.25)
                        continue

                    # Nachlaufende atomare Umbenennungen oder JSON-Schreibvorgaenge
                    # kurz auslaufen lassen und danach die echte Cachegroesse messen.
                    time.sleep(
                        max(
                            0.0,
                            float(EMBYFLOW_CACHE_AUTOTUNE_VERIFY_DELAY)
                        )
                    )

                    checked_size = embyflow_cache_size_bytes()
                    hard_exceeded = bool(
                        checked_size > EMBYFLOW_CACHE_LIMIT_BYTES
                    )
                    request_during_scan = False
                    repeat_scan = False

                    with EMBYFLOW_CACHE_TUNE_REQUEST_LOCK:
                        request_during_scan = bool(
                            EMBYFLOW_CACHE_TUNE_REQUEST_DIRTY
                        )

                        if hard_exceeded and hard_retry_count < 1:
                            hard_retry_count += 1
                            EMBYFLOW_CACHE_TUNE_REQUEST_DIRTY = True

                        repeat_scan = bool(
                            EMBYFLOW_CACHE_TUNE_REQUEST_DIRTY
                        )

                        if not repeat_scan:
                            EMBYFLOW_CACHE_TUNE_REQUEST_PENDING = False

                    try:
                        with embyflow_open_log(
                            "/tmp/embyflow_cache_autotune.log",
                            "a"
                        ) as log:
                            log.write(
                                "%s reason=%s before=%s after=%s "
                                "checked=%s target=%s hard=%s "
                                "deleted=%s freed=%s quiet=%.1f "
                                "new_request=%s hard_retry=%s repeat=%s\n"
                                % (
                                    time.strftime("%Y-%m-%d %H:%M:%S"),
                                    run_reason,
                                    int(result.get("before", 0) or 0),
                                    int(result.get("after", 0) or 0),
                                    int(checked_size or 0),
                                    int(EMBYFLOW_CACHE_AUTOTUNE_TARGET_BYTES),
                                    int(EMBYFLOW_CACHE_LIMIT_BYTES),
                                    int(result.get("deleted", 0) or 0),
                                    int(result.get("freed", 0) or 0),
                                    float(EMBYFLOW_CACHE_AUTOTUNE_QUIET_SECONDS),
                                    int(bool(request_during_scan)),
                                    int(hard_retry_count),
                                    int(bool(repeat_scan)),
                                )
                            )
                    except Exception:
                        pass

                    if repeat_scan:
                        # embyflow_tune_cache() hat den Zeitstempel gesetzt.
                        # Der naechste Lauf wartet deshalb automatisch erneut
                        # bis zum Ablauf der 30-Sekunden-Sperre.
                        continue

                    break

            except Exception as error:
                try:
                    with embyflow_open_log(
                        "/tmp/embyflow_cache_autotune_error.log",
                        "a"
                    ) as log:
                        log.write(
                            "%s reason=%s error=%s\n"
                            % (
                                time.strftime("%Y-%m-%d %H:%M:%S"),
                                str(reason or "image-batch"),
                                str(error),
                            )
                        )
                except Exception:
                    pass

                try:
                    with EMBYFLOW_CACHE_TUNE_REQUEST_LOCK:
                        EMBYFLOW_CACHE_TUNE_REQUEST_PENDING = False
                        EMBYFLOW_CACHE_TUNE_REQUEST_DIRTY = False
                except Exception:
                    EMBYFLOW_CACHE_TUNE_REQUEST_PENDING = False
                    EMBYFLOW_CACHE_TUNE_REQUEST_DIRTY = False

        worker = threading.Thread(
            target=tune_worker,
            name="EmbyFlowCacheAutoTune"
        )
        worker.daemon = True
        worker.start()
        return True

    except Exception:
        EMBYFLOW_CACHE_TUNE_REQUEST_PENDING = False
        EMBYFLOW_CACHE_TUNE_REQUEST_DIRTY = False

        try:
            embyflow_tune_cache(
                EMBYFLOW_CACHE_AUTOTUNE_TARGET_BYTES
            )
            return True
        except Exception:
            return False


# HOME_PERFORMANCE_TEST_PATCH_V1
EMBYFLOW_PERF_LOG = "/tmp/embyflow_perf.log"

def embyflow_perf_log(stage, started=None, **fields):
    if not EMBYFLOW_DEBUG_LOGS:
        return

    try:
        now = time.time() if "time" in globals() else __import__("time").time()
        parts = [
            __import__("time").strftime("%Y-%m-%d %H:%M:%S"),
            str(stage),
        ]
        if started is not None:
            parts.append("ms=%.1f" % ((now - float(started)) * 1000.0))
        for key in sorted(fields):
            parts.append("%s=%s" % (key, fields[key]))
        with embyflow_open_log(EMBYFLOW_PERF_LOG, "a") as log:
            log.write(" | ".join(parts) + "\n")
    except Exception:
        pass

# --- EmbyFlow dynamic MetrixHD scaling -------------------------------------
# Base layout is authored in Full-HD (1920x1080). MetrixHD commonly ships as
# 1280x720 skin. These helpers scale XML skin coordinates/fonts and all runtime
# ePoint/eSize moves from the same base grid. Colors use MetrixHD named colors
# such as layer-a-background, layer-b-background, layer-a-accent1 and RGYB.
BASE_W = 1920
BASE_H = 1080

def _embyflow_desktop_size():
    try:
        if embyflow_get_desktop_metrics is not None:
            metrics = embyflow_get_desktop_metrics(
                BASE_W,
                BASE_H
            )
            return (
                int(metrics.get("width") or BASE_W),
                int(metrics.get("height") or BASE_H),
            )
    except Exception:
        pass

    return BASE_W, BASE_H

SCREEN_W, SCREEN_H = _embyflow_desktop_size()
SCALE_X = float(SCREEN_W) / float(BASE_W)
SCALE_Y = float(SCREEN_H) / float(BASE_H)
SCALE_FONT = min(SCALE_X, SCALE_Y)

# DYNAMIC_RESOLUTION_SUPPORT_V17
SCREEN_RESOLUTION_KEY = "%dx%d" % (SCREEN_W, SCREEN_H)
IS_HD_SKIN = SCREEN_W <= 1280 or SCREEN_H <= 720
IS_FHD_SKIN = not IS_HD_SKIN

def sx(value):
    try:
        return int(round(float(value) * SCALE_X))
    except Exception:
        return int(value or 0)

def sy(value):
    try:
        return int(round(float(value) * SCALE_Y))
    except Exception:
        return int(value or 0)

def sf(value):
    try:
        v = int(round(float(value) * SCALE_FONT))
        return max(10, v)
    except Exception:
        return int(value or 0)

def EFP(x, y):
    return ePoint(sx(x), sy(y))

def EFS(w, h):
    return eSize(sx(w), sy(h))

EMBYFLOW_COLORS = {
    "layer-a-background": "#0C1827",
    "layer-b-background": "#102238",
    "layer-a-foreground": "#F2F5F8",
    "layer-b-foreground": "#D7DEE8",
    "layer-a-accent1": "#15B9FF",
    "layer-a-selection-background": "#173A5E",
    "layer-a-selection-foreground": "#FFFFFF",
}

def apply_embyflow_colors(skin):
    try:
        text = str(skin or "")
        for old_name in sorted(EMBYFLOW_COLORS, key=len, reverse=True):
            text = text.replace(old_name, EMBYFLOW_COLORS[old_name])
        return text
    except Exception:
        return skin

def scale_skin(skin):
    try:
        import re
        text = apply_embyflow_colors(skin)
        def repl_position(m):
            return 'position="%s,%s"' % (sx(m.group(1)), sy(m.group(2)))
        def repl_size(m):
            return 'size="%s,%s"' % (sx(m.group(1)), sy(m.group(2)))
        def repl_font(m):
            return 'font="%s;%s"' % (m.group(1), sf(m.group(2)))
        text = re.sub(r'position="(-?\d+),(-?\d+)"', repl_position, text)
        text = re.sub(r'size="(-?\d+),(-?\d+)"', repl_size, text)
        text = re.sub(r'font="([^";]+);(\d+)"', repl_font, text)
        return text
    except Exception:
        return apply_embyflow_colors(skin)
