def ensure_dir(path):
    try:
        if not os.path.exists(path):
            os.makedirs(path)
    except:
        pass


def read_json_file(path, default=None):
    try:
        f = open(path, "r")
        data = json.loads(f.read())
        f.close()
        return data
    except:
        return default


def write_json_file(path, data):
    # EMBYFLOW_ATOMIC_JSON_WRITE_V1
    # Erst vollständig in eine temporäre Datei im selben
    # Verzeichnis schreiben und anschließend atomar ersetzen.
    temporary_path = None

    try:
        target_path = str(path or "").strip()

        if not target_path:
            return False

        target_directory = os.path.dirname(
            target_path
        )

        if target_directory and not os.path.isdir(
            target_directory
        ):
            try:
                os.makedirs(
                    target_directory
                )
            except OSError:
                if not os.path.isdir(
                    target_directory
                ):
                    raise

        temporary_path = (
            target_path
            + ".tmp."
            + str(os.getpid())
            + "."
            + str(uuid4())
        )

        with open(
            temporary_path,
            "w",
            encoding="utf-8"
        ) as handle:
            json.dump(
                data,
                handle,
                ensure_ascii=False,
                separators=(",", ":")
            )

            handle.flush()

            try:
                os.fsync(
                    handle.fileno()
                )
            except Exception:
                pass

        try:
            os.replace(
                temporary_path,
                target_path
            )
        except AttributeError:
            # Kompatibilitäts-Fallback für ältere Python-Versionen.
            if os.path.exists(
                target_path
            ):
                os.remove(
                    target_path
                )

            os.rename(
                temporary_path,
                target_path
            )

        temporary_path = None
        return True

    except Exception:
        return False

    finally:
        if (
            temporary_path
            and os.path.exists(
                temporary_path
            )
        ):
            try:
                os.remove(
                    temporary_path
                )
            except Exception:
                pass


def embyflow_server_scope():
    """Stabiler kurzer Schlüssel für Daten des aktiven Emby-Servers und Benutzers."""
    try:
        import hashlib
        raw = "%s|%s" % (
            str(EMBY_SERVER or "").strip().rstrip("/").lower(),
            str(EMBY_USERNAME or "").strip().lower(),
        )
        if not raw.strip("|"):
            return "noserver"
        return hashlib.sha1(raw.encode("utf-8")).hexdigest()[:12]
    except Exception:
        try:
            return str(abs(hash((str(EMBY_SERVER or ""), str(EMBY_USERNAME or "")))))[:12]
        except Exception:
            return "noserver"

def get_emby_auth(force=False):
    if not requests or not EMBY_SERVER or not EMBY_USERNAME:
        return None, None, None
    server = EMBY_SERVER.rstrip("/")
    try:
        now_ts = int(time.time())
        if (not force and EMBY_AUTH_CACHE.get("server") == server and
                EMBY_AUTH_CACHE.get("token") and EMBY_AUTH_CACHE.get("user_id") and
                now_ts - int(EMBY_AUTH_CACHE.get("ts") or 0) < 21600):
            return server, EMBY_AUTH_CACHE.get("token"), EMBY_AUTH_CACHE.get("user_id")
    except:
        pass
    try:
        login = embyflow_http_post(
            server + "/Users/AuthenticateByName",
            headers={"X-Emby-Authorization": AUTH_HEADER},
            json={"Username": EMBY_USERNAME, "Pw": EMBY_PASSWORD},
            timeout=6,
            verify=True,
        )
        data = login.json()
        token = data.get("AccessToken")
        user_id = (data.get("User") or {}).get("Id")
        if token and user_id:
            EMBY_AUTH_CACHE["server"] = server
            EMBY_AUTH_CACHE["token"] = token
            EMBY_AUTH_CACHE["user_id"] = user_id
            EMBY_AUTH_CACHE["ts"] = int(time.time())
            return server, token, user_id
    except Exception as e:
        try:
            f = embyflow_open_log("/tmp/embyflow_auth_cache_error.log", "a")
            f.write("%s\n" % str(e))
            f.close()
        except:
            pass
    return server, None, None


def build_stream_url_by_id(item_id, mode="1080p_h264"):
    # EMBYFLOW_BETA84_CENTRAL_AUTH_STEP1_V1
    # Vorhandenen zentralen Token-Cache verwenden,
    # statt bei jedem Aufruf erneut anzumelden.
    server, token, user_id = get_emby_auth()

    if not server or not token:
        return TEST_STREAM_URL

    if mode == "1080p_h264":
        return (
            "%s/Videos/%s/stream.mp4?"
            "Static=false&VideoCodec=h264&AudioCodec=aac"
            "&MaxWidth=1920&MaxHeight=1080&VideoBitRate=6000000"
            "&AudioBitRate=192000&MaxAudioChannels=2&api_key=%s"
        ) % (server, item_id, token)

    return "%s/Videos/%s/stream.mkv?Static=true&api_key=%s" % (
        server,
        item_id,
        token,
    )


SAFE_DIRECT_AUDIO = ("aac", "mp3", "mp2", "ac3", "eac3")
RISKY_AUDIO = ("dts", "dca", "truehd", "mlp", "flac", "opus", "pcm")
RISKY_VIDEO = ("hevc", "h265", "av1", "vc1")


def audio_codec_is_safe(codec):
    codec = (codec or "").lower()
    return codec in SAFE_DIRECT_AUDIO


def audio_codec_is_risky(codec):
    codec = (codec or "").lower()
    return codec in RISKY_AUDIO or codec.startswith("pcm")


def audio_stream_text(stream):
    try:
        parts = [
            stream.get("Language", ""),
            stream.get("DisplayLanguage", ""),
            stream.get("Title", ""),
            stream.get("DisplayTitle", ""),
            stream.get("Codec", ""),
            stream.get("Profile", ""),
        ]
        return " ".join([str(x) for x in parts if x]).lower()
    except:
        return ""


def audio_stream_is_unwanted(stream):
    text = audio_stream_text(stream)
    bad_words = (
        "commentary", "comment", "kommentar", "director", "regisseur",
        "audio description", "audiodeskription", "descriptive", "beschreibung",
        "hearing impaired", "hoh", "sdh", "visually impaired",
    )
    for word in bad_words:
        if word in text:
            return True
    try:
        if stream.get("IsForced"):
            return True
    except:
        pass
    return False


def audio_stream_score(stream, default_index=None):
    try:
        lang = (stream.get("Language") or stream.get("DisplayLanguage") or "").lower()
        codec = (stream.get("Codec") or "").lower()
        channels = int(stream.get("Channels") or 0)
        stream_index = stream.get("Index")
        score = 0

        if lang in ("ger", "de", "deu", "german", "deutsch"):
            score += 10000
        elif lang in ("eng", "en", "english"):
            score += 1000

        if audio_stream_is_unwanted(stream):
            score -= 20000

        if codec in ("ac3", "eac3"):
            score += 3000
        elif codec in ("aac", "mp3", "mp2"):
            score += 2500
        elif codec in ("dts", "dca", "truehd", "mlp"):
            score -= 5000
        elif audio_codec_is_risky(codec):
            score -= 5000

        if channels >= 6:
            score += 700
        elif channels == 2:
            score += 200
        elif channels == 1:
            score -= 100

        if stream.get("IsDefault"):
            score += 80
        if default_index is not None and stream_index == default_index:
            score += 40
        return score
    except:
        return -999999


def audio_stream_is_safe_direct(stream):
    try:
        codec = (stream.get("Codec") or "").lower()
        return codec in ("ac3", "eac3", "aac", "mp3", "mp2") and not audio_stream_is_unwanted(stream)
    except:
        return False


def video_stream_is_risky(stream):
    try:
        codec = (stream.get("Codec") or "").lower()
        video_text = " ".join([
            str(stream.get("VideoRange") or ""),
            str(stream.get("VideoRangeType") or ""),
            str(stream.get("DisplayTitle") or ""),
            str(stream.get("Profile") or ""),
        ]).lower().replace(" ", "")
        if codec in RISKY_VIDEO:
            return True
        if "dolbyvision" in video_text or "dovi" in video_text:
            return True
        if (stream.get("BitDepth") or 0) >= 10:
            return True
        if (stream.get("Height") or 0) >= 2160:
            return True
    except:
        pass
    return False


def preferred_safe_audio_index(source):
    try:
        streams = source.get("MediaStreams") or []
        default_index = source.get("DefaultAudioStreamIndex")
        best = None
        # Deutsch immer bevorzugen. Wenn Deutsch DTS/HD/Risky ist:
        # trotzdem Deutsch wählen, aber Audio-Transcode erzwingen.
        for pos, stream in enumerate(streams):
            if stream.get("Type") != "Audio":
                continue
            lang = (stream.get("Language") or stream.get("DisplayLanguage") or "").lower()
            title = (stream.get("DisplayTitle") or stream.get("Title") or "").lower()
            if lang in ("ger", "de", "deu", "german", "deutsch") or "deutsch" in title or "german" in title:
                stream_index = stream.get("Index")
                if stream_index is None:
                    stream_index = pos
                if not audio_stream_is_safe_direct(stream):
                    source["EmbyFlowForceAudioTranscode"] = True
                return stream_index

        for pos, stream in enumerate(streams):
            if stream.get("Type") != "Audio":
                continue
            if not audio_stream_is_safe_direct(stream):
                continue
            stream_index = stream.get("Index")
            if stream_index is None:
                stream_index = pos
            score = audio_stream_score(stream, default_index)
            if best is None or score > best[0]:
                best = (score, stream_index, stream)
        if best is not None:
            try:
                f = embyflow_open_log("/tmp/embyflow_audio_choice.log", "a")
                f.write("selected index=%s score=%s title=%s lang=%s codec=%s channels=%s default=%s\n" % (
                    best[1], best[0],
                    best[2].get("DisplayTitle") or best[2].get("Title") or "",
                    best[2].get("Language") or best[2].get("DisplayLanguage") or "",
                    best[2].get("Codec") or "",
                    best[2].get("Channels") or "",
                    default_index,
                ))
                f.close()
            except:
                pass
            return best[1]
        return None
    except:
        return None


def source_has_safe_direct_audio(source):
    try:
        for stream in source.get("MediaStreams") or []:
            if stream.get("Type") == "Audio" and audio_stream_is_safe_direct(stream):
                return True
    except:
        pass
    return False


def source_has_risky_audio(source):
    try:
        for stream in source.get("MediaStreams") or []:
            if stream.get("Type") == "Audio" and audio_codec_is_risky(stream.get("Codec")):
                return True
    except:
        pass
    return False


def subtitle_stream_score(stream):
    try:
        lang = (stream.get("Language") or stream.get("DisplayLanguage") or "").lower()
        text = " ".join([
            str(stream.get("Title") or ""),
            str(stream.get("DisplayTitle") or ""),
            str(stream.get("Codec") or ""),
        ]).lower()
        score = 0
        if lang in ("ger", "de", "deu", "german", "deutsch"):
            score += 10000
        elif lang in ("eng", "en", "english"):
            score += 1000
        if stream.get("IsDefault"):
            score += 500
        if stream.get("IsForced"):
            score += 200
        if "sdh" in text or "hearing impaired" in text or "hoh" in text:
            score -= 1000
        return score
    except:
        return -999999


def preferred_german_subtitle_index(source):
    try:
        best = None
        for pos, stream in enumerate(source.get("MediaStreams") or []):
            if stream.get("Type") != "Subtitle":
                continue
            score = subtitle_stream_score(stream)
            lang = (stream.get("Language") or stream.get("DisplayLanguage") or "").lower()
            if lang not in ("ger", "de", "deu", "german", "deutsch"):
                continue
            stream_index = stream.get("Index")
            if stream_index is None:
                stream_index = pos
            if best is None or score > best[0]:
                best = (score, stream_index)
        return best[1] if best else None
    except:
        return None


def enrich_media_source_for_player(item):
    try:
        media_sources = item.get("MediaSources") or []
        if not media_sources:
            return
        source = media_sources[0]
        streams = source.get("MediaStreams") or []
        audio_index = source.get("DefaultAudioStreamIndex")
        subtitle_index = source.get("DefaultSubtitleStreamIndex")
        safe_audio_index = preferred_safe_audio_index(source)
        if safe_audio_index is not None:
            source["DefaultAudioStreamIndex"] = safe_audio_index
            source["EmbyFlowForceAudioTranscode"] = bool(source.get("EmbyFlowForceAudioTranscode"))
        elif audio_index is None or audio_index < 0:
            for idx, stream in enumerate(streams):
                if stream.get("Type") == "Audio":
                    source["DefaultAudioStreamIndex"] = stream.get("Index", idx)
                    break
            source["EmbyFlowForceAudioTranscode"] = True
        else:
            source["EmbyFlowForceAudioTranscode"] = True
        if source.get("EmbyFlowForceAudioTranscode"):
            selected_audio = source.get("DefaultAudioStreamIndex")
            for stream in streams:
                if stream.get("Type") == "Audio" and stream.get("Index") == selected_audio:
                    lang = (stream.get("Language") or stream.get("DisplayLanguage") or "").lower()
                    label_lang = "German" if lang in ("ger", "de", "deu") else (stream.get("DisplayLanguage") or stream.get("Language") or "")
                    display = ("%s AAC 5.1 (Transcode)" % label_lang).strip()
                    stream["Codec"] = "aac"
                    stream["Channels"] = min(int(stream.get("Channels") or 6), 6)
                    stream["DisplayTitle"] = display
                    stream["Title"] = "AAC 5.1 (Transcode)"
                    break
        selected_audio_lang = ""
        try:
            selected_audio = source.get("DefaultAudioStreamIndex")
            for stream in streams:
                if stream.get("Type") == "Audio" and stream.get("Index") == selected_audio:
                    selected_audio_lang = (stream.get("Language") or stream.get("DisplayLanguage") or "").lower()
                    break
        except:
            selected_audio_lang = ""
        if selected_audio_lang and selected_audio_lang not in ("ger", "de", "deu", "german", "deutsch"):
            german_subtitle_index = preferred_german_subtitle_index(source)
            if german_subtitle_index is not None:
                source["DefaultSubtitleStreamIndex"] = german_subtitle_index
        if source.get("DefaultSubtitleStreamIndex") is None:
            source["DefaultSubtitleStreamIndex"] = -1
        for stream in streams:
            if stream.get("Type") == "Video":
                item["Width"] = stream.get("Width") or item.get("Width") or 0
                item["Height"] = stream.get("Height") or item.get("Height") or 0
                break
    except:
        pass


def item_has_dolby_vision(item):
    try:
        if not isinstance(item, dict):
            return False
        text_parts = [
            item.get("title", ""),
            item.get("Name", ""),
            item.get("meta", ""),
            item.get("video_label", ""),
        ]
        for source in item.get("media_sources") or item.get("MediaSources") or []:
            text_parts.extend([
                source.get("Name", ""),
                source.get("Container", ""),
                source.get("VideoType", ""),
            ])
            for stream in source.get("MediaStreams") or []:
                if stream.get("Type") == "Video":
                    text_parts.extend([
                        stream.get("Codec", ""),
                        stream.get("Profile", ""),
                        stream.get("VideoRange", ""),
                        stream.get("VideoRangeType", ""),
                        stream.get("DisplayTitle", ""),
                    ])
        haystack = " ".join([str(part) for part in text_parts if part]).lower()
        compact = haystack.replace(" ", "").replace("-", "")
        return "dolbyvision" in compact or "dovi" in compact or "dvhe" in compact
    except:
        return False


def item_has_dts_audio(item):
    try:
        if not isinstance(item, dict):
            return False
        text_parts = [
            item.get("title", ""),
            item.get("Name", ""),
            item.get("meta", ""),
            item.get("audio_label", ""),
        ]
        for source in item.get("media_sources") or item.get("MediaSources") or []:
            text_parts.extend([source.get("Name", ""), source.get("Container", "")])
            for stream in source.get("MediaStreams") or []:
                if stream.get("Type") == "Audio":
                    text_parts.extend([
                        stream.get("Codec", ""),
                        stream.get("Profile", ""),
                        stream.get("DisplayTitle", ""),
                    ])
        compact = " ".join([str(part) for part in text_parts if part]).lower().replace(" ", "").replace("-", "")
        return "dts" in compact or "dca" in compact
    except:
        return False


def item_needs_compatible_stream(item):
    try:
        if not isinstance(item, dict):
            return False
        for source in item.get("media_sources") or item.get("MediaSources") or []:
            video_risky = False
            for stream in source.get("MediaStreams") or []:
                if stream.get("Type") == "Video" and video_stream_is_risky(stream):
                    video_risky = True
                    break
            if video_risky:
                return True
            if source_has_safe_direct_audio(source):
                return False
            if source_has_risky_audio(source):
                return True
        return False
    except:
        return False


def build_compatible_stream_url(server, item_id, token, mode):
    # EMBYFLOW_R1_FORCE_REENCODE_NO_STREAMCOPY
    # Wenn Quelle bereits h264 ist, kopiert der Server den Video-Stream
    # sonst 1:1 (Stream Copy) und ignoriert dabei MaxWidth/MaxHeight -
    # die Box bekommt weiter die native (zu breite) Aufloesung und zeigt
    # nur Ton, kein Bild (siehe Mad Heidi, 2048px Breite). AllowVideoStreamCopy=false
    # erzwingt echtes Neu-Enkodieren, auch bei gleichem Quell-/Zielcodec.
    return (
        "%s/Videos/%s/stream.mp4?"
        "Static=false&VideoCodec=h264&AudioCodec=aac"
        "&EnableAutoStreamCopy=false"
        "&MaxWidth=1920&MaxHeight=1080&VideoBitRate=6000000"
        "&AudioBitRate=192000&MaxAudioChannels=2"
        "&AllowVideoStreamCopy=false&api_key=%s"
    ) % (server, item_id, token)


# EMBYFLOW_SERVER_DECISION_HLS_PROFILE_TEST5_V1
def embyflow_server_decision_hls_test5(
    server,
    item_id,
    token,
    user_id,
    fallback_media_source_id,
    audio_index,
    play_session_id,
    start_ticks=0
):
    # EMBYFLOW_ADMIN_SAFETY_V2_PLAYBACKINFO_POST
    # PlaybackInfo ist eine Wiedergabeentscheidung und wird deshalb per POST
    # mit einem echten DeviceProfile angefragt. Der Server kann dadurch seine
    # Benutzer-/Transcoding-Policy anwenden. Eine abgelehnte oder unvollstaendige
    # Entscheidung wird NICHT durch eine selbst gebaute Transcode-URL umgangen.
    decision = {
        "url": "",
        "media_source_id": str(fallback_media_source_id or ""),
        "supports_direct_play": None,
        "supports_direct_stream": None,
        "supports_transcoding": None,
        "source_container": "",
        "source_video_codec": "",
        "source_video_profile": "",
        "source_width": 0,
        "source_height": 0,
        "http_status": 0,
        "policy_allowed": False,
        "error": "",
        "play_session_id": str(play_session_id or ""),
        "playbackinfo_method": "POST",
        "start_ticks": 0,
    }

    try:
        start_ticks = max(0, int(start_ticks or 0))
    except Exception:
        start_ticks = 0
    decision["start_ticks"] = start_ticks

    server_base = str(server or "").rstrip("/")
    headers = {
        "X-Emby-Authorization": AUTH_HEADER,
        "X-Emby-Token": str(token or ""),
        "Cache-Control": "no-cache",
        "Pragma": "no-cache",
        "Content-Type": "application/json",
    }

    # Dieses Profil beschreibt ausschliesslich den bereits vorhandenen
    # HLS/H.264/AAC-Kompatibilitaetspfad. Direct Play/Direct Stream werden in
    # DIESER Funktion bewusst nicht angeboten, weil sie nur aufgerufen wird,
    # wenn EmbyFlow bereits einen Video-Transcode benoetigt.
    device_profile = {
        "Name": "EmbyFlowE2 Enigma2 HLS H264",
        "MaxStreamingBitrate": 6200000,
        "MusicStreamingTranscodingBitrate": 192000,
        "DirectPlayProfiles": [],
        "TranscodingProfiles": [
            {
                "Container": "ts",
                "Type": "Video",
                "VideoCodec": "h264",
                "AudioCodec": "aac",
                "Protocol": "hls",
                "Context": "Streaming",
                "MaxAudioChannels": "2",
                "MinSegments": 1,
                "BreakOnNonKeyFrames": False,
            }
        ],
        "ContainerProfiles": [],
        "CodecProfiles": [],
        "SubtitleProfiles": [
            {
                "Format": "vtt",
                "Method": "External",
            }
        ],
        "ResponseProfiles": [],
    }

    request_body = {
        "UserId": str(user_id or ""),
        "IsPlayback": True,
        "AutoOpenLiveStream": False,
        "EnableDirectPlay": False,
        "EnableDirectStream": False,
        "EnableTranscoding": True,
        "AllowVideoStreamCopy": False,
        "AllowAudioStreamCopy": False,
        "CurrentPlaySessionId": str(play_session_id or ""),
        "DeviceProfile": device_profile,
    }

    if fallback_media_source_id:
        request_body["MediaSourceId"] = str(fallback_media_source_id)

    # EMBYFLOW_REF15_HLS_SERVER_RESUME_LOCALTEST
    # Kein weiterer Serverrequest: die Resume-Position wird in die ohnehin
    # notwendige PlaybackInfo-Entscheidung eingebracht.
    if start_ticks > 0:
        request_body["StartTimeTicks"] = int(start_ticks)

    if audio_index is not None:
        try:
            request_body["AudioStreamIndex"] = int(audio_index)
        except Exception:
            request_body["AudioStreamIndex"] = audio_index

    try:
        response = embyflow_http_post(
            "%s/Items/%s/PlaybackInfo" % (
                server_base,
                str(item_id or "")
            ),
            headers=headers,
            json=request_body,
            timeout=10,
            verify=True,
        )

        status_code = int(
            getattr(response, "status_code", 0)
            or 0
        )
        decision["http_status"] = status_code

        if status_code != 200:
            decision["error"] = "PlaybackInfo HTTP %s" % status_code
            return decision

        payload = response.json() or {}
        returned_session_id = str(
            payload.get("PlaySessionId")
            or play_session_id
            or ""
        )
        decision["play_session_id"] = returned_session_id
        sources = payload.get("MediaSources") or []

        selected = None
        if fallback_media_source_id:
            for candidate in sources:
                if str(candidate.get("Id") or "") == str(fallback_media_source_id):
                    selected = candidate
                    break

        if selected is None and sources:
            selected = sources[0]

        if selected is None:
            decision["error"] = "PlaybackInfo ohne MediaSource"
            return decision

        decision["media_source_id"] = str(
            selected.get("Id") or fallback_media_source_id or ""
        )
        decision["supports_direct_play"] = selected.get("SupportsDirectPlay")
        decision["supports_direct_stream"] = selected.get("SupportsDirectStream")
        decision["supports_transcoding"] = selected.get("SupportsTranscoding")
        decision["source_container"] = str(selected.get("Container") or "")

        for stream in selected.get("MediaStreams") or []:
            if str(stream.get("Type") or "").lower() != "video":
                continue
            decision["source_video_codec"] = str(stream.get("Codec") or "")
            decision["source_video_profile"] = str(stream.get("Profile") or "")
            try:
                decision["source_width"] = int(stream.get("Width") or 0)
            except Exception:
                pass
            try:
                decision["source_height"] = int(stream.get("Height") or 0)
            except Exception:
                pass
            break

        # Wichtig fuer die Admin-Safety: Wenn der Server Transcoding nicht
        # freigibt, wird keine eigene URL als Ersatz gebaut.
        if selected.get("SupportsTranscoding") is False:
            decision["error"] = "Server erlaubt fuer diese Quelle kein Transcoding"
            return decision

        transcoding_url = str(
            selected.get("TranscodingUrl")
            or ""
        ).strip()

        if not transcoding_url:
            decision["error"] = "PlaybackInfo lieferte keine TranscodingUrl"
            return decision

        if transcoding_url.lower().startswith(("http://", "https://")):
            resolved_url = transcoding_url
        elif transcoding_url.startswith("/"):
            resolved_url = server_base + transcoding_url
        else:
            resolved_url = server_base + "/" + transcoding_url

        # Enigma2/GStreamer kann den X-Emby-Token-Header beim eigentlichen
        # Service-Start nicht verlaesslich mitsenden. Deshalb bleibt die bisher
        # verwendete URL-Authentifizierung fuer den Stream erhalten.
        lowered_url = resolved_url.lower()
        if "api_key=" not in lowered_url and "x-emby-token=" not in lowered_url:
            joiner = "&" if "?" in resolved_url else "?"
            resolved_url += "%sapi_key=%s" % (
                joiner,
                str(token or "")
            )

        if start_ticks > 0:
            resolved_url = url_with_start_ticks(
                resolved_url,
                start_ticks
            )

        decision["url"] = resolved_url
        decision["policy_allowed"] = True

    except Exception as error:
        decision["error"] = "PlaybackInfo POST: %s" % str(error)
        try:
            with open(
                "/tmp/embyflow_madheidi_serverdecision_test5_error.log", "a"
            ) as handle:
                handle.write("PlaybackInfo POST: %s\n" % str(error))
        except Exception:
            pass

    try:
        with embyflow_open_log("/tmp/embyflow_madheidi_serverdecision_test5.log", "w") as handle:
            handle.write(
                "mode=server-decision-hls\n"
                "playbackinfo_method=%s\n"
                "start_ticks=%s\n"
                "http_status=%s\n"
                "policy_allowed=%s\n"
                "error=%s\n"
                "item=%s\n"
                "media_source=%s\n"
                "supports_direct_play=%s\n"
                "supports_direct_stream=%s\n"
                "supports_transcoding=%s\n"
                "container=%s\n"
                "video_codec=%s\n"
                "video_profile=%s\n"
                "width=%s\n"
                "height=%s\n"
                "target_h264_profiles=server-profile\n"
                "service_type=%s\n"
                "url=%s\n"
                % (
                    decision["playbackinfo_method"],
                    decision["start_ticks"],
                    decision["http_status"],
                    decision["policy_allowed"],
                    decision["error"],
                    str(item_id or ""),
                    decision["media_source_id"],
                    decision["supports_direct_play"],
                    decision["supports_direct_stream"],
                    decision["supports_transcoding"],
                    decision["source_container"],
                    decision["source_video_codec"],
                    decision["source_video_profile"],
                    decision["source_width"],
                    decision["source_height"],
                    STREAM_SERVICE_TYPE,
                    embyflow_sanitize_url_for_log(decision["url"]),
                )
            )
    except Exception:
        pass

    return decision

def pick_best_audio_stream(item):
    best = None
    for src in item.get("MediaSources", []) or []:
        default_index = src.get("DefaultAudioStreamIndex")
        for st in src.get("MediaStreams", []) or []:
            if st.get("Type") != "Audio":
                continue
            score = audio_stream_score(st, default_index)
            if best is None or score > best[0]:
                best = (score, src, st)
    return best[1:] if best else (None, None)


def build_direct_mkv_stream_url(
    server,
    item_id,
    token,
    media_source_id=None,
    audio_index=None,
    subtitle_index=None
):
    # EMBYFLOW_RC14_CENTRAL_STREAM_STRATEGY_V1
    if embyflow_build_static_stream_url is not None:
        return embyflow_build_static_stream_url(
            server,
            item_id,
            token,
            media_source_id,
            audio_index,
            subtitle_index,
            "mkv"
        )

    params = ["Static=true"]

    if media_source_id:
        params.append(
            "MediaSourceId=%s" % str(media_source_id)
        )

    if audio_index is not None:
        params.append(
            "AudioStreamIndex=%s" % str(audio_index)
        )

    try:
        subtitle_value = int(subtitle_index)
    except Exception:
        subtitle_value = -1

    if subtitle_value >= 0:
        params.append(
            "SubtitleStreamIndex=%s" % subtitle_value
        )

    params.append("api_key=%s" % str(token or ""))

    return "%s/Videos/%s/stream.mkv?%s" % (
        str(server or "").rstrip("/"),
        item_id,
        "&".join(params),
    )




def build_audio_selected_stream_url(server, item_id, token, media_source_id, audio_index, audio_codec=None, max_channels=6):
    params = [
        "Static=false",
        "AudioStreamIndex=%s" % audio_index,
        "MaxAudioChannels=%s" % max_channels,
    ]
    if media_source_id:
        params.append("MediaSourceId=%s" % media_source_id)
    if audio_codec:
        params.append("AudioCodec=%s" % audio_codec)
    params.append("api_key=%s" % token)
    return "%s/Videos/%s/stream.ts?%s" % (server, item_id, "&".join(params))


def add_stream_session_params(url, play_session_id):
    # EMBYFLOW_RC14_CENTRAL_SESSION_PARAMS_V1
    if embyflow_add_session_params is not None:
        return embyflow_add_session_params(
            url,
            play_session_id,
            "embyflowe2"
        )

    try:
        extra = "DeviceId=embyflowe2&PlaySessionId=%s" % str(
            play_session_id or ""
        )
        if "PlaySessionId=" in url:
            return url
        joiner = "&" if "?" in url else "?"
        return url + joiner + extra
    except Exception:
        return url


# STREAM_LOG_TOKEN_REDACTION_V2
def embyflow_sanitize_url_for_log(url):
    try:
        value = str(url or "")

        value = re.sub(
            r'(?i)([?&](?:api_key|token|access_token|'
            r'x-emby-token|playsessionid)=)[^&\s]*',
            r'\1***',
            value,
        )

        value = re.sub(
            r'(?i)(X-Emby-Token\s*[:=]\s*)[^,;\s]+',
            r'\1***',
            value,
        )

        return value

    except Exception:
        return "[URL maskiert]"


def url_with_start_ticks(url, target_ticks):
    # EMBYFLOW_RC14_CENTRAL_START_TICKS_V1
    if embyflow_add_start_ticks is not None:
        return embyflow_add_start_ticks(
            url,
            target_ticks
        )

    try:
        value = str(url or "")
        if not value:
            return value
        if "?" in value:
            path, query = value.split("?", 1)
            kept = []
            for part in query.split("&"):
                if not part:
                    continue
                if part.split("=", 1)[0].lower() == "starttimeticks":
                    continue
                kept.append(part)
            kept.append("StartTimeTicks=%s" % int(target_ticks or 0))
            return path + "?" + "&".join(kept)
        return value + "?StartTimeTicks=%s" % int(target_ticks or 0)
    except Exception:
        return url


def playback_badges(playback_info=None):
    item = (playback_info or {}).get("item") or {}
    fsk = item.get("OfficialRating") or item.get("official_rating") or "FSK"
    audio_label = "AAC 2.0"
    video_label = "1080P H264"
    try:
        for source in item.get("MediaSources") or item.get("media_sources") or []:
            audio_stream = None
            default_audio_index = source.get("DefaultAudioStreamIndex")
            for stream in source.get("MediaStreams") or []:
                if stream.get("Type") != "Audio":
                    continue
                stream_index = stream.get("Index")
                if stream_index is None:
                    stream_index = (source.get("MediaStreams") or []).index(stream)
                if default_audio_index is not None and stream_index == default_audio_index:
                    audio_stream = stream
                    break
                if audio_stream is None and audio_codec_is_safe(stream.get("Codec")):
                    audio_stream = stream
            if audio_stream is None:
                for stream in source.get("MediaStreams") or []:
                    if stream.get("Type") == "Audio":
                        audio_stream = stream
                        break
            if audio_stream is not None:
                lang = audio_stream.get("Language") or audio_stream.get("DisplayLanguage") or ""
                codec = (audio_stream.get("Codec") or "").upper()
                channels = audio_stream.get("Channels") or 0
                parts = []
                if lang:
                    parts.append(lang)
                if codec:
                    parts.append(codec)
                if channels:
                    parts.append("%s.0" % channels if int(channels) <= 2 else "%s.1" % max(1, int(channels) - 1))
                if parts:
                    audio_label = " ".join(parts)
            for stream in source.get("MediaStreams") or []:
                if stream.get("Type") == "Video":
                    h = stream.get("Height") or 0
                    codec = (stream.get("Codec") or "").upper()
                    vrange = stream.get("VideoRange") or ""
                    parts = []
                    if h:
                        parts.append("4K" if h >= 2160 else "%sP" % h)
                    if vrange:
                        parts.append(str(vrange).upper().replace("DOLBYVISION", "DOLBY VISION"))
                    if codec:
                        parts.append(codec)
                    if parts:
                        video_label = " ".join(parts)
                    break
    except:
        pass
    if (playback_info or {}).get("force_url"):
        audio_label = "AAC 2.0"
        video_label = "1080P H264"
    return str(fsk), str(audio_label), str(video_label)


# EMBYFLOW_PERFORMANCE_PATCH23_STREAM_INFO_REUSE_V1
def fetch_stream_info(
    search_term=None,
    audio_mode="direct",
    item_id=None,
    item_data=None
):
    if not requests or not EMBY_SERVER or not EMBY_USERNAME:
        return None

    started_ts = time.time()
    server, token, user_id = get_emby_auth()

    if not token or not user_id:
        return None

    headers = {
        "X-Emby-Authorization": AUTH_HEADER,
        "X-Emby-Token": token,
    }

    candidate_items = []

    # Detail-, Grid- und A-Z-Daten enthalten MediaSources bereits. In diesem
    # Fall ist vor dem Playerstart keine zweite synchrone Item-Abfrage nötig.
    try:
        import copy

        prepared_item = copy.deepcopy(
            item_data
        ) if isinstance(item_data, dict) else None

        if prepared_item:
            prepared_sources = (
                prepared_item.get("MediaSources")
                or prepared_item.get("media_sources")
                or []
            )

            prepared_id = str(
                prepared_item.get("Id")
                or prepared_item.get("id")
                or item_id
                or ""
            ).strip()

            prepared_type_raw = str(
                prepared_item.get("Type")
                or prepared_item.get("type")
                or prepared_item.get("item_type")
                or ""
            ).strip()
            prepared_type = {
                "movie": "Movie",
                "video": "Video",
                "episode": "Episode",
                "audio": "Audio",
            }.get(
                prepared_type_raw.lower(),
                prepared_type_raw
            )

            if (
                prepared_id
                and prepared_sources
                and prepared_type in (
                    "Movie",
                    "Video",
                    "Episode",
                    "Audio",
                )
            ):
                prepared_item["Id"] = prepared_id
                prepared_item["Type"] = prepared_type
                prepared_item["MediaSources"] = prepared_sources
                prepared_item.setdefault(
                    "Name",
                    prepared_item.get("title")
                    or search_term
                    or ""
                )
                candidate_items = [prepared_item]

    except Exception:
        candidate_items = []

    if not candidate_items and item_id:
        item_response = embyflow_cached_get_json(
            server + "/Users/%s/Items/%s"
            % (user_id, item_id),
            headers=headers,
            params={
                "Fields": (
                    "MediaSources,OfficialRating,Overview,"
                    "Genres,ProductionYear,RunTimeTicks,UserData,"
                    "SeriesId,SeasonId,ParentId,ParentIndexNumber,"
                    "IndexNumber,SeriesName,SortName"
                )
            },
            ttl=120,
            timeout=8,
            verify=True,
            cache_key="stream-item-%s" % str(item_id),
        )
        candidate_items = [item_response]

    elif not candidate_items:
        search_response = embyflow_cached_get_json(
            server + "/Users/%s/Items" % user_id,
            headers=headers,
            params={
                "SearchTerm": search_term,
                "Recursive": "true",
                "Limit": "10",
                "IncludeItemTypes": "Movie,Video,Episode,Audio",
                "Fields": (
                    "MediaSources,OfficialRating,"
                    "RunTimeTicks,UserData,SeriesId,SeasonId,"
                    "ParentId,ParentIndexNumber,IndexNumber,"
                    "SeriesName,SortName"
                ),
            },
            ttl=45,
            timeout=8,
            verify=True,
            cache_key="stream-search-%s" % str(
                search_term or ""
            ),
        )
        candidate_items = (
            search_response.get("Items", [])
            or []
        )

    for item in candidate_items:
        item_id = item.get("Id")

        # EMBYFLOW_AUDIO_PLAYER_V1_STREAM
        # Audio is isolated from the established video/transcode path.
        if item_id and item.get("Type") == "Audio":
            media_sources = item.get("MediaSources") or []
            source = media_sources[0] if media_sources else {}
            container = str(source.get("Container") or item.get("Container") or "").strip().lower()
            ext = re.sub(r"[^a-z0-9]", "", container)
            endpoint = "%s/Audio/%s/stream" % (server, item_id)
            if ext:
                endpoint += "." + ext
            stream_url = (
                endpoint
                + "?Static=true&api_key=%s" % token
            )
            item["EmbyFlowPlaybackMode"] = "audio-direct"
            return {
                "url": stream_url,
                "server": server,
                "token": token,
                "user_id": user_id,
                "item": item,
                "force_url": True,
                "play_session_id": str(uuid4()),
                "playback_mode": "audio-direct",
                "server_resume_ticks": 0,
                "audio_port": "mediaplugins2026-port1",
            }

        if item_id and item.get("Type") in ("Movie", "Video", "Episode"):
            enrich_media_source_for_player(item)
            force_transcode = False
            force_url = False
            try:
                # Kein automatischer AAC-2.0-Zwang bei Direct Play.
                # Direct bleibt Direct; AAC nur noch bei audio_mode == "aac".
                if False and item_needs_compatible_stream(item):
                    force_transcode = "video_h264"
                    force_url = True
                for src in item.get("MediaSources", []) or []:
                    for st in src.get("MediaStreams", []) or []:
                        if st.get("Type") == "Video":
                            height = st.get("Height") or 0
                            width = st.get("Width") or 0
                            bitdepth = st.get("BitDepth") or 0
                            videorange = st.get("VideoRange") or ""
                            codec = st.get("Codec") or ""
                            # Test: Direct Play nicht automatisch wegen 4K/10bit/DV/AV1 auf AAC 2.0 zwingen.
                            # AAC-Fallback nur noch manuell ueber audio_mode == "aac".
                            # EMBYFLOW_4K_SERVER_TRANSCODE_V1
                            codec = str(codec or "").strip().lower()
                            videorange = str(videorange or "")
                            videorange_lower = videorange.lower()

                            try:
                                width = int(width or 0)
                            except Exception:
                                width = 0
                            try:
                                height = int(height or 0)
                            except Exception:
                                height = 0
                            try:
                                bitdepth = int(bitdepth or 0)
                            except Exception:
                                bitdepth = 0

                            # EMBYFLOW_H264_WIDTH_GUARD_V9_2
                            # VU+ Duo 4K SE: H.264-Quellen mit mehr als 1920 Pixeln
                            # Breite koennen trotz gueltigem H.264/AAC-Direct-Play
                            # nur Ton und ein schwarzes Bild liefern. Der bisherige
                            # Test war faelschlich auf eine einzelne Produktions-ID
                            # (587869) beschraenkt und griff deshalb auf dem Dev-Server
                            # fuer Mad Heidi (Item 1447, 2048x856) nicht.
                            # Solche Quellen gehen jetzt durch den bereits vorhandenen
                            # admin-sicheren POST PlaybackInfo -> HLS/H.264-Pfad, der
                            # MaxWidth=1920 und AllowVideoStreamCopy=false vorgibt.
                            h264_width_over_limit = (
                                codec in ("h264", "h.264", "avc")
                                and width > 1920
                            )

                            if h264_width_over_limit:
                                force_transcode = "video_h264"
                                force_url = True
                                try:
                                    f = embyflow_open_log(
                                        "/tmp/embyflow_h264_width_guard.log",
                                        "a"
                                    )
                                    f.write(
                                        "FORCE item=%s codec=%s width=%s height=%s max_width=1920\n"
                                        % (
                                            str(item_id or ""),
                                            str(codec or ""),
                                            str(width),
                                            str(height),
                                        )
                                    )
                                    f.close()
                                except Exception:
                                    pass

                            # EMBYFLOW_DREAMSAFE_VIDEO_V1
                            # Dreambox reference behavior: hardware-decodable
                            # HEVC/H.265 (including 2160p/Main10 and HEVC Dolby
                            # Vision sources) stays on the original Static=true
                            # stream.  Do NOT turn 4K alone into a server-side
                            # H.264 encode.  This reduces server transcoding-temp
                            # pressure and keeps the existing Stopped +
                            # ActiveEncodings cleanup as defense-in-depth.
                            hevc_native = codec in (
                                "hevc", "h265", "h.265", "hev1", "hvc1"
                            )
                            dolby_vision = (
                                "dolbyvision" in videorange_lower
                                or "dovi" in videorange_lower
                                or "dvhe" in videorange_lower
                            )

                            # AV1 is not hardware-decoded by the VU+ Duo 4K SE.
                            # Keep the existing full video fallback for AV1.
                            if codec == "av1":
                                force_transcode = "video_h264"
                                force_url = True

                            # Non-HEVC 2160p/DV formats keep the compatibility
                            # fallback. H.264 >1920 is already covered by the
                            # dedicated, proven width guard above.
                            elif (height >= 2160 or dolby_vision) and not hevc_native:
                                force_transcode = "video_h264"
                                force_url = True

                            elif hevc_native and (height >= 2160 or dolby_vision):
                                item["EmbyFlowVideoDecision"] = "direct-hevc-native"
                                try:
                                    with embyflow_open_log(
                                        "/tmp/embyflow_dreamsafe_video_v1.log",
                                        "a",
                                    ) as _dreamsafe_log:
                                        _dreamsafe_log.write(
                                            "%s DIRECT item=%s codec=%s size=%sx%s bitdepth=%s dv=%s reason=hevc-native\n"
                                            % (
                                                time.strftime("%Y-%m-%d %H:%M:%S"),
                                                str(item_id or ""),
                                                str(codec or ""),
                                                str(width),
                                                str(height),
                                                str(bitdepth),
                                                int(bool(dolby_vision)),
                                            )
                                        )
                                except Exception:
                                    pass
            except:
                force_transcode = False

            media_source, audio_stream = pick_best_audio_stream(item)
            audio_index = audio_stream.get("Index") if audio_stream else None
            audio_codec = (audio_stream.get("Codec") or "").lower() if audio_stream else ""
            media_source_id = media_source.get("Id") if media_source else None

            subtitle_index = None
            try:
                if media_source:
                    configured_subtitle_index = (
                        media_source.get(
                            "DefaultSubtitleStreamIndex"
                        )
                    )

                    if (
                        configured_subtitle_index is not None
                        and int(configured_subtitle_index) >= 0
                    ):
                        subtitle_index = int(
                            configured_subtitle_index
                        )
            except:
                subtitle_index = None

            play_session_id = str(uuid4())

            try:
                _resume_user_data_ref15 = (
                    item.get("UserData")
                    or item.get("user_data")
                    or {}
                )
                _resume_ticks_ref15 = max(
                    0,
                    int(
                        _resume_user_data_ref15.get(
                            "PlaybackPositionTicks"
                        )
                        or item.get("PlaybackPositionTicks")
                        or 0
                    )
                )
                _runtime_ticks_ref15 = max(
                    0,
                    int(
                        item.get("RunTimeTicks")
                        or item.get("runtime_ticks")
                        or 0
                    )
                )
                if (
                    _runtime_ticks_ref15
                    and _resume_ticks_ref15
                    >= max(
                        0,
                        _runtime_ticks_ref15 - 600000000
                    )
                ):
                    _resume_ticks_ref15 = 0
            except Exception:
                _resume_ticks_ref15 = 0

            try:
                f=embyflow_open_log("/tmp/embyflow_audio_branch.log","a")
                f.write("item=%s audio_index=%s subtitle_index=%s codec=%s force=%s media_source=%s title=%s lang=%s\n" % (
                    item_id,
                    audio_index,
                    subtitle_index,
                    audio_codec,
                    media_source.get("EmbyFlowForceAudioTranscode") if media_source else None,
                    media_source_id,
                    audio_stream.get("DisplayTitle") if audio_stream else "",
                    audio_stream.get("Language") if audio_stream else "",
                ))
                f.close()
            except:
                pass

            if audio_index is not None:
                try:
                    item["embyflow_selected_audio_index"] = audio_index
                    for src in item.get("MediaSources", []) or []:
                        if not media_source_id or src.get("Id") == media_source_id:
                            src["DefaultAudioStreamIndex"] = audio_index
                except:
                    pass

            if audio_mode == "aac":
                stream_url = build_compatible_stream_url(
                    server,
                    item_id,
                    token,
                    "video_h264"
                )
                force_url = True

            # Ein notwendiger Video-Transcode muss vor allen
            # Direct-Play-Audiozweigen ausgewertet werden.
            #
            # EMBYFLOW_HLS_TRANSCODE_GENERALIZED_V1
            # Der frühere "video_h264"-Kompatibilitätsstream läuft als
            # progressives stream.mp4 (Static=false). Live-Transcodes als
            # progressives MP4 lassen sich auf Enigma2/gstreamer-Boxen oft
            # nicht sauber demuxen (fehlendes/verzoegertes moov-Atom) -
            # Symptom: Ton läuft, Bild bleibt schwarz. Der HLS-Pfad
            # (master.m3u8, SegmentContainer=ts) ist robuster und war bisher
            # nur für Item 587869 ("Mad Heidi") als Test aktiv. Er gilt jetzt
            # für jeden Titel, bei dem ein Video-Transcode nötig ist.
            elif force_transcode:
                test5_decision = embyflow_server_decision_hls_test5(
                    server,
                    item_id,
                    token,
                    user_id,
                    media_source_id,
                    audio_index,
                    play_session_id,
                    _resume_ticks_ref15
                )
                stream_url = str(test5_decision.get("url") or "")
                if not stream_url:
                    # ADMIN_SAFETY_V2: Eine abgelehnte/fehlende PlaybackInfo-
                    # Entscheidung darf nicht durch eine selbst gebaute
                    # Transcode-URL umgangen werden.
                    item["EmbyFlowServerDecisionTest5"] = test5_decision
                    return None
                item["EmbyFlowPlaybackMode"] = "server-decision-transcoding"
                item["EmbyFlowServerDecisionTest5"] = test5_decision
                item["EmbyFlowServerResumeTicksRef15"] = int(
                    test5_decision.get("start_ticks") or 0
                )
                force_url = True

            elif (
                audio_index is not None
                and (
                    audio_codec in (
                        "dts",
                        "dca",
                        "truehd",
                        "mlp",
                    )
                    or (
                        media_source
                        and media_source.get(
                            "EmbyFlowForceAudioTranscode"
                        )
                    )
                )
            ):
                # EMBYFLOW_RC14_RECEIVER_NEUTRAL_STREAM_ENDPOINT_V1
                # Direct Play verwendet auf allen Enigma2-Plattformen den
                # validierten statischen stream.mkv-Endpunkt. Der optionale
                # Audiokompatibilitätsmodus bleibt davon unberührt.
                stream_url = build_direct_mkv_stream_url(
                    server,
                    item_id,
                    token,
                    media_source_id,
                    audio_index,
                    subtitle_index
                )
                force_url = False

            elif audio_index is not None:
                stream_url = build_direct_mkv_stream_url(
                    server,
                    item_id,
                    token,
                    media_source_id,
                    audio_index,
                    subtitle_index
                )

            else:
                stream_url = build_direct_mkv_stream_url(
                    server,
                    item_id,
                    token,
                    media_source_id,
                    None,
                    subtitle_index
                )
            stream_url = add_stream_session_params(stream_url, play_session_id)

            try:
                f = embyflow_open_log("/tmp/embyflow_stream_timing.log", "a")
                f.write("item=%s title=%s seconds=%.3f cached_auth=1\n" % (
                    str(item_id), str(item.get("Name") or search_term or ""), time.time() - started_ts
                ))
                f.close()
            except:
                pass
            return {
                "url": stream_url,
                "server": server,
                "token": token,
                "user_id": user_id,
                "item": item,
                "force_url": force_url,
                "play_session_id": play_session_id,
                "playback_mode": str(
                    item.get("EmbyFlowPlaybackMode") or "direct"
                ),
                "server_resume_ticks": int(
                    item.get("EmbyFlowServerResumeTicksRef15")
                    or 0
                ),
            }
    return None


def fetch_stream_url(search_term, audio_mode="direct"):
    info = fetch_stream_info(search_term, audio_mode)
    if info:
        return info.get("url")
    return None




# ASYNC_LIBRARY_COUNTS_CACHE_V2
EMBYFLOW_LIBRARY_COUNTS_REFRESH_RUNNING = False
EMBYFLOW_LIBRARY_COUNTS_REFRESH_LOCK = None

# DYNAMIC_LIBRARY_MENU_COUNTS_V1
LIBRARY_VIEW_COUNTS_CACHE_FILE = (
    CACHE_DIR + "/library_view_counts.json"
)
LIBRARY_VIEW_COUNTS_TTL = 300


def emby_library_view_counts(views, force=False):
    # EMBYFLOW_PERFORMANCE_PATCH23_ASYNC_COUNTS_V1
    # Nie auf Netzwerkzugriffe warten: vorhandene oder direkt vom Views-Endpunkt
    # gelieferte Werte sofort zurückgeben und fehlende Werte im Hintergrund laden.
    global EMBYFLOW_LIBRARY_COUNTS_REFRESH_RUNNING
    global EMBYFLOW_LIBRARY_COUNTS_REFRESH_LOCK

    if not views:
        return {}

    now_ts = int(time.time())
    cached_timestamp = 0
    cached_counts = {}

    try:
        cached = read_json_file(
            LIBRARY_VIEW_COUNTS_CACHE_FILE,
            {}
        ) or {}
        cached_timestamp = int(
            cached.get("timestamp", 0)
            or 0
        )

        for key, value in (
            cached.get("counts", {})
            or {}
        ).items():
            try:
                cached_counts[str(key)] = int(value)
            except Exception:
                pass
    except Exception:
        cached_timestamp = 0
        cached_counts = {}

    inline_counts = {}
    requested_view_ids = []

    for view in views:
        view_id = str(
            view.get("id") or ""
        ).strip()

        if not view_id:
            continue

        requested_view_ids.append(view_id)
        server_count = view.get("server_count")

        if server_count is not None:
            try:
                inline_counts[view_id] = int(server_count)
            except Exception:
                pass

    visible_counts = dict(cached_counts)
    visible_counts.update(inline_counts)

    cache_age = max(
        0,
        now_ts - cached_timestamp
    )
    cache_is_fresh = bool(
        cached_counts
        and cache_age < LIBRARY_VIEW_COUNTS_TTL
    )

    all_inline = bool(
        requested_view_ids
        and all(
            view_id in inline_counts
            for view_id in requested_view_ids
        )
    )

    # /Users/{UserId}/Views hat bereits vollständige Zähler geliefert.
    # In diesem Fall ist keine zusätzliche Items-Abfrage pro View nötig.
    if all_inline:
        if (
            force
            or not cache_is_fresh
            or any(
                cached_counts.get(key) != value
                for key, value in inline_counts.items()
            )
        ):
            write_json_file(
                LIBRARY_VIEW_COUNTS_CACHE_FILE,
                {
                    "timestamp": now_ts,
                    "counts": inline_counts,
                }
            )

        return dict(inline_counts)

    visible_counts_complete = bool(
        requested_view_ids
        and all(
            view_id in visible_counts
            for view_id in requested_view_ids
        )
    )

    if (
        cache_is_fresh
        and visible_counts_complete
        and not force
    ):
        return visible_counts

    if (
        not requests
        or not EMBY_SERVER
        or not EMBY_USERNAME
    ):
        return visible_counts

    try:
        import threading
    except Exception:
        threading = None

    if threading is None:
        return visible_counts

    if EMBYFLOW_LIBRARY_COUNTS_REFRESH_LOCK is None:
        try:
            EMBYFLOW_LIBRARY_COUNTS_REFRESH_LOCK = threading.Lock()
        except Exception:
            return visible_counts

    def perform_refresh():
        global EMBYFLOW_LIBRARY_COUNTS_REFRESH_RUNNING

        refreshed = dict(inline_counts)

        try:
            server, token, user_id = get_emby_auth()

            if not server or not token or not user_id:
                return

            headers = {
                "X-Emby-Token": token,
                "X-Emby-Authorization": AUTH_HEADER,
            }
            result_lock = threading.Lock()
            workers = []

            def fetch_one(view):
                view_id = str(
                    view.get("id") or ""
                ).strip()

                if not view_id or view_id in refreshed:
                    return

                collection_type = str(
                    view.get("type") or ""
                ).strip().lower()
                include_type = (
                    embyflow_collection_include_types(
                        collection_type
                    )
                    or ""
                )
                params = {
                    "ParentId": view_id,
                    "Recursive": "true",
                    "Limit": "1",
                }

                if include_type:
                    params["IncludeItemTypes"] = include_type

                try:
                    response_data = embyflow_cached_get_json(
                        server + "/Users/%s/Items" % user_id,
                        headers=headers,
                        params=params,
                        ttl=LIBRARY_VIEW_COUNTS_TTL,
                        timeout=8,
                        verify=True,
                        cache_key="library-count-%s" % view_id,
                    )
                    count = int(
                        response_data.get(
                            "TotalRecordCount",
                            0
                        )
                        or 0
                    )

                    with result_lock:
                        refreshed[view_id] = count

                except Exception as error:
                    try:
                        with embyflow_open_log(
                            "/tmp/embyflow_library_view_counts_error.log",
                            "a"
                        ) as log:
                            log.write(
                                "view=%s name=%s error=%s\n"
                                % (
                                    view_id,
                                    view.get("name") or "",
                                    error,
                                )
                            )
                    except Exception:
                        pass

            for view in views:
                view_id = str(
                    view.get("id") or ""
                ).strip()

                if not view_id or view_id in refreshed:
                    continue

                worker = threading.Thread(
                    target=fetch_one,
                    args=(view,)
                )
                worker.daemon = True
                worker.start()
                workers.append(worker)

            # Dieser Join läuft ausschließlich im Hintergrundthread.
            for worker in workers:
                worker.join()

            final_counts = dict(cached_counts)
            final_counts.update(refreshed)

            if final_counts:
                write_json_file(
                    LIBRARY_VIEW_COUNTS_CACHE_FILE,
                    {
                        "timestamp": int(time.time()),
                        "counts": final_counts,
                    }
                )

            try:
                with embyflow_open_log(
                    "/tmp/embyflow_library_view_counts.log",
                    "w"
                ) as log:
                    log.write(
                        "Modus=Hintergrund\nViews=%s\nGezählt=%s\n"
                        % (
                            len(views),
                            len(refreshed),
                        )
                    )
            except Exception:
                pass

        finally:
            EMBYFLOW_LIBRARY_COUNTS_REFRESH_RUNNING = False

    should_start = False

    try:
        with EMBYFLOW_LIBRARY_COUNTS_REFRESH_LOCK:
            if not EMBYFLOW_LIBRARY_COUNTS_REFRESH_RUNNING:
                EMBYFLOW_LIBRARY_COUNTS_REFRESH_RUNNING = True
                should_start = True
    except Exception:
        should_start = False

    if should_start:
        refresh_thread = threading.Thread(
            target=perform_refresh,
            name="EmbyFlowLibraryCounts"
        )
        refresh_thread.daemon = True
        refresh_thread.start()

    # Auch beim allerersten Cache-Miss niemals synchron warten.
    return visible_counts


def emby_library_views(collection_type=None):
    views = []
    if not requests or not EMBY_SERVER or not EMBY_USERNAME:
        return views
    try:
        server, token, user_id = get_emby_auth()
        if not token or not user_id:
            return views

        data = embyflow_cached_get_json(
            server + "/Users/%s/Views" % user_id,
            headers={
                "X-Emby-Token": token,
                "X-Emby-Authorization": AUTH_HEADER,
            },
            ttl=300,
            timeout=10,
            verify=True,
            cache_key="library-views",
        )

        for v in data.get("Items", []) or []:
            if collection_type and v.get("CollectionType") != collection_type:
                continue

            view_type = str(
                v.get("CollectionType") or ""
            ).strip().lower()
            server_count = None

            # Emby-Versionen liefern je nach View unterschiedliche Zählerfelder.
            # Nur tatsächlich vorhandene Werte werden übernommen.
            if view_type == "movies":
                count_keys = [
                    "MovieCount",
                    "ChildCount",
                    "RecursiveItemCount",
                ]
            elif view_type == "tvshows":
                count_keys = [
                    "SeriesCount",
                    "ChildCount",
                    "RecursiveItemCount",
                ]
            else:
                count_keys = [
                    "ChildCount",
                    "RecursiveItemCount",
                ]

            for count_key in count_keys:
                if v.get(count_key) is None:
                    continue

                try:
                    server_count = int(v.get(count_key))
                    break
                except Exception:
                    pass

            views.append({
                "id": v.get("Id"),
                "name": v.get("Name", ""),
                "type": v.get("CollectionType", ""),
                "server_count": server_count,
            })
    except Exception as e:
        try:
            f = embyflow_open_log("/tmp/embyflow_library_views_error.log", "a")
            f.write("%s\n" % str(e))
            f.close()
        except:
            pass
    return views


# DYNAMIC_SERVER_VIEWS_DEV_V1
def embyflow_collection_include_types(collection_type):
    collection_type = str(
        collection_type or ""
    ).strip().lower()

    if collection_type == "movies":
        return "Movie"

    if collection_type == "tvshows":
        return "Series"

    if collection_type == "boxsets":
        return "BoxSet"

    return ""


# REAL_LAZY_PAGE_CACHE_V2
EMBYFLOW_LAZY_PAGE_CACHE = {}
EMBYFLOW_LAZY_PAGE_CACHE_MAX = 60


def _embyflow_lazy_page_cache_key(
    parent_id,
    collection_type,
    start_index,
    limit,
    sort_mode="az"
):
    return (
        str(parent_id or ""),
        str(collection_type or "").strip().lower(),
        int(start_index or 0),
        int(limit or 10),
        str(sort_mode or "az").strip().lower(),
    )


def _embyflow_lazy_page_cache_get(key):
    try:
        entry = EMBYFLOW_LAZY_PAGE_CACHE.get(key)

        if not entry:
            return None

        entry["access"] = time.time()

        return [
            dict(item)
            for item in entry.get("items", [])
        ]
    except Exception:
        return None


def _embyflow_lazy_page_cache_put(key, items):
    try:
        EMBYFLOW_LAZY_PAGE_CACHE[key] = {
            "items": [
                dict(item)
                for item in (items or [])
            ],
            "access": time.time(),
        }

        while (
            len(EMBYFLOW_LAZY_PAGE_CACHE)
            > EMBYFLOW_LAZY_PAGE_CACHE_MAX
        ):
            oldest_key = min(
                EMBYFLOW_LAZY_PAGE_CACHE,
                key=lambda cache_key: float(
                    EMBYFLOW_LAZY_PAGE_CACHE[
                        cache_key
                    ].get("access", 0)
                    or 0
                )
            )

            del EMBYFLOW_LAZY_PAGE_CACHE[
                oldest_key
            ]

        return True

    except Exception:
        return False


def emby_dynamic_view_items(
    parent_id,
    collection_type="",
    limit=120,
    start_index=0,
    sort_mode="az"
):
    # LAZY_DYNAMIC_LIBRARY_LOADER_V2
    #
    # Normale Bibliotheksansicht:
    # - initial nur 20 Titel
    # - später jeweils 10 Titel
    # - Gesamtzahl wird jedem Eintrag als Kontext mitgegeben
    items = []

    if (
        not requests
        or not EMBY_SERVER
        or not EMBY_USERNAME
        or not parent_id
    ):
        return items

    try:
        server, token, user_id = get_emby_auth()

        if not token or not user_id:
            return items

        collection_type = str(
            collection_type or ""
        ).strip().lower()

        include_types = (
            embyflow_collection_include_types(
                collection_type
            )
        )

        try:
            requested_limit = max(
                1,
                int(limit or 20)
            )
        except Exception:
            requested_limit = 20

        try:
            requested_start = max(
                0,
                int(start_index or 0)
            )
        except Exception:
            requested_start = 0

        # GRID_SORT_NEWEST_V27
        requested_sort_mode = str(
            sort_mode or "az"
        ).strip().lower()
        if requested_sort_mode not in ("az", "newest"):
            requested_sort_mode = "az"

        # REAL_LAZY_PAGE_CACHE_LOOKUP_V2
        cache_key = _embyflow_lazy_page_cache_key(
            parent_id,
            collection_type,
            requested_start,
            requested_limit,
            requested_sort_mode
        )

        cached_items = _embyflow_lazy_page_cache_get(
            cache_key
        )

        if cached_items is not None:
            try:
                with embyflow_open_log(
                    "/tmp/embyflow_lazy_page_cache.log",
                    "a"
                ) as cache_log:
                    cache_log.write(
                        "HIT parent=%s type=%s "
                        "start=%s limit=%s loaded=%s\n"
                        % (
                            parent_id,
                            collection_type,
                            requested_start,
                            requested_limit,
                            len(cached_items),
                        )
                    )
            except Exception:
                pass

            return cached_items

        try:
            with embyflow_open_log(
                "/tmp/embyflow_lazy_page_cache.log",
                "a"
            ) as cache_log:
                cache_log.write(
                    "MISS parent=%s type=%s "
                    "start=%s limit=%s\n"
                    % (
                        parent_id,
                        collection_type,
                        requested_start,
                        requested_limit,
                    )
                )
        except Exception:
            pass

        if requested_sort_mode == "newest":
            sort_by = "PremiereDate"
            sort_order = "Descending"
        else:
            sort_by = "SortName"
            sort_order = "Ascending"

        params = {
            "ParentId": str(parent_id),
            "Recursive": "true",
            "SortBy": sort_by,
            "SortOrder": sort_order,
            "StartIndex": str(requested_start),
            "Limit": str(requested_limit),
            "Fields": (
                "Overview,Genres,ProductionYear,PremiereDate,"
                "RunTimeTicks,UserData,ChildCount,"
                "SortName"
            ),
        }

        if include_types:
            params["IncludeItemTypes"] = (
                include_types
            )

        response = embyflow_http_get(
            server + "/Users/%s/Items"
            % user_id,
            headers={
                "X-Emby-Token": token,
                "X-Emby-Authorization": AUTH_HEADER,
            },
            params=params,
            timeout=10,
            verify=True,
        )

        if response.status_code != 200:
            raise RuntimeError(
                "HTTP %s ab Index %s: %s"
                % (
                    response.status_code,
                    requested_start,
                    (response.text or "")[:300],
                )
            )

        data = response.json() or {}

        total_count = int(
            data.get("TotalRecordCount", 0)
            or 0
        )

        for item in data.get("Items", []) or []:
            title = item.get("Name", "")
            item_type = item.get("Type") or ""
            year = item.get("ProductionYear") or ""
            genres = ", ".join(
                item.get("Genres") or []
            )

            if item_type == "Series":
                meta = "Serie"

            elif item_type == "BoxSet":
                meta = "Sammlung"

                child_count = item.get(
                    "ChildCount"
                )

                if child_count is not None:
                    meta += (
                        " | %s Eintraege"
                        % child_count
                    )

            elif item_type in (
                "Folder",
                "CollectionFolder",
                "UserView",
            ):
                meta = "Ordner"

            elif item_type in (
                "Video",
                "Movie",
            ):
                meta = "Film"

            else:
                meta = item_type or "Eintrag"

            if year:
                meta += " | %s" % year

            if (
                genres
                and item_type not in (
                    "BoxSet",
                    "Folder",
                    "CollectionFolder",
                    "UserView",
                )
            ):
                meta += " | %s" % genres

            sort_name = (
                item.get("SortName")
                or title
            )

            items.append({
                "title": title,
                "Name": title,
                "sort_name": sort_name,
                "SortName": sort_name,
                "meta": meta,
                "overview": item.get(
                    "Overview",
                    ""
                ),
                "country": "",
                "director": "",
                "search_term": title,
                "id": item.get("Id"),
                "Id": item.get("Id"),
                "type": item_type,
                "Type": item_type,
                "user_data": item.get(
                    "UserData",
                    {}
                ),
                "UserData": item.get(
                    "UserData",
                    {}
                ),
                "runtime_ticks": item.get(
                    "RunTimeTicks"
                ),
                "RunTimeTicks": item.get(
                    "RunTimeTicks"
                ),
                "media_sources": [],
                "MediaSources": [],
                "collection_type": (
                    collection_type
                ),
                "_embyflow_parent_id": str(
                    parent_id
                ),
                "_embyflow_include_types": str(
                    include_types or ""
                ),
                "_embyflow_library_name": "",
                "_embyflow_library_total": (
                    total_count
                ),
                "_embyflow_lazy_library": True,
                "_embyflow_sort_mode": requested_sort_mode,
                "_embyflow_page_start": (
                    requested_start
                ),
            })

        # REAL_LAZY_PAGE_CACHE_STORE_V2
        cache_saved = _embyflow_lazy_page_cache_put(
            cache_key,
            items
        )

        try:
            with embyflow_open_log(
                "/tmp/embyflow_lazy_page_cache.log",
                "a"
            ) as cache_log:
                cache_log.write(
                    "STORE parent=%s type=%s "
                    "start=%s limit=%s loaded=%s "
                    "saved=%s cache_pages=%s\n"
                    % (
                        parent_id,
                        collection_type,
                        requested_start,
                        requested_limit,
                        len(items),
                        int(bool(cache_saved)),
                        len(EMBYFLOW_LAZY_PAGE_CACHE),
                    )
                )
        except Exception:
            pass

        try:
            with embyflow_open_log(
                "/tmp/embyflow_lazy_paging.log",
                "a"
            ) as log:
                log.write(
                    "FETCH parent=%s type=%s "
                    "start=%s limit=%s loaded=%s total=%s\n"
                    % (
                        parent_id,
                        collection_type,
                        requested_start,
                        requested_limit,
                        len(items),
                        total_count,
                    )
                )
        except Exception:
            pass

        try:
            if requested_start == 0:
                with embyflow_open_log(
                    "/tmp/embyflow_complete_library_load.log",
                    "w"
                ) as log:
                    log.write(
                        "ParentId=%s\n"
                        "CollectionType=%s\n"
                        "IncludeTypes=%s\n"
                        "LazyPaging=1\n"
                        "InitialGeladen=%s\n"
                        "ServerGesamt=%s\n"
                        % (
                            parent_id,
                            collection_type,
                            include_types,
                            len(items),
                            total_count,
                        )
                    )
        except Exception:
            pass

    except Exception as error:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_lazy_paging_error.log",
                "a"
            ) as log:
                log.write(
                    "parent=%s type=%s start=%s "
                    "limit=%s error=%s\n"
                    % (
                        parent_id,
                        collection_type,
                        start_index,
                        limit,
                        error,
                    )
                )
        except Exception:
            pass

    return items

def emby_dynamic_container_items(
    parent_id,
    limit=120
):
    return emby_dynamic_view_items(
        parent_id,
        "",
        limit
    )


# SERVER_SIDE_AZ_QUERY_DEV_V1
def emby_server_letter_items(
    parent_id,
    include_types,
    letter_key,
    limit=500
):
    items = []
    total_count = 0

    if (
        not requests
        or not EMBY_SERVER
        or not EMBY_USERNAME
        or not parent_id
    ):
        return items, total_count

    try:
        server, token, user_id = get_emby_auth()

        if not token or not user_id:
            return items, total_count

        requested = str(
            letter_key or ""
        ).strip().upper()
        numeric_filter = requested == "0-9"
        requested_prefix = requested[:1]

        headers = {
            "X-Emby-Token": token,
            "X-Emby-Authorization": AUTH_HEADER,
        }
        raw_items = []
        seen = set()
        requested_limit = max(
            1,
            int(limit or 500)
        )
        params = {
            "ParentId": str(parent_id),
            "Recursive": "true",
            "IncludeItemTypes": str(
                include_types or "Movie"
            ),
            "SortBy": "SortName",
            "SortOrder": "Ascending",
            "StartIndex": "0",
            "Limit": str(
                requested_limit * 10
                if numeric_filter
                else requested_limit
            ),
            "Fields": (
                "Overview,Genres,ProductionYear,"
                "RunTimeTicks,MediaSources,UserData,"
                "SortName"
            ),
        }

        if numeric_filter:
            # Eine Bereichsabfrage statt zehn serieller Requests.
            params["NameStartsWithOrGreater"] = "0"
            params["NameLessThan"] = "A"
        elif requested_prefix:
            params["NameStartsWith"] = requested_prefix
        else:
            return items, total_count

        response = embyflow_http_get(
            server + "/Users/%s/Items" % user_id,
            headers=headers,
            params=params,
            timeout=8,
            verify=True,
        )

        # Kompatibilitätsfallback für ältere Server, die NameLessThan nicht
        # akzeptieren: weiterhin nur eine zusätzliche Bereichsabfrage, niemals
        # wieder zehn serielle 0-9-Requests.
        if numeric_filter and response.status_code != 200:
            params.pop("NameLessThan", None)
            response = embyflow_http_get(
                server + "/Users/%s/Items" % user_id,
                headers=headers,
                params=params,
                timeout=8,
                verify=True,
            )

        if response.status_code != 200:
            raise RuntimeError(
                "HTTP %s" % response.status_code
            )

        data = response.json() or {}
        server_total = int(
            data.get("TotalRecordCount", 0)
            or 0
        )

        for raw in data.get("Items", []) or []:
            sort_value = str(
                raw.get("SortName")
                or raw.get("Name")
                or ""
            ).lstrip()

            if (
                numeric_filter
                and not (
                    sort_value[:1]
                    and sort_value[:1].isdigit()
                )
            ):
                continue

            item_id = str(
                raw.get("Id") or ""
            )

            if item_id and item_id in seen:
                continue

            if item_id:
                seen.add(item_id)

            raw_items.append(raw)

        total_count = (
            len(raw_items)
            if numeric_filter
            else server_total
        )

        raw_items.sort(
            key=lambda raw: str(
                raw.get("SortName")
                or raw.get("Name")
                or ""
            ).upper()
        )

        for raw in raw_items:
            title = raw.get("Name", "")
            item_type = raw.get("Type") or ""
            year = raw.get("ProductionYear") or ""
            genres = ", ".join(
                raw.get("Genres") or []
            )

            tech_parts = []

            try:
                for source in (
                    raw.get("MediaSources", [])
                    or []
                ):
                    for stream in (
                        source.get("MediaStreams", [])
                        or []
                    ):
                        if stream.get("Type") != "Video":
                            continue

                        width = int(
                            stream.get("Width") or 0
                        )

                        height = int(
                            stream.get("Height") or 0
                        )

                        codec = str(
                            stream.get("Codec") or ""
                        ).upper()

                        video_range = str(
                            stream.get("VideoRange")
                            or ""
                        )

                        if (
                            height >= 2160
                            or width >= 3840
                        ):
                            tech_parts.append("4K")
                        elif height:
                            tech_parts.append(
                                "%sp" % height
                            )

                        if codec:
                            tech_parts.append(codec)

                        if video_range:
                            tech_parts.append(
                                video_range
                            )

                        break

                    if tech_parts:
                        break

            except Exception:
                tech_parts = []

            if item_type == "Series":
                meta = "Serie"
            elif item_type == "BoxSet":
                meta = "Sammlung"
            else:
                meta = "Film"

            if year:
                meta += " | %s" % year

            if tech_parts:
                meta += " | %s" % " | ".join(
                    tech_parts
                )
            elif genres:
                meta += " | %s" % genres

            items.append({
                "title": title,
                "Name": title,
                "sort_name": (
                    raw.get("SortName")
                    or title
                ),
                "meta": meta,
                "overview": raw.get(
                    "Overview",
                    ""
                ),
                "country": "",
                "director": "",
                "search_term": title,
                "id": raw.get("Id"),
                "Id": raw.get("Id"),
                "type": item_type,
                "Type": item_type,
                "user_data": raw.get(
                    "UserData",
                    {}
                ),
                "UserData": raw.get(
                    "UserData",
                    {}
                ),
                "runtime_ticks": raw.get(
                    "RunTimeTicks"
                ),
                "RunTimeTicks": raw.get(
                    "RunTimeTicks"
                ),
                "media_sources": raw.get(
                    "MediaSources",
                    []
                ),
                "MediaSources": raw.get(
                    "MediaSources",
                    []
                ),
                "_embyflow_parent_id": str(
                    parent_id
                ),
                "_embyflow_include_types": str(
                    include_types or "Movie"
                ),
            })

    except Exception as error:
        try:
            with embyflow_open_log(
                "/tmp/embyflow_server_letter_error.log",
                "a",
                encoding="utf-8"
            ) as log:
                log.write(
                    u"parent=%s type=%s "
                    u"letter=%s error=%s\n"
                    % (
                        parent_id,
                        include_types,
                        letter_key,
                        error,
                    )
                )
        except Exception:
            pass

    return items, total_count


def emby_library_items(parent_id, include_types, limit=100):
    items = []
    if not requests or not EMBY_SERVER or not EMBY_USERNAME or not parent_id:
        return items
    try:
        server, token, user_id = get_emby_auth()
        if not token or not user_id:
            return items

        r = embyflow_http_get(
            server + "/Users/%s/Items" % user_id,
            headers={"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER},
            params={
                "ParentId": parent_id,
                "Recursive": "true",
                "IncludeItemTypes": include_types,
                "SortBy": "ParentIndexNumber,IndexNumber,SortName",
                "SortOrder": "Ascending",
                "Limit": str(limit),
                "Fields": "Overview,Genres,ProductionYear,RunTimeTicks,MediaSources",
            },
            timeout=10,
            verify=True,
        )

        raw_items = r.json().get("Items", []) or []
        if include_types == "Episode":
            def ep_key(x):
                try:
                    return (
                        int(x.get("ParentIndexNumber") or 0),
                        int(x.get("IndexNumber") or 0),
                        str(x.get("Name") or "")
                    )
                except:
                    return (9999, 9999, str(x.get("Name") or ""))
            raw_items = sorted(raw_items, key=ep_key)
        elif include_types == "Season":
            def season_key(x):
                try:
                    return int(x.get("IndexNumber") or 0)
                except:
                    return 9999
            raw_items = sorted(raw_items, key=season_key)

        for item in raw_items:
            title = item.get("Name", "")
            typ = "Serie" if item.get("Type") == "Series" else "Film"
            year = item.get("ProductionYear") or ""
            genres = ", ".join(item.get("Genres") or [])
            tech_parts = []
            try:
                for src in item.get("MediaSources", []) or []:
                    for st in src.get("MediaStreams", []) or []:
                        if st.get("Type") == "Video":
                            w = st.get("Width") or 0
                            h = st.get("Height") or 0
                            codec = (st.get("Codec") or "").upper()
                            vrange = st.get("VideoRange") or ""
                            if w and h:
                                if h >= 2160 or w >= 3840:
                                    tech_parts.append("4K")
                                elif h >= 1080:
                                    tech_parts.append("1080p")
                                else:
                                    tech_parts.append("%sp" % h)
                            if codec:
                                tech_parts.append(codec)
                            if vrange:
                                tech_parts.append(vrange)
                            break
                    if tech_parts:
                        break
            except:
                tech_parts = []

            meta = typ
            if year:
                meta += " | %s" % year
            if tech_parts:
                meta += " | %s" % " | ".join(tech_parts)
            elif genres:
                meta += " | %s" % genres

            try:
                if item.get("Type") == "Episode":
                    f=embyflow_open_log("/tmp/embyflow_episode_userdata.log","a")
                    f.write("title=%s meta=%s runtime=%s userdata=%s\n" % (
                        title, meta, item.get("RunTimeTicks"), repr(item.get("UserData", {}))
                    ))
                    f.close()
            except:
                pass

            items.append({
                "title": title,
                "meta": meta,
                "overview": item.get("Overview", ""),
                "country": "",
                "director": "",
                "search_term": title,
                "id": item.get("Id"),
                "type": item.get("Type"),
                "media_sources": item.get("MediaSources", []),
            })
    except Exception as e:
        try:
            f = embyflow_open_log("/tmp/embyflow_library_items_error.log", "a")
            f.write("%s\n" % str(e))
            f.close()
        except:
            pass
    return items



# EMBYFLOW_HB_MEDIA_PORT2
_AUDIO_ONLY_CONTAINERS = set((
    "mp3", "aac", "m4a", "m4b", "flac", "wav", "wave", "ogg",
    "oga", "opus", "alac", "aiff", "aif", "wma", "ape",
))

def embyflow_resolve_audio_item(item):
    """Resolve an arbitrary audiobook/library card to a real playable Audio item.

    Never trusts the grid Type alone.  The full Emby item is inspected for an
    audio-only MediaSource.  Container/book cards are resolved to their first
    real Audio child.  Video-bearing items are explicitly rejected.
    """
    if not isinstance(item, dict):
        return None

    item_id = str(item.get("Id") or item.get("id") or "").strip()
    if not item_id:
        return None

    raw = None
    try:
        server, token, user_id = get_emby_auth()
        if token and user_id:
            response = embyflow_http_get(
                server + "/Users/%s/Items/%s" % (user_id, item_id),
                headers={
                    "X-Emby-Token": token,
                    "X-Emby-Authorization": AUTH_HEADER,
                },
                params={
                    "Fields": (
                        "Overview,Genres,ProductionYear,RunTimeTicks,"
                        "MediaSources,MediaStreams,Chapters,Artists,"
                        "Album,AlbumArtist,Container,Path,ParentId,UserData"
                    )
                },
                timeout=8,
                verify=True,
            )
            if response.status_code == 200:
                raw = response.json() or {}
    except Exception:
        raw = None

    def audio_only(candidate):
        if not isinstance(candidate, dict):
            return False
        sources = candidate.get("MediaSources") or candidate.get("media_sources") or []
        container = str(candidate.get("Container") or candidate.get("container") or "").lower().lstrip(".")
        has_audio = False
        has_video = False
        for source in sources:
            if not isinstance(source, dict):
                continue
            source_container = str(source.get("Container") or "").lower().lstrip(".")
            if source_container and not container:
                container = source_container
            for stream in source.get("MediaStreams") or []:
                stream_type = str(stream.get("Type") or "").lower()
                if stream_type == "audio":
                    has_audio = True
                elif stream_type == "video":
                    has_video = True
        media_type = str(candidate.get("MediaType") or candidate.get("media_type") or "").lower()
        item_type = str(candidate.get("Type") or candidate.get("type") or "").lower()
        if has_video:
            return False
        if has_audio:
            return True
        if media_type in ("audio", "audiobook", "music", "song", "track"):
            return True
        if item_type == "audio":
            return True
        return container in _AUDIO_ONLY_CONTAINERS

    if raw and audio_only(raw):
        normalized = dict(raw)
        normalized["Type"] = "Audio"
        normalized["type"] = "Audio"
        normalized["MediaType"] = "Audio"
        return normalized

    # A Book/AudioBook/Folder/MusicAlbum can be a display container whose
    # playable file is an Audio child.
    try:
        children = emby_child_items(item_id, "Audio", 500, recursive=True)
    except Exception:
        children = []

    if children:
        child = children[0]
        child_id = str(child.get("Id") or child.get("id") or "").strip()
        if child_id:
            try:
                server, token, user_id = get_emby_auth()
                response = embyflow_http_get(
                    server + "/Users/%s/Items/%s" % (user_id, child_id),
                    headers={
                        "X-Emby-Token": token,
                        "X-Emby-Authorization": AUTH_HEADER,
                    },
                    params={
                        "Fields": (
                            "Overview,Genres,ProductionYear,RunTimeTicks,"
                            "MediaSources,MediaStreams,Chapters,Artists,"
                            "Album,AlbumArtist,Container,Path,ParentId,UserData"
                        )
                    },
                    timeout=8,
                    verify=True,
                )
                if response.status_code == 200:
                    child_raw = response.json() or {}
                    if audio_only(child_raw):
                        normalized = dict(child_raw)
                        normalized["Type"] = "Audio"
                        normalized["type"] = "Audio"
                        normalized["MediaType"] = "Audio"
                        return normalized
            except Exception:
                pass
        if audio_only(child):
            normalized = dict(child)
            normalized["Type"] = "Audio"
            normalized["type"] = "Audio"
            normalized["MediaType"] = "Audio"
            return normalized

    return None


def emby_child_items(parent_id, include_types, limit=120, recursive=False):
    items = []
    if not requests or not EMBY_SERVER or not EMBY_USERNAME or not parent_id:
        return items
    try:
        server, token, user_id = get_emby_auth()
        if not token or not user_id:
            return items

        r = embyflow_http_get(
            server + "/Users/%s/Items" % user_id,
            headers={"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER},
            params={
                "ParentId": parent_id,
                "Recursive": "true" if recursive else "false",
                "IncludeItemTypes": include_types,
                "SortBy": "ParentIndexNumber,IndexNumber,SortName",
                "SortOrder": "Ascending",
                "Limit": str(limit),
                "Fields": "Overview,Genres,ProductionYear,RunTimeTicks,MediaSources,IndexNumber,ParentIndexNumber,SeriesName,SeriesId,SeasonId,ParentId,UserData",
            },
            timeout=8,
            verify=True,
        )

        if r.status_code != 200:
            try:
                with embyflow_open_log("/tmp/embyflow_child_items_http.log", "a") as log:
                    log.write(
                        "status=%s parent=%s type=%s body=%s\n"
                        % (
                            r.status_code,
                            parent_id,
                            include_types,
                            (r.text or "")[:300],
                        )
                    )
            except:
                pass
            return items

        try:
            response_data = r.json()
        except Exception as json_error:
            try:
                with embyflow_open_log("/tmp/embyflow_child_items_http.log", "a") as log:
                    log.write(
                        "json_error=%s status=%s parent=%s type=%s body=%s\n"
                        % (
                            json_error,
                            r.status_code,
                            parent_id,
                            include_types,
                            (r.text or "")[:300],
                        )
                    )
            except:
                pass
            return items

        requested_types = tuple(
            value.strip()
            for value in str(include_types or "").split(",")
            if value.strip()
        )

        for item in response_data.get("Items", []) or []:
            # EMBYFLOW_RC14_REQUESTED_ITEM_TYPE_FILTER_V1
            item_type = str(item.get("Type") or "").strip()

            if (
                requested_types
                and not embyflow_item_type_allowed(
                    item_type,
                    requested_types
                )
            ):
                try:
                    with embyflow_open_log(
                        "/tmp/embyflow_child_type_filter.log",
                        "a"
                    ) as log:
                        log.write(
                            "parent=%s requested=%s ignored=%s title=%s\n"
                            % (
                                parent_id,
                                include_types,
                                item_type,
                                item.get("Name") or "",
                            )
                        )
                except Exception:
                    pass

                continue

            title = item.get("Name", "")
            meta = item_type
            if item_type == "Season":
                num = item.get("IndexNumber")
                meta = "Staffel %s" % num if num is not None else "Staffel"
            elif item_type == "Episode":
                season = item.get("ParentIndexNumber")
                episode = item.get("IndexNumber")
                if season is not None and episode is not None:
                    meta = "S%02dE%02d" % (int(season), int(episode))
                elif episode is not None:
                    meta = "Episode %s" % episode
                else:
                    meta = "Episode"
                series_name = item.get("SeriesName") or ""
                if series_name:
                    meta += " | %s" % series_name

            try:
                if item_type == "Episode":
                    f = embyflow_open_log("/tmp/embyflow_episode_userdata.log", "a")
                    f.write("title=%s meta=%s runtime=%s userdata=%s\n" % (
                        title,
                        meta,
                        item.get("RunTimeTicks"),
                        repr(item.get("UserData", {}))
                    ))
                    f.close()
            except:
                pass

            items.append({
                "title": title,
                "meta": meta,
                "overview": item.get("Overview", ""),
                "country": "",
                "director": "",
                "search_term": title,
                "id": item.get("Id"),
                "type": item_type,
                "parent_id": item.get("ParentId"),
                "series_id": item.get("SeriesId") or (parent_id if item_type == "Season" else ""),
                "season_id": item.get("SeasonId"),
                "season_number": item.get("IndexNumber") if item_type == "Season" else item.get("ParentIndexNumber"),
                "episode_number": item.get("IndexNumber") if item_type == "Episode" else None,
                "user_data": item.get("UserData", {}),
                "UserData": item.get("UserData", {}),
                "runtime_ticks": item.get("RunTimeTicks"),
                "media_sources": item.get("MediaSources", []),
            })
    except Exception as e:
        try:
            f = embyflow_open_log("/tmp/embyflow_child_items_error.log", "a")
            f.write("%s\n" % str(e))
            f.close()
        except:
            pass
    return items


def _int_or_none(value):
    try:
        if value is None or value == "":
            return None
        return int(value)
    except:
        return None


def emby_series_episodes(series_id, limit=600):
    episodes = emby_child_items(series_id, "Episode", limit, recursive=True)
    return episodes


def emby_refresh_user_data(item_ids):
    refreshed = {}
    if not requests or not EMBY_SERVER or not EMBY_USERNAME or not item_ids:
        return refreshed
    try:
        ids = []
        for item_id in item_ids:
            if item_id and str(item_id) not in ids:
                ids.append(str(item_id))
        if not ids:
            return refreshed

        server, token, user_id = get_emby_auth()
        if not token or not user_id:
            return refreshed

        r = embyflow_http_get(
            server + "/Users/%s/Items" % user_id,
            headers={"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER},
            params={
                "Ids": ",".join(ids),
                "Fields": "UserData,RunTimeTicks,MediaSources",
                "Limit": str(len(ids)),
            },
            timeout=10,
            verify=True,
        )
        for item in r.json().get("Items", []) or []:
            item_id = item.get("Id")
            if item_id:
                refreshed[str(item_id)] = item
        try:
            f = embyflow_open_log("/tmp/embyflow_userdata_refresh.log", "a")
            f.write("ids=%s refreshed=%s\n" % (",".join(ids), ",".join(refreshed.keys())))
            f.close()
        except:
            pass
    except Exception as e:
        try:
            f = embyflow_open_log("/tmp/embyflow_userdata_refresh_error.log", "a")
            f.write("%s\n" % str(e))
            f.close()
        except:
            pass
    return refreshed


def emby_series_episodes_for_season(series_id, season_number, limit=600):
    wanted = _int_or_none(season_number)
    if wanted is None:
        return []
    episodes = emby_series_episodes(series_id, limit)
    filtered = []
    for episode in episodes:
        if _int_or_none(episode.get("season_number")) == wanted:
            filtered.append(episode)
    return filtered


def emby_series_seasons(series_id):
    # SPEED_TUNING_V1:
    # Beim Öffnen einer Serie nur die Staffeln laden.
    # Vorher wurden zusätzlich bis zu 800 Episoden rekursiv
    # geladen, nur um die Folgenanzahl je Staffel anzuzeigen.
    seasons = emby_child_items(series_id, "Season", 120)

    for season in seasons:
        season["series_id"] = season.get("series_id") or series_id

    seasons.sort(
        key=lambda item: (
            _int_or_none(item.get("season_number")) is None,
            _int_or_none(item.get("season_number")) or 9999,
            item.get("title", ""),
        )
    )
    return seasons


