def open_native_home(session, **kwargs):
    session.openWithCallback(
        lambda selection: handle_home_selection(session, selection),
        EmbyFlowChoiceScreen,
        "EmbyFlow E2",
        HOME_CHOICES,
    )


def handle_home_selection(session, selection):
    if not selection:
        return
    title, action = selection
    if action == "movies":
        open_native_list(session, "EmbyFlow E2 - Filme", MOVIE_CHOICES)
    elif action == "series":
        open_native_list(session, "EmbyFlow E2 - Serien", SERIES_CHOICES)
    elif action == "docs":
        open_native_list(session, "EmbyFlow E2 - Doku", DOC_CHOICES)
    elif action == "search":
        open_native_list(session, "EmbyFlow E2 - Suche", [("Suche kommt als naechster Schritt", "search")])
    elif action == "settings":
        open_native_list(session, "EmbyFlow E2 - Einstellungen", [("Serverstatus: nicht geprueft", "server")])


def open_native_list(session, title, entries):
    session.openWithCallback(
        lambda selection: open_native_home(session),
        EmbyFlowChoiceScreen,
        title,
        entries,
    )



# GRID_ENGINE_V11_IN_MEMORY_LIBRARY_CACHE
V11_LIBRARY_CACHE_DIR = CACHE_DIR + "/metadata"


def _v11_norm_genre(value):
    try:
        return str(value or "").strip().casefold()
    except:
        return str(value or "").strip().lower()


def _v11_item_from_raw(item):
    title = item.get("Name", "")
    item_type = item.get("Type") or ""
    typ = "Serie" if item_type == "Series" else "Film"
    year = item.get("ProductionYear") or ""
    genres = list(item.get("Genres") or [])
    meta = typ
    if year:
        meta += " | %s" % year
    if genres:
        meta += " | %s" % ", ".join(genres)
    return {
        "title": title,
        "meta": meta,
        "overview": item.get("Overview", ""),
        "country": "",
        "director": "",
        "search_term": title,
        "id": item.get("Id"),
        "type": item_type,
        "genres": genres,
        "production_year": year,
        "runtime_ticks": item.get("RunTimeTicks"),
        "user_data": item.get("UserData", {}),
        "UserData": item.get("UserData", {}),
        "media_sources": [],
    }


def _v11_fetch_library(include_types, limit=5000):
    items = []
    if not requests or not EMBY_SERVER or not EMBY_USERNAME:
        return items
    server, token, user_id = get_emby_auth()
    if not token or not user_id:
        return items
    response = embyflow_http_get(
        server + "/Users/%s/Items" % user_id,
        headers={"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER},
        params={
            "Recursive": "true",
            "IncludeItemTypes": include_types,
            "SortBy": "SortName",
            "SortOrder": "Ascending",
            "Limit": str(limit),
            "Fields": "Overview,Genres,ProductionYear,RunTimeTicks,UserData",
        },
        timeout=10,
        verify=True,
    )
    if response.status_code != 200:
        raise RuntimeError("HTTP %s" % response.status_code)
    for raw in response.json().get("Items", []) or []:
        items.append(_v11_item_from_raw(raw))
    return items


class EmbyFlowInMemoryLibraryCache(object):
    REFRESH_AFTER = 1800

    def __init__(self):
        self.lock = None
        self.loading = set()
        self.items = {"Movie": [], "Series": []}
        self.loaded_at = {"Movie": 0.0, "Series": 0.0}
        self.server_scope = embyflow_server_scope()
        try:
            import threading
            self.lock = threading.RLock()
        except:
            self.lock = None
        self._load_disk("Movie")
        self._load_disk("Series")

    def reset_for_current_server(self):
        new_scope = embyflow_server_scope()
        try:
            with self.lock:
                self.server_scope = new_scope
                self.loading = set()
                self.items = {"Movie": [], "Series": []}
                self.loaded_at = {"Movie": 0.0, "Series": 0.0}
        except Exception:
            self.server_scope = new_scope
            self.loading = set()
            self.items = {"Movie": [], "Series": []}
            self.loaded_at = {"Movie": 0.0, "Series": 0.0}
        self._load_disk("Movie")
        self._load_disk("Series")

    def _ensure_server_scope(self):
        current = embyflow_server_scope()
        if current != getattr(self, "server_scope", ""):
            self.reset_for_current_server()

    def _log(self, text, error=False):
        try:
            path = "/tmp/embyflow_library_v11_error.log" if error else "/tmp/embyflow_library_v11.log"
            with open(path, "a") as f:
                f.write("%s %s\n" % (time.strftime("%H:%M:%S"), str(text)))
        except:
            pass

    def _path(self, include_types):
        return V11_LIBRARY_CACHE_DIR + "/library_v11_%s_%s.json" % (
            str(getattr(self, "server_scope", "") or embyflow_server_scope()),
            str(include_types),
        )

    def _load_disk(self, include_types):
        try:
            path = self._path(include_types)
            if not os.path.exists(path):
                return False
            with open(path, "r") as f:
                payload = json.loads(f.read())
            values = payload.get("items") if isinstance(payload, dict) else None
            if not isinstance(values, list):
                return False
            with self.lock:
                self.items[include_types] = values
                self.loaded_at[include_types] = float(payload.get("saved") or os.path.getmtime(path))
            self._log("DISK_HIT type=%s items=%s" % (include_types, len(values)))
            return True
        except Exception as error:
            self._log("disk-load type=%s error=%s" % (include_types, error), True)
            return False

    def _save_disk(self, include_types, values):
        try:
            ensure_dir(V11_LIBRARY_CACHE_DIR)
            path = self._path(include_types)
            tmp = path + ".tmp"
            with open(tmp, "w") as f:
                f.write(json.dumps({"saved": int(time.time()), "items": values}, ensure_ascii=False))
            try:
                os.remove(path)
            except:
                pass
            os.rename(tmp, path)
        except Exception as error:
            self._log("disk-save type=%s error=%s" % (include_types, error), True)

    def has(self, include_types):
        self._ensure_server_scope()
        try:
            with self.lock:
                return bool(self.items.get(include_types))
        except:
            return False

    def get_all(self, include_types, limit=120):
        self._ensure_server_scope()
        try:
            with self.lock:
                values = list(self.items.get(include_types) or [])
            if values:
                self._log("RAM_HIT type=%s items=%s limit=%s" % (include_types, len(values), limit))
                return values[:int(limit)]
        except Exception as error:
            self._log("ram-get type=%s error=%s" % (include_types, error), True)
        return None

    def get_genres(self, include_types, genres, limit=120):
        self._ensure_server_scope()
        aliases = set(_v11_norm_genre(x) for x in (genres or []) if x)
        if not aliases:
            return self.get_all(include_types, limit)
        try:
            with self.lock:
                source = list(self.items.get(include_types) or [])
            if not source:
                return None
            result = []
            for item in source:
                item_genres = set(_v11_norm_genre(x) for x in (item.get("genres") or []))
                if aliases.intersection(item_genres):
                    result.append(item)
                    if len(result) >= int(limit):
                        break
            self._log("RAM_GENRE type=%s aliases=%s items=%s" % (include_types, ",".join(sorted(aliases)), len(result)))
            return result
        except Exception as error:
            self._log("ram-genre type=%s error=%s" % (include_types, error), True)
            return None

    def refresh_async(self, include_types, force=False):
        self._ensure_server_scope()
        include_types = str(include_types)
        try:
            now = time.time()
            with self.lock:
                if include_types in self.loading:
                    return
                if (not force and self.items.get(include_types) and
                        now - float(self.loaded_at.get(include_types) or 0) < self.REFRESH_AFTER):
                    return
                self.loading.add(include_types)
            import threading
            worker = threading.Thread(target=self._refresh_worker, args=(include_types,), name="EmbyFlowLibraryV11%s" % include_types)
            worker.daemon = True
            worker.start()
            self._log("REFRESH_START type=%s" % include_types)
        except Exception as error:
            self._log("refresh-start type=%s error=%s" % (include_types, error), True)

    def _refresh_worker(self, include_types):
        started = time.time()
        worker_scope = str(getattr(self, "server_scope", "") or embyflow_server_scope())
        try:
            values = _v11_fetch_library(include_types, 5000)
            if worker_scope != embyflow_server_scope():
                self._log("REFRESH_DISCARD server_changed type=%s" % include_types)
                return
            if values:
                with self.lock:
                    self.items[include_types] = values
                    self.loaded_at[include_types] = time.time()
                self._save_disk(include_types, values)
                self._log("REFRESH_OK type=%s items=%s seconds=%.3f" % (include_types, len(values), time.time() - started))
            else:
                self._log("REFRESH_EMPTY type=%s seconds=%.3f" % (include_types, time.time() - started), True)
        except Exception as error:
            self._log("refresh type=%s error=%s" % (include_types, error), True)
        finally:
            try:
                if worker_scope == str(getattr(self, "server_scope", "")):
                    with self.lock:
                        self.loading.discard(include_types)
            except:
                pass

    def warm(self):
        self._ensure_server_scope()
        self.refresh_async("Movie")
        self.refresh_async("Series")


EMBYFLOW_LIBRARY_CACHE_V11 = EmbyFlowInMemoryLibraryCache()

# GRID_ENGINE_V10_METADATA_CACHE
METADATA_CACHE_DIR = CACHE_DIR + "/metadata"


def _metadata_cache_key(kind, *parts):
    try:
        import hashlib
        payload = json.dumps(
            [embyflow_server_scope(), kind] + list(parts),
            sort_keys=True,
            ensure_ascii=True,
        )
        return hashlib.sha1(payload.encode("utf-8")).hexdigest()
    except:
        return str(abs(hash((embyflow_server_scope(), kind) + tuple([str(x) for x in parts]))))


class EmbyFlowMetadataCache(object):
    WORKER_COUNT = 4
    REFRESH_AFTER = 1800
    MAX_STALE = 172800

    # EMBYFLOW_BETA84_METADATA_CACHE_CLEANER_V1
    # Nur der persistente JSON-Metadaten-Cache wird begrenzt.
    METADATA_CACHE_LIMIT_BYTES = 30 * 1024 * 1024

    def __init__(self):
        self.lock = None
        self.event = None
        self.queue = []
        self.queued = set()
        self.workers = []
        try:
            import threading
            self.lock = threading.RLock()
            self.event = threading.Event()
            for number in range(self.WORKER_COUNT):
                worker = threading.Thread(target=self._worker, name="EmbyFlowMetadata%d" % (number + 1))
                worker.daemon = True
                worker.start()
                self.workers.append(worker)
        except Exception as error:
            self._log("worker-init: %s" % error, True)

    def _log(self, text, error=False):
        try:
            path = "/tmp/embyflow_metadata_v10_error.log" if error else "/tmp/embyflow_metadata_v10.log"
            with open(path, "a") as f:
                f.write("%s %s\n" % (time.strftime("%H:%M:%S"), str(text)))
        except:
            pass

    def _path(self, key):
        return METADATA_CACHE_DIR + "/" + str(key) + ".json"

    def load(self, key, allow_stale=True):
        path = self._path(key)
        try:
            if not os.path.exists(path):
                return None
            age = time.time() - os.path.getmtime(path)
            if (not allow_stale) and age > self.REFRESH_AFTER:
                return None
            if age > self.MAX_STALE:
                try:
                    os.remove(path)
                except Exception:
                    pass
                return None
            with open(path, "r") as f:
                data = json.loads(f.read())
            if isinstance(data, dict) and isinstance(data.get("items"), list):
                items = data.get("items")
                if not items:
                    try:
                        os.remove(path)
                    except Exception:
                        pass
                    self._log("EMPTY_INVALID key=%s" % key)
                    return None
                return items
        except Exception as error:
            self._log("load key=%s error=%s" % (key, error), True)
        return None

    def age(self, key):
        try:
            return time.time() - os.path.getmtime(self._path(key))
        except:
            return 999999999

    def save(self, key, items):
        if not items:
            self._log("EMPTY_NOSAVE key=%s" % key)
            return False
        try:
            ensure_dir(METADATA_CACHE_DIR)
            path = self._path(key)
            tmp = path + ".tmp"
            payload = {"saved": int(time.time()), "items": items or []}
            with open(tmp, "w") as f:
                f.write(json.dumps(payload, ensure_ascii=False))
            try:
                os.remove(path)
            except:
                pass
            os.rename(tmp, path)
            self._log("SAVE key=%s items=%s" % (key, len(items or [])))

            try:
                self._purge_stale_metadata_cache(protected_path=path)
            except Exception:
                pass

            try:
                self.prune_metadata_cache(
                    protected_path=path
                )
            except Exception:
                pass

            return True

        except Exception as error:
            self._log("save key=%s error=%s" % (key, error), True)
            return False

    def _purge_stale_metadata_cache(self, protected_path=None):
        try:
            ensure_dir(METADATA_CACHE_DIR)
            now = time.time()
            protected_abs = os.path.abspath(protected_path) if protected_path else None
            for name in os.listdir(METADATA_CACHE_DIR):
                if not str(name).endswith(".json"):
                    continue
                path = os.path.join(METADATA_CACHE_DIR, name)
                try:
                    if protected_abs and os.path.abspath(path) == protected_abs:
                        continue
                    if (now - os.path.getmtime(path)) > self.MAX_STALE:
                        os.remove(path)
                except Exception:
                    pass
        except Exception:
            pass

    def prune_metadata_cache(self, protected_path=None):
        """
        Entfernt ausschließlich die ältesten JSON-Dateien aus
        METADATA_CACHE_DIR, bis die 30-MB-Grenze eingehalten wird.
        """
        result = {
            "before": 0,
            "after": 0,
            "deleted": 0,
            "freed": 0,
        }

        try:
            ensure_dir(METADATA_CACHE_DIR)

            protected_real = ""

            if protected_path:
                try:
                    protected_real = os.path.realpath(
                        protected_path
                    )
                except Exception:
                    protected_real = str(
                        protected_path
                    )

            candidates = []
            total_size = 0

            for filename in os.listdir(
                METADATA_CACHE_DIR
            ):
                lower_name = str(
                    filename or ""
                ).lower()

                if not lower_name.endswith(".json"):
                    continue

                full_path = os.path.join(
                    METADATA_CACHE_DIR,
                    filename
                )

                try:
                    if not os.path.isfile(full_path):
                        continue

                    file_size = int(
                        os.path.getsize(full_path)
                    )

                    total_size += file_size

                    try:
                        real_path = os.path.realpath(
                            full_path
                        )
                    except Exception:
                        real_path = full_path

                    if (
                        protected_real
                        and real_path == protected_real
                    ):
                        continue

                    try:
                        file_time = float(
                            os.path.getmtime(
                                full_path
                            )
                        )
                    except Exception:
                        file_time = 0.0

                    candidates.append(
                        (
                            file_time,
                            full_path,
                            file_size,
                        )
                    )

                except Exception:
                    pass

            result["before"] = total_size
            limit_bytes = int(
                self.METADATA_CACHE_LIMIT_BYTES
            )

            if total_size > limit_bytes:
                candidates.sort(
                    key=lambda entry: entry[0]
                )

                for file_time, full_path, file_size in candidates:
                    if total_size <= limit_bytes:
                        break

                    try:
                        os.remove(full_path)
                        total_size -= file_size
                        result["deleted"] += 1
                        result["freed"] += file_size
                    except Exception:
                        pass

            result["after"] = max(
                0,
                total_size
            )

        except Exception as error:
            try:
                self._log(
                    "metadata-cleaner error=%s"
                    % str(error),
                    True
                )
            except Exception:
                pass

        return result

    def enqueue(self, key, loader, priority=False):
        if not self.lock or not self.event or not callable(loader):
            return
        try:
            with self.lock:
                if key in self.queued:
                    return
                self.queued.add(key)
                job=(key, loader, embyflow_server_scope())
                if priority:
                    self.queue.insert(0, job)
                else:
                    self.queue.append(job)
            self.event.set()
        except Exception as error:
            self._log("enqueue key=%s error=%s" % (key, error), True)

    def get(self, key, loader):
        cached = self.load(key, allow_stale=True)
        if cached is not None:
            if self.age(key) > self.REFRESH_AFTER:
                self.enqueue(key, loader, priority=True)
            self._log("HIT key=%s items=%s" % (key, len(cached)))
            return cached
        started=time.time()
        items=loader() or []
        self.save(key, items)
        self._log("MISS key=%s items=%s seconds=%.3f" % (key, len(items), time.time()-started))
        return items

    def _next(self):
        try:
            with self.lock:
                if self.queue:
                    return self.queue.pop(0)
        except:
            pass
        return None

    def _done(self, key):
        try:
            with self.lock:
                self.queued.discard(key)
        except:
            pass

    def _worker(self):
        while True:
            job=self._next()
            if job is None:
                try:
                    self.event.clear(); self.event.wait(5.0)
                except:
                    time.sleep(1.0)
                continue
            key, loader, job_scope=job
            started=time.time()
            try:
                if job_scope != embyflow_server_scope():
                    self._log("REFRESH_DISCARD server_changed key=%s" % key)
                    continue
                items=loader() or []
                if job_scope != embyflow_server_scope():
                    self._log("REFRESH_DISCARD server_changed_after_load key=%s" % key)
                    continue
                self.save(key, items)
                self._log("REFRESH key=%s items=%s seconds=%.3f" % (key, len(items), time.time()-started))
            except Exception as error:
                self._log("refresh key=%s error=%s" % (key, error), True)
            finally:
                self._done(key)


EMBYFLOW_METADATA_CACHE = EmbyFlowMetadataCache()


def cached_emby_genre_items(include_types, genres, limit=120, sort_mode="az"):
    requested_sort_mode = str(sort_mode or "az").strip().lower()
    if requested_sort_mode not in ("az", "newest"):
        requested_sort_mode = "az"
    try:
        EMBYFLOW_LIBRARY_CACHE_V11._log("ENTER type=%s genres=%s sort=%s" % (include_types, genres, requested_sort_mode))
    except:
        pass
    normalized = tuple(genres) if isinstance(genres, list) else (genres,)
    # Den alten Library-RAM-Cache nur fuer A-Z verwenden. Er kennt keinen
    # Sortiermodus und duerfte sonst eine alte A-Z-Liste fuer newest liefern.
    if requested_sort_mode == "az":
        ram = EMBYFLOW_LIBRARY_CACHE_V11.get_genres(include_types, list(normalized), limit)
        if ram is not None:
            # Kontext nachtraeglich setzen, damit BLAU auch auf Cache-Treffern
            # fuer Doku/Genre-Ansichten verfuegbar ist.
            for item in ram or []:
                try:
                    item["_embyflow_sort_mode"] = "az"
                    item["_embyflow_sort_source"] = "genre"
                    item["_embyflow_sort_include_types"] = str(include_types or "Movie")
                    item["_embyflow_sort_genres"] = list(normalized)
                    item["_embyflow_sort_limit"] = int(limit or 120)
                except Exception:
                    pass
            EMBYFLOW_LIBRARY_CACHE_V11.refresh_async(include_types)
            return ram
    key = _metadata_cache_key("genre-sort-v28", include_types, normalized, int(limit), requested_sort_mode)
    result = EMBYFLOW_METADATA_CACHE.get(
        key,
        lambda: emby_genre_items(include_types, list(normalized), limit, requested_sort_mode)
    )
    EMBYFLOW_LIBRARY_CACHE_V11.refresh_async(include_types)
    return result


def cached_emby_category_items(include_types, limit=120, sort_mode="az"):
    requested_sort_mode = str(sort_mode or "az").strip().lower()
    if requested_sort_mode not in ("az", "newest"):
        requested_sort_mode = "az"
    if requested_sort_mode == "az":
        ram = EMBYFLOW_LIBRARY_CACHE_V11.get_all(include_types, limit)
        if ram is not None:
            for item in ram or []:
                try:
                    item["_embyflow_sort_mode"] = "az"
                    item["_embyflow_sort_source"] = "category"
                    item["_embyflow_sort_include_types"] = str(include_types or "Movie")
                    item["_embyflow_sort_genres"] = []
                    item["_embyflow_sort_limit"] = int(limit or 120)
                except Exception:
                    pass
            EMBYFLOW_LIBRARY_CACHE_V11.refresh_async(include_types)
            return ram
    key = _metadata_cache_key("category-sort-v28", include_types, int(limit), requested_sort_mode)
    result = EMBYFLOW_METADATA_CACHE.get(
        key,
        lambda: emby_category_items(include_types, limit, requested_sort_mode)
    )
    EMBYFLOW_LIBRARY_CACHE_V11.refresh_async(include_types)
    return result


