def prewarm_emby_metadata_cache():
    # V11: persistent snapshot immediately into RAM, refresh silently.
    EMBYFLOW_LIBRARY_CACHE_V11.warm()
    movie_genres = [
        ["Krimi", "Crime"], ["Comedy", "Komödie", "Komodie"], ["Drama"],
        ["Action"], ["Thriller"], ["Horror"], ["Science Fiction", "Sci-Fi", "SciFi"],
        ["Fantasy"], ["Adventure", "Abenteuer"], ["Documentary", "Dokumentation", "Doku"],
    ]
    series_genres = [
        ["Krimi", "Crime"], ["Comedy", "Komödie", "Komodie"], ["Drama"], ["Action"],
        ["Mystery"], ["Science Fiction", "Sci-Fi", "SciFi"], ["Fantasy"],
        ["Animation", "Anime"], ["Kids", "Kinder", "Family", "Familie"],
        ["Documentary", "Dokumentation", "Doku"],
    ]
    jobs=[]
    for typ in ("Movie", "Series"):
        key=_metadata_cache_key("category", typ, 120)
        jobs.append((key, lambda typ=typ: emby_category_items(typ, 120)))
    for genres in movie_genres:
        key=_metadata_cache_key("genre", "Movie", tuple(genres), 120)
        jobs.append((key, lambda genres=genres: emby_genre_items("Movie", genres, 120)))
    for genres in series_genres:
        key=_metadata_cache_key("genre", "Series", tuple(genres), 120)
        jobs.append((key, lambda genres=genres: emby_genre_items("Series", genres, 120)))
    for key, loader in jobs:
        if EMBYFLOW_METADATA_CACHE.load(key, allow_stale=True) is None or EMBYFLOW_METADATA_CACHE.age(key) > EMBYFLOW_METADATA_CACHE.REFRESH_AFTER:
            EMBYFLOW_METADATA_CACHE.enqueue(key, loader, priority=False)
    try:
        views=emby_library_views(None)
        for view in views:
            view_id=view.get("id")
            if not view_id:
                continue
            for typ in ("Movie", "Series"):
                key=_metadata_cache_key("library", str(view_id), typ, 120)
                if EMBYFLOW_METADATA_CACHE.load(key, allow_stale=True) is None or EMBYFLOW_METADATA_CACHE.age(key) > EMBYFLOW_METADATA_CACHE.REFRESH_AFTER:
                    EMBYFLOW_METADATA_CACHE.enqueue(key, lambda view_id=view_id, typ=typ: emby_library_items(view_id, typ, 120), priority=False)
    except Exception as error:
        EMBYFLOW_METADATA_CACHE._log("prewarm-views: %s" % error, True)


