    def refresh_online_status(self):
        try:
            import os
            for fn in ("home_posters.json","poster1.jpg","poster2.jpg","poster3.jpg","poster4.jpg","poster5.jpg","poster6.jpg"):
                try:
                    os.remove(POSTER_CACHE_DIR + "/" + fn)
                except:
                    pass
        except:
            pass
        result = self.refresh_library_counts(show_popup=True)
        try:
            self.check_server_status()
            self.load_dynamic_posters(force_refresh=True)
            self.load_hero_slides(force_refresh=True)
        except:
            pass
        return result

    def load_cached_server_status(self):
        cached = read_json_file(CACHE_DIR + "/server_status.json", {}) or {}
        server = cached.get("server") or (EMBY_SERVER.rstrip("/") if EMBY_SERVER else "-")
        self.safe_set_label("server_host", "")
        self.safe_set_label("server_state", "Server")
        self.safe_set_label("server_online", cached.get("online") or "Offline")
        if cached.get("username"):
            self.safe_set_label("top_username", cached.get("username"))

    def load_cached_library_counts(self):
        cached = read_json_file(CACHE_DIR + "/library_counts.json", None)
        if not cached:
            self.safe_set_label("lib_movies", "Filme Cache")
            self.safe_set_label("lib_series", "Serien Cache")
            self.safe_set_label("lib_docs", "Doku Cache")
            self.safe_set_label("lib_docseries", "Doku-Serien Cache")
            self.safe_set_label("lib_episodes", "Episoden Cache")
            self.safe_set_label("lib_last_sync", "Sync ausstehend")
            return False
        counts = cached.get("counts", cached)
        self.safe_set_label("lib_movies", "Filme %s" % counts.get("Filme", 0))
        self.safe_set_label("lib_series", "Serien %s" % counts.get("Serien", 0))
        self.safe_set_label("lib_docs", "Doku %s" % counts.get("Doku", 0))
        self.safe_set_label("lib_docseries", "Doku-Serien %s" % counts.get("Doku-Serien", 0))
        self.safe_set_label("lib_episodes", "Episoden %s" % counts.get("Episoden", 0))
        self.safe_set_label("lib_last_sync", "Sync %s" % cached.get("last_sync", "--:--"))
        self.last_library_counts = counts
        return True

    def refresh_library_counts(self, show_popup=False):
        try:
            if not requests or not EMBY_SERVER or not EMBY_USERNAME:
                if show_popup:
                    self.popup_info("Emby Server nicht konfiguriert")
                return None

            # EMBYFLOW_BETA84_REFRESH_COUNTS_AUTH_V1
            # Zentralen Token-Cache verwenden, statt für die
            # Mediathekszähler erneut anzumelden.
            server, token, user_id = get_emby_auth()

            if not server or not token or not user_id:
                if show_popup:
                    self.popup_info("Emby Login Fehler")
                return None

            try:
                cached_status = read_json_file(
                    CACHE_DIR + "/server_status.json",
                    {}
                ) or {}

                username = (
                    cached_status.get("username")
                    or EMBY_USERNAME
                    or "User"
                )
            except Exception:
                username = (
                    EMBY_USERNAME
                    or "User"
                )

            self.safe_set_label(
                "top_username",
                username
            )

            headers = {
                "X-Emby-Token": token,
                "X-Emby-Authorization": AUTH_HEADER,
            }

            def count_items(include_types, extra=None):
                params = {
                    "Recursive": "true",
                    "IncludeItemTypes": include_types,
                    "Limit": "1",
                }
                if extra:
                    params.update(extra)
                r = embyflow_http_get(
                    server + "/Users/%s/Items" % user_id,
                    headers=headers,
                    params=params,
                    timeout=10,
                    verify=True,
                )
                return int(r.json().get("TotalRecordCount", 0))

            movies = count_items("Movie")
            series = count_items("Series")
            episodes = count_items("Episode")
            docs = count_items("Movie", {"Genres": "Documentary"})
            docseries = count_items("Series", {"Genres": "Documentary"})

            self.safe_set_label("lib_movies", "Filme %s" % movies)
            self.safe_set_label("lib_series", "Serien %s" % series)
            self.safe_set_label("lib_docs", "Doku %s" % docs)
            self.safe_set_label("lib_docseries", "Doku-Serien %s" % docseries)
            self.safe_set_label("lib_episodes", "Episoden %s" % episodes)
            self.safe_set_label("lib_last_sync", "Sync %s" % time.strftime("%H:%M"))

            counts = {
                "Filme": movies,
                "Serien": series,
                "Doku": docs,
                "Doku-Serien": docseries,
                "Episoden": episodes,
            }

            cache_file = CACHE_DIR + "/library_counts.json"
            old = None
            try:
                f = open(cache_file, "r")
                old = json.loads(f.read()).get("counts")
                f.close()
            except:
                old = getattr(self, "last_library_counts", None)

            self.last_library_counts = counts

            self.safe_set_label("server_state", "Server")
            self.safe_set_label("server_host", "")
            self.safe_set_label("server_online", "Online")

            try:
                write_json_file(cache_file, {"counts": counts, "last_sync": time.strftime("%H:%M"), "last_sync_ts": int(time.time())})
                write_json_file(CACHE_DIR + "/server_status.json", {
                    "state": "verbunden",
                    "online": "Online",
                    "server": server,
                    "username": username,
                    "last_sync": time.strftime("%H:%M"),
                })
            except:
                pass

            if show_popup:
                lines = ["Emby Server online", "", "Mediathek aktualisiert:"]
                for key in ["Filme", "Serien", "Doku", "Doku-Serien", "Episoden"]:
                    val = counts.get(key, 0)
                    if old and key in old:
                        diff = val - old.get(key, 0)
                        if diff > 0:
                            lines.append("%s: %s (+%s hinzugekommen)" % (key, val, diff))
                        elif diff < 0:
                            lines.append("%s: %s (%s weniger)" % (key, val, diff))
                        else:
                            lines.append("%s: %s" % (key, val))
                    else:
                        lines.append("%s: %s" % (key, val))

                self.popup_info("\n".join(lines), timeout=8)

            return counts

        except Exception as e:
            try:
                f = embyflow_open_log("/tmp/embyflow_library_counts_error.log", "a")
                f.write("%s\n" % str(e))
                f.close()
            except:
                pass
            if show_popup:
                self.popup_info("Emby Prüfung fehlgeschlagen\n\n%s" % str(e), timeout=8)
            return None




    def set_week_preview(self):
        try:
            rows = [
                ("Mo", "Weiter | Neu | Empfohlen"),
                ("Di", "Action | Comedy | Sci-Fi"),
                ("Mi", "Filme | Serien | Dokus"),
                ("Do", "Zuletzt | Filme neu | Serien neu"),
                ("Fr", "Thriller | Horror | Mystery"),
                ("Sa", "Fantasy | Abenteuer | Anime"),
                ("So", "Romance | Familie | Feel-Good"),
            ]
            today = datetime.now().weekday()
            for i, row in enumerate(rows):
                prefix = "● " if i == today else "  "
                self["week_row%d" % (i + 1)].setText("%s%s   %s" % (prefix, row[0], row[1]))
        except:
            pass

    def start_delayed_posters(self):
        perf_started = time.time()
        embyflow_perf_log("HOME_POSTERS_START")
        if not self.load_cached_posters():
            try:
                self.startup_timer.start(100, True)
            except:
                self.load_dynamic_posters(force_refresh=True)
        try:
            self.home_poster_timer.start(HOME_POSTER_ROTATE_MS, True)
        except:
            pass
        embyflow_perf_log("HOME_POSTERS_START_DONE", perf_started)

    def auto_refresh_home_posters(self):
        try:
            self.load_dynamic_posters(force_refresh=True)
        except:
            pass
        try:
            self.home_poster_timer.start(HOME_POSTER_ROTATE_MS, True)
        except:
            pass

    def refresh_home_posters_if_needed(self):
        try:
            now = int(time.time())
            if now - int(getattr(self, "last_home_refresh", 0) or 0) < 120:
                return
            self.last_home_refresh = now
            self.load_dynamic_posters(force_refresh=True)
        except:
            pass

    def load_cached_posters(self):
        perf_started = time.time()
        perf_decode_ms = 0.0
        perf_loaded_count = 0
        try:
            meta = read_json_file(POSTER_CACHE_DIR + "/home_posters.json", {}) or {}
            # DISCOVERFIX1: alte Home-Metadaten einmalig nicht wiederverwenden.
            if int(meta.get("discoverfix1", 0) or 0) != 1:
                return False
            last_ts = int(meta.get("last_sync_ts", 0) or 0)
            if not last_ts:
                try:
                    last_text = meta.get("last_sync") or ""
                    if last_text:
                        last_ts = int(time.mktime(time.strptime(last_text, "%Y-%m-%d %H:%M")))
                except:
                    last_ts = 0
            # HOME_POSTER_INSTANT_CACHE_V28
            # Vorhandene Home-Poster werden unabhängig vom Alter sofort angezeigt.
            # Die 5-Minuten-Aktualisierung läuft getrennt über home_poster_timer.
            cache_age = max(0, int(time.time()) - last_ts) if last_ts else 0
            try:
                with embyflow_open_log("/tmp/embyflow_home_cache_v28.log", "a") as log:
                    log.write("CACHE_SHOW age=%s\n" % cache_age)
            except Exception:
                pass
            # HOME_POSTER_ITEM_CACHE_V1
            loaded = False
            items = meta.get("items") or {}

            for i in range(1, 7):
                widget_name = "poster%d" % i
                cached_item = items.get(widget_name) or {}

                img = (
                    cached_item.get("image_path")
                    or (
                        POSTER_CACHE_DIR
                        + "/"
                        + widget_name
                        + ".jpg"
                    )
                )

                if (
                    os.path.exists(img)
                    and os.path.getsize(img) > 500
                ):
                    perf_pix_started = time.time()
                    decoded = embyflow_decode_image_to_widget(
                        self,
                        widget_name,
                        img,
                        max(1, sx(221)),
                        max(1, sy(314)),
                        token="home:%s" % widget_name,
                    )
                    perf_decode_ms += (time.time() - perf_pix_started) * 1000.0

                    if decoded:
                        perf_loaded_count += 1
                        loaded = True
            if items:
                self.dynamic_poster_items = items
                self.update_progress_widgets()
            else:
                self.clear_progress_widgets()
            if not loaded:
                self.load_static_posters_fallback()
            embyflow_perf_log(
                "CACHE_POSTERS_DONE",
                perf_started,
                loaded=int(bool(loaded)),
                count=perf_loaded_count,
                decode_ms="%.1f" % perf_decode_ms,
                items=len(items),
            )
            return loaded
        except Exception as error:
            embyflow_perf_log("CACHE_POSTERS_ERROR", perf_started, error=str(error))
            return False

    def load_dynamic_posters(self, force_refresh=False):
        perf_total_started = time.time()
        perf_http_ms = 0.0
        perf_download_ms = 0.0
        perf_normalize_ms = 0.0
        perf_decode_ms = 0.0
        perf_http_calls = 0
        embyflow_perf_log("DYNAMIC_POSTERS_START", force_refresh=int(bool(force_refresh)))
        try:
            f=embyflow_open_log("/tmp/embyflow_poster_debug.log","a")
            f.write("START force_refresh=%s\n" % str(force_refresh))
            f.close()
        except:
            pass
        if not force_refresh:
            self.load_cached_posters()
        try:
            import os
            cache = POSTER_CACHE_DIR + "/"
            try:
                os.makedirs(cache)
            except:
                pass

            self.dynamic_poster_items = {}

            if not requests or not EMBY_SERVER or not EMBY_USERNAME:
                self.load_static_posters_fallback()
                return

            # HOME_AUTH_CACHE_V28
            # Vorhandene Anmeldung wiederverwenden statt beim Posterwechsel
            # erneut einen synchronen Login auszuführen.
            perf_auth_started = time.time()
            server, token, user_id = get_emby_auth()
            embyflow_perf_log("AUTH_DONE", perf_auth_started, token=int(bool(token)), user=int(bool(user_id)))
            server = (server or EMBY_SERVER or "").rstrip("/")
            try:
                f=embyflow_open_log("/tmp/embyflow_poster_debug.log","a")
                f.write("LOGIN token=%s user_id=%s\n" % (bool(token), bool(user_id)))
                f.close()
            except:
                pass
            if not token or not user_id:
                self.load_static_posters_fallback()
                return

            headers = {"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER}

            # EMBYFLOW_HOME_SCOPE_V9_1
            # Poster-/Negative-Cache strikt an Server + Benutzer binden. Beim
            # Wechsel zwischen Produktion und Dev duerfen alte .missing-Dateien
            # bzw. home_posters.json nicht die neue Startseite blockieren.
            try:
                import hashlib as _embyflow_home_hashlib
                _home_scope_raw = "%s|%s" % (server, user_id)
                home_scope = _embyflow_home_hashlib.sha1(
                    _home_scope_raw.encode("utf-8", "replace")
                ).hexdigest()[:12]
            except Exception:
                home_scope = str(abs(hash((str(server), str(user_id)))))[:12]

            try:
                _scope_marker = POSTER_CACHE_DIR + "/home_scope.txt"
                _old_scope = ""
                try:
                    with open(_scope_marker, "r") as _scope_file:
                        _old_scope = _scope_file.read().strip()
                except Exception:
                    _old_scope = ""
                if _old_scope != home_scope:
                    try:
                        os.remove(POSTER_CACHE_DIR + "/home_posters.json")
                    except Exception:
                        pass
                    try:
                        for _cache_name in os.listdir(POSTER_CACHE_DIR):
                            if _cache_name.startswith("home_perf2_") and _cache_name.endswith(".missing"):
                                try:
                                    os.remove(os.path.join(POSTER_CACHE_DIR, _cache_name))
                                except Exception:
                                    pass
                    except Exception:
                        pass
                    try:
                        with open(_scope_marker, "w") as _scope_file:
                            _scope_file.write(home_scope)
                    except Exception:
                        pass
            except Exception:
                pass

            perf_http_ms_holder = [0.0]
            perf_http_calls_holder = [0]

            def fetch_items(include_types, limit=2, genre=None, start_index=0, filters=None, sort_by="DateCreated"):
                params = {
                    "Recursive": "true",
                    "IncludeItemTypes": include_types,
                    "SortBy": sort_by,
                    "SortOrder": "Descending",
                    "StartIndex": str(start_index),
                    "Limit": str(limit),
                    "Fields": "PrimaryImageAspectRatio,Overview,Genres,ProductionYear,RunTimeTicks,UserData,SeriesName,SeriesId,SeasonId,ParentId,IndexNumber,ParentIndexNumber,ImageTags",
                }
                if genre:
                    params["Genres"] = genre
                if filters:
                    params["Filters"] = filters
                fetch_started = time.time()
                try:
                    data = embyflow_cached_get_json(
                        server + "/Users/%s/Items" % user_id,
                        headers=headers,
                        params=params,
                        ttl=45,
                        timeout=10,
                        verify=True,
                        cache_key="home-items",
                    )
                except Exception as fetch_error:
                    try:
                        with embyflow_open_log(
                            "/tmp/embyflow_home_items_error.log", "a"
                        ) as fetch_log:
                            fetch_log.write(
                                "%s types=%s genre=%s start=%s limit=%s error=%s\n"
                                % (
                                    time.strftime("%Y-%m-%d %H:%M:%S"),
                                    include_types,
                                    genre or "-",
                                    start_index,
                                    limit,
                                    str(fetch_error),
                                )
                            )
                    except Exception:
                        pass
                    return []
                elapsed_ms = (time.time() - fetch_started) * 1000.0
                perf_http_ms_holder[0] += elapsed_ms
                perf_http_calls_holder[0] += 1
                result_items = data.get("Items", []) or []
                embyflow_perf_log(
                    "HTTP_ITEMS", fetch_started,
                    types=include_types, genre=genre or "-", start=start_index,
                    limit=limit, status="ram-or-http", count=len(result_items),
                )
                return result_items

            def fetch_resume_items(limit=2):
                params = {
                    "Recursive": "true",
                    "Limit": str(limit),
                    "Fields": "PrimaryImageAspectRatio,Overview,Genres,ProductionYear,RunTimeTicks,UserData,SeriesName,SeriesId,SeasonId,ParentId,IndexNumber,ParentIndexNumber,ImageTags",
                }
                try:
                    resume_started = time.time()
                    data = embyflow_cached_get_json(
                        server + "/Users/%s/Items/Resume" % user_id,
                        headers=headers,
                        params=params,
                        ttl=20,
                        timeout=10,
                        verify=True,
                        cache_key="home-resume",
                    )
                    elapsed_ms = (time.time() - resume_started) * 1000.0
                    perf_http_ms_holder[0] += elapsed_ms
                    perf_http_calls_holder[0] += 1
                    items = data.get("Items", []) or []
                    embyflow_perf_log("HTTP_RESUME", resume_started, status="ram-or-http", count=len(items))
                    if items:
                        return items
                except Exception as e:
                    try:
                        f = embyflow_open_log("/tmp/embyflow_resume_items_error.log", "a")
                        f.write("%s\n" % str(e))
                        f.close()
                    except:
                        pass
                return fetch_items("Movie,Episode", limit, None, 0, "IsResumable", "DatePlayed")

            slots = []
            slots += [("poster1", x) for x in fetch_items("Movie", 2)]
            slots += [("poster3", x) for x in fetch_items("Series", 2)]
            docs = fetch_items("Movie", 2, "Documentary")
            if len(docs) < 2:
                docs = fetch_items("Movie", 2, "Dokumentation")
            slots += [("poster5", x) for x in docs[:2]]

            # Slots sauber auf poster1-6 verteilen
            ordered = []
            now = datetime.now()
            day_index = now.toordinal()
            if now.hour < 6:
                day_index -= 1
            # HOME_DISCOVER_RECOMMENDED_ROTATION_V27
            # Entdecken und Empfohlen wechseln alle fünf Minuten, ohne die
            # Hero-Slideshow oder den Weiter-schauen-Bereich zu beeinflussen.
            rotation_bucket = int(time.time() // max(1, HOME_POSTER_CACHE_TTL))
            poster_offset = (rotation_bucket % 20) * 2

            resume = fetch_resume_items(6)
            if len(resume) < 2:
                resume = fetch_items("Movie,Episode", 2, None, 0, "IsResumable", "DateLastMediaAdded")

            # HOME_STRONG_DUPLICATE_FILTER_V1
            def item_duplicate_keys(item):
                if not isinstance(item, dict):
                    return []

                keys = []

                item_id = str(
                    item.get("Id")
                    or item.get("id")
                    or ""
                ).strip()

                if item_id:
                    keys.append(
                        "id:%s" % item_id.lower()
                    )

                title = str(
                    item.get("Name")
                    or item.get("title")
                    or item.get("search_term")
                    or ""
                ).strip().lower()

                # Leerzeichen, Satzzeichen und Bindestrichvarianten
                # vereinheitlichen, damit gleiche Titel erkannt werden.
                normalized_title = "".join(
                    character
                    for character in title
                    if character.isalnum()
                )

                year = str(
                    item.get("ProductionYear")
                    or item.get("year")
                    or ""
                ).strip()

                item_type = str(
                    item.get("Type")
                    or item.get("type")
                    or ""
                ).strip().lower()

                if normalized_title:
                    keys.append(
                        "title:%s|year:%s|type:%s"
                        % (
                            normalized_title,
                            year,
                            item_type,
                        )
                    )

                    # Zusätzlicher Titel-Schlüssel ohne Typ:
                    # verhindert Duplikate bei unterschiedlich klassifizierten
                    # Movie-/Video-Datensätzen desselben Titels.
                    keys.append(
                        "title:%s|year:%s"
                        % (
                            normalized_title,
                            year,
                        )
                    )

                return keys

            def unique_items(items):
                seen = set()
                result = []

                for item in items or []:
                    keys = item_duplicate_keys(item)

                    if not keys:
                        continue

                    if any(key in seen for key in keys):
                        try:
                            with embyflow_open_log(
                                "/tmp/embyflow_duplicate_items.log",
                                "a"
                            ) as log:
                                log.write(
                                    "UNIQUE_SKIP id=%s title=%s year=%s type=%s\n"
                                    % (
                                        item.get("Id")
                                        or item.get("id")
                                        or "",
                                        item.get("Name")
                                        or item.get("title")
                                        or "",
                                        item.get("ProductionYear")
                                        or item.get("year")
                                        or "",
                                        item.get("Type")
                                        or item.get("type")
                                        or "",
                                    )
                                )
                        except Exception:
                            pass

                        continue

                    seen.update(keys)
                    result.append(item)

                return result

            movies = unique_items(resume)

            # Sicherheits-Fallback:
            # Wenn Resume-Items keine brauchbaren Poster liefern oder zu wenig sind,
            # wird mit sichtbaren neuen Filmen aufgefüllt.
            fallback_movies = unique_items(fetch_items("Movie", 8, None, 0))
            for item in fallback_movies:
                key = item.get("Id") or item.get("id") or item.get("Name") or item.get("title") or item.get("search_term")
                existing = [m.get("Id") or m.get("id") or m.get("Name") or m.get("title") or m.get("search_term") for m in movies]
                if key and key not in existing:
                    movies.append(item)
                if len(movies) >= 2:
                    break

            movies = movies[:2]

            def remove_duplicates(source, used):
                out = []

                for item in source or []:
                    if not isinstance(item, dict):
                        continue

                    item_id = str(
                        item.get("Id")
                        or item.get("id")
                        or ""
                    ).strip()
                    item_title = str(
                        item.get("Name")
                        or item.get("title")
                        or item.get("search_term")
                        or ""
                    ).strip()
                    item_type = str(
                        item.get("Type")
                        or item.get("type")
                        or ""
                    ).strip()

                    if not item_id or not item_title:
                        continue

                    if item_type in ("Movie", "Series"):
                        image_tags = item.get("ImageTags")
                        if isinstance(image_tags, dict) and not image_tags.get("Primary"):
                            continue

                        primary_tag = item.get("PrimaryImageTag")
                        if primary_tag is not None and not primary_tag:
                            continue

                    keys = item_duplicate_keys(item)

                    if not keys:
                        continue

                    if any(key in used for key in keys):
                        try:
                            with embyflow_open_log(
                                "/tmp/embyflow_duplicate_items.log",
                                "a"
                            ) as log:
                                log.write(
                                    "HOME_SKIP id=%s title=%s year=%s type=%s\n"
                                    % (
                                        item.get("Id")
                                        or item.get("id")
                                        or "",
                                        item.get("Name")
                                        or item.get("title")
                                        or "",
                                        item.get("ProductionYear")
                                        or item.get("year")
                                        or "",
                                        item.get("Type")
                                        or item.get("type")
                                        or "",
                                    )
                                )
                        except Exception:
                            pass

                        continue

                    used.update(keys)
                    out.append(item)

                return out

            used=set()

            hero_key = ""
            try:
                hero_item = (
                    self.hero_slides[self.hero_index]
                    or {}
                )

                hero_key = str(
                    hero_item.get("id")
                    or hero_item.get("Id")
                    or ""
                )

                used.update(
                    item_duplicate_keys(hero_item)
                )
            except Exception:
                pass

            movies=remove_duplicates(movies, used)

            # Die Startseite bleibt semantisch stabil; nur die Inhalte der
            # beiden Empfehlungsbereiche rotieren regelmäßig.
            row_mode = 0

            if row_mode == 0:
                row_titles = ("Weiter schauen", "Entdecken", "Empfohlen fuer dich")
                row1 = movies
                row2 = remove_duplicates(
                    fetch_items("Movie,Series", 8, None, poster_offset),
                    used
                )[:2]
                recommended_offset = ((poster_offset + 10) % 40)
                row3 = remove_duplicates(
                    fetch_items("Movie,Series", 12, None, recommended_offset),
                    used
                )[:2]

                # DISCOVERFIX1: fehlende Karten auffuellen, niemals die bereits
                # gefundene erste Karte durch einen neuen Fallback ersetzen.
                if len(row2) < 2:
                    row2 += remove_duplicates(
                        fetch_items("Movie,Series", 12, None, 0),
                        used
                    )[:max(0, 2 - len(row2))]
                if len(row2) < 2:
                    row2 += remove_duplicates(
                        fetch_items("Movie,Series", 12, None, 12),
                        used
                    )[:max(0, 2 - len(row2))]

                if len(row3) < 2:
                    row3 += remove_duplicates(
                        fetch_items("Movie,Series", 12, None, 4),
                        used
                    )[:max(0, 2 - len(row3))]
                if len(row3) < 2:
                    row3 += remove_duplicates(
                        fetch_items("Movie,Series", 12, None, 16),
                        used
                    )[:max(0, 2 - len(row3))]
            elif row_mode == 1:
                row_titles = ("Filme", "Serien", "Dokus")
                row1 = remove_duplicates(fetch_items("Movie", 8, None, poster_offset), used)[:2]
                row2 = remove_duplicates(fetch_items("Series", 8, None, poster_offset), used)[:2]
                row3 = remove_duplicates(fetch_items("Movie", 8, "Documentary", poster_offset), used)[:2]
                if len(row3) < 2:
                    row3 = remove_duplicates(fetch_items("Movie", 8, "Dokumentation", poster_offset), used)[:2]
            elif row_mode == 2:
                row_titles = ("Action", "Comedy", "Sci-Fi")
                row1 = remove_duplicates(fetch_items("Movie,Series", 8, "Action", poster_offset), used)[:2]
                row2 = remove_duplicates(fetch_items("Movie,Series", 8, "Comedy", poster_offset), used)[:2]
                if len(row2) < 2:
                    row2 = remove_duplicates(fetch_items("Movie,Series", 8, "Komödie", poster_offset), used)[:2]
                row3 = remove_duplicates(fetch_items("Movie,Series", 8, "Sci-Fi", poster_offset), used)[:2]
                if len(row3) < 2:
                    row3 = remove_duplicates(fetch_items("Movie,Series", 8, "Science Fiction", poster_offset), used)[:2]
                if len(row3) < 2:
                    row3 = remove_duplicates(fetch_items("Movie,Series", 8, "Science-Fiction", poster_offset), used)[:2]
                if len(row3) < 2:
                    row3 = remove_duplicates(fetch_items("Movie,Series", 8, "SciFi", poster_offset), used)[:2]
            else:
                row_titles = ("Zuletzt gespielt", "Auswahl", "Serien-Tipps")
                row1 = movies
                row2 = remove_duplicates(fetch_items("Movie", 8, None, 0), used)[:2]
                row3 = remove_duplicates(fetch_items("Series", 8, None, 0), used)[:2]

            try:
                self["row1_title"].setText(row_titles[0])
                self["row2_title"].setText(row_titles[1])
                self["row3_title"].setText(row_titles[2])
            except:
                pass

            ordered += [("poster1", row1[0] if len(row1) > 0 else None)]
            ordered += [("poster2", row1[1] if len(row1) > 1 else None)]
            ordered += [("poster3", row2[0] if len(row2) > 0 else None)]
            ordered += [("poster4", row2[1] if len(row2) > 1 else None)]
            ordered += [("poster5", row3[0] if len(row3) > 0 else None)]
            ordered += [("poster6", row3[1] if len(row3) > 1 else None)]

            try:
                f=embyflow_open_log("/tmp/embyflow_poster_debug.log","a")
                f.write("ORDERED %s\n" % repr([(a, (b or {}).get("Name")) for a,b in ordered]))
                f.close()
            except:
                pass

            # EMBYFLOW_PERF1_HOME_IMAGE_CACHE_V1
            def remember_home_poster(widget_name, item, image_path):
                self.dynamic_poster_items[widget_name] = {
                    "id": item.get("Id"),
                    "image_path": image_path,
                    "title": item.get("Name", ""),
                    "type": item.get("Type", ""),
                    "overview": item.get("Overview", ""),
                    "year": item.get("ProductionYear", ""),
                    "genres": item.get("Genres", []),
                    "runtime": item.get("RunTimeTicks", 0),
                    "progress": self.progress_percent_from_item(item),
                    "user_data": item.get("UserData", {}),
                }

            def display_home_poster(widget_name, item, image_path):
                try:
                    decoded = embyflow_decode_image_to_widget(
                        self,
                        widget_name,
                        image_path,
                        max(1, sx(221)),
                        max(1, sy(314)),
                        token="home:%s" % widget_name,
                    )
                    if not decoded:
                        return False

                    remember_home_poster(
                        widget_name,
                        item,
                        image_path
                    )
                    return True
                except Exception:
                    return False

            for widget_name, item in ordered:
                if not item:
                    continue
                item_id = item.get("Id")
                if not item_id:
                    continue

                # EMBYFLOW_HOME_CONTINUE_SERIES_POSTER_V29_START
                # Im Home-Bereich "Weiter schauen" sollen Episoden wie die
                # restlichen Karten ein echtes Hochkantposter verwenden.
                # Deshalb bleibt der klickbare Eintrag die Episode, nur die
                # Bildquelle wechselt bei poster1/poster2 auf das Serienposter.
                image_source_id = item_id
                item_type = str(
                    item.get("Type")
                    or item.get("type")
                    or ""
                ).strip()

                if (
                    widget_name in ("poster1", "poster2")
                    and item_type == "Episode"
                ):
                    series_id = str(
                        item.get("SeriesId")
                        or item.get("series_id")
                        or ""
                    ).strip()

                    if series_id:
                        image_source_id = series_id

                    try:
                        with open(
                            "/tmp/embyflow_home_continue_poster_v29.log",
                            "a"
                        ) as log:
                            log.write(
                                "%s | widget=%s episode=%s series=%s source=%s\n"
                                % (
                                    time.strftime("%Y-%m-%d %H:%M:%S"),
                                    widget_name,
                                    str(item_id),
                                    series_id or "-",
                                    str(image_source_id),
                                )
                            )
                    except Exception:
                        pass
                # EMBYFLOW_HOME_CONTINUE_SERIES_POSTER_V29_END

                # HOME_POSTER_ITEM_CACHE_V1
                # Die Bildquelle ist Teil des Cache-Namens. Dadurch wird ein
                # bereits gecachtes 16:9-Episodenbild nicht weiterverwendet,
                # wenn nun das Serienposter geladen werden soll.
                img = (
                    cache
                    + "home_perf2_"
                    + SCREEN_RESOLUTION_KEY
                    + "_scope_"
                    + str(home_scope)
                    + "_"
                    + widget_name
                    + "_"
                    + str(item_id)
                    + "_src_"
                    + str(image_source_id)
                    + ".jpg"
                )

                target_w = max(1, sx(221))
                target_h = max(1, sy(314))
                url = server + (
                    "/Items/%s/Images/Primary?maxWidth=%d&maxHeight=%d&quality=90&api_key=%s"
                    % (image_source_id, target_w, target_h, token)
                )
                missing_path = img + ".missing"

                # Bereits passend gespeicherte Poster sofort wiederverwenden.
                if display_home_poster(widget_name, item, img):
                    continue

                # Fehlende Bilder zehn Minuten lang nicht erneut anfragen.
                if embyflow_negative_cache_active(missing_path):
                    continue

                try:
                    download_started = time.time()
                    rr = embyflow_http_get(
                        url,
                        headers=headers,
                        timeout=10,
                        verify=True,
                    )
                    download_elapsed = (time.time() - download_started) * 1000.0
                    perf_download_ms += download_elapsed
                    perf_http_ms_holder[0] += download_elapsed
                    perf_http_calls_holder[0] += 1
                    embyflow_perf_log("POSTER_DOWNLOAD", download_started, widget=widget_name, status=getattr(rr, "status_code", "?"), bytes=len(rr.content or b""))
                    try:
                        f=embyflow_open_log("/tmp/embyflow_poster_debug.log","a")
                        f.write("%s download status=%s bytes=%s\n" % (widget_name, rr.status_code, len(rr.content or "")))
                        f.close()
                    except:
                        pass
                    if rr.status_code == 200 and rr.content:
                        content_type = ""
                        try:
                            content_type = str(
                                rr.headers.get("Content-Type", "")
                            )
                        except Exception:
                            content_type = ""

                        if (
                            len(rr.content) <= 500
                            or (
                                content_type
                                and not content_type.startswith("image/")
                            )
                        ):
                            raise RuntimeError("ungueltige Bildantwort")

                        temporary_image = img + ".download"
                        with open(temporary_image, "wb") as handle:
                            handle.write(rr.content)
                            handle.flush()
                            try:
                                os.fsync(handle.fileno())
                            except Exception:
                                pass

                        try:
                            os.replace(temporary_image, img)
                        except AttributeError:
                            try:
                                os.remove(img)
                            except Exception:
                                pass
                            os.rename(temporary_image, img)

                        embyflow_clear_negative_cache(missing_path)
                        embyflow_touch_cache_file(img, 0)

                        decode_started = time.time()
                        decoded = display_home_poster(
                            widget_name,
                            item,
                            img
                        )
                        decode_elapsed = (
                            time.time() - decode_started
                        ) * 1000.0
                        perf_decode_ms += decode_elapsed
                        embyflow_perf_log(
                            "POSTER_EPICLOAD",
                            decode_started,
                            widget=widget_name,
                            decoded=int(bool(decoded)),
                        )

                        try:
                            with embyflow_open_log(
                                "/tmp/embyflow_home_poster_v1.log",
                                "a"
                            ) as home_log:
                                home_log.write(
                                    "DISPLAY_START widget=%s item=%s "
                                    "title=%s file=%s bytes=%s "
                                    "epicload=%s\n"
                                    % (
                                        widget_name,
                                        item_id,
                                        item.get("Name", ""),
                                        img,
                                        os.path.getsize(img),
                                        int(bool(decoded)),
                                    )
                                )
                        except Exception:
                            pass
                    else:
                        embyflow_mark_negative_cache(
                            missing_path,
                            "http-%s" % getattr(
                                rr,
                                "status_code",
                                "?"
                            )
                        )
                except Exception as e:
                    embyflow_mark_negative_cache(
                        missing_path,
                        str(e)
                    )
                    try:
                        f = embyflow_open_log("/tmp/embyflow_dynamic_poster_error.log", "a")
                        f.write("%s %s\n" % (widget_name, str(e)))
                        f.close()
                    except:
                        pass

            # Wenn nichts geladen wurde, statische Poster als Backup
            if not self.dynamic_poster_items:
                self.load_static_posters_fallback()
            else:
                self.update_progress_widgets()
                write_json_file(POSTER_CACHE_DIR + "/home_posters.json", {
                    "last_sync": time.strftime("%Y-%m-%d %H:%M"),
                    "last_sync_ts": int(time.time()),
                    "discoverfix1": 1,
                    "items": self.dynamic_poster_items,
                    "row_titles": [self["row1_title"].getText(), self["row2_title"].getText(), self["row3_title"].getText()],
                })

            perf_http_ms = perf_http_ms_holder[0]
            perf_http_calls = perf_http_calls_holder[0]
            embyflow_perf_log(
                "DYNAMIC_POSTERS_DONE", perf_total_started,
                http_calls=perf_http_calls, http_ms="%.1f" % perf_http_ms,
                download_ms="%.1f" % perf_download_ms,
                normalize_ms="%.1f" % perf_normalize_ms,
                decode_ms="%.1f" % perf_decode_ms,
                displayed=len(self.dynamic_poster_items),
            )

            # PERF2.2: Nach echtem Home-Poster-Downloadlauf mit 99-MiB-Reserve.
            if perf_download_ms > 0.0:
                embyflow_request_cache_tune("home-posters")

        except Exception as e:
            embyflow_perf_log("DYNAMIC_POSTERS_ERROR", perf_total_started, error=str(e))
            try:
                f = embyflow_open_log("/tmp/embyflow_dynamic_poster_error.log", "a")
                f.write("%s\n" % str(e))
                f.close()
            except:
                pass
            self.load_static_posters_fallback()


    def load_static_posters_fallback(self):
        try:
            self.clear_progress_widgets()
            base = "/usr/lib/enigma2/python/Plugins/Extensions/EmbyFlowE2/posters/"
            for i in range(1, 7):
                name = "poster%d" % i
                path = base + "poster%d.png" % i
                if self[name].instance:
                    pix = LoadPixmap(path)
                    if pix:
                        self[name].instance.setPixmap(pix)
                        try:
                            self[name].instance.setScale(1)
                        except Exception:
                            pass
        except Exception as e:
            try:
                f = embyflow_open_log("/tmp/embyflow_poster_widget_error.log", "a")
                f.write("%s\n" % str(e))
                f.close()
            except:
                pass


    def start_delayed_hero(self):
        # HERO_DIAG_START_DELAYED_V1
        try:
            with embyflow_open_log(
                "/tmp/embyflow_hero_diagnose.log",
                "a"
            ) as diag_log:
                diag_log.write(
                    "START_DELAYED_HERO_ENTER\n"
                )
        except Exception:
            pass

        cached_loaded = self.load_cached_hero_slides()

        try:
            with embyflow_open_log(
                "/tmp/embyflow_hero_diagnose.log",
                "a"
            ) as diag_log:
                diag_log.write(
                    "START_DELAYED_CACHE_RESULT=%s\n"
                    % bool(cached_loaded)
                )
        except Exception:
            pass

        if cached_loaded:
            return

        try:
            self.hero_startup_timer.start(100, True)

            try:
                with embyflow_open_log(
                    "/tmp/embyflow_hero_diagnose.log",
                    "a"
                ) as diag_log:
                    diag_log.write(
                        "START_DELAYED_TIMER_STARTED\n"
                    )
            except Exception:
                pass

        except Exception as timer_error:
            try:
                with embyflow_open_log(
                    "/tmp/embyflow_hero_diagnose.log",
                    "a"
                ) as diag_log:
                    diag_log.write(
                        "START_DELAYED_TIMER_ERROR=%s\n"
                        % str(timer_error)
                    )
            except Exception:
                pass

            self.load_hero_slides()

    def load_cached_hero_slides(self):
        # HERO_CACHE_TTL_6H_V2
        cache_path = HERO_CACHE_DIR + "/hero_slides.json"

        cached = read_json_file(
            cache_path,
            None
        )

        if not cached:
            try:
                with embyflow_open_log(
                    "/tmp/embyflow_hero_cache_ttl.log",
                    "a"
                ) as log:
                    log.write(
                        "CACHE_MISSING path=%s\n"
                        % cache_path
                    )
            except Exception:
                pass

            return False

        slides = cached.get("slides") or []

        if not slides:
            try:
                with embyflow_open_log(
                    "/tmp/embyflow_hero_cache_ttl.log",
                    "a"
                ) as log:
                    log.write(
                        "CACHE_EMPTY path=%s\n"
                        % cache_path
                    )
            except Exception:
                pass

            return False

        try:
            cache_timestamp = int(
                cached.get(
                    "last_sync_ts",
                    0
                )
                or 0
            )
        except Exception:
            cache_timestamp = 0

        if cache_timestamp <= 0:
            try:
                cache_timestamp = int(
                    os.path.getmtime(
                        cache_path
                    )
                )
            except Exception:
                cache_timestamp = 0

        if cache_timestamp > 0:
            cache_age = max(
                0,
                int(time.time()) - cache_timestamp
            )
        else:
            cache_age = 21601

        if cache_age >= 21600:
            # EMBYFLOW_STALE_HERO_IMMEDIATE_V1
            # Alten Cache sofort anzeigen. Die Rückgabe False
            # startet anschließend trotzdem die Aktualisierung
            # im Hintergrund.
            self.hero_slides = slides

            try:
                self.shuffle_hero_round()
            except Exception:
                self.hero_index = 0

            try:
                self.show_hero_slide()
            except Exception:
                pass

            try:
                self.hero_timer.start(
                    10000,
                    False
                )
            except Exception:
                pass

            try:
                with embyflow_open_log(
                    "/tmp/embyflow_hero_cache_ttl.log",
                    "a"
                ) as log:
                    log.write(
                        "CACHE_STALE_USED age=%s slides=%s path=%s\n"
                        % (
                            cache_age,
                            len(slides),
                            cache_path,
                        )
                    )
            except Exception:
                pass

            return False

        self.hero_slides = slides
        self.shuffle_hero_round()
        self.show_hero_slide()

        try:
            self.hero_timer.start(
                10000,
                False
            )
        except Exception:
            pass

        try:
            with embyflow_open_log(
                "/tmp/embyflow_hero_cache_ttl.log",
                "a"
            ) as log:
                log.write(
                    "CACHE_HIT age=%s slides=%s path=%s\n"
                    % (
                        cache_age,
                        len(slides),
                        cache_path,
                    )
                )
        except Exception:
            pass

        return True

    # EMBYFLOW_HERO_ASYNC_STARTUP_V1
    def load_hero_slides(self, force_refresh=False):
        """Hero sofort anzeigen; Serverabruf niemals im GUI-Thread."""
        cached_loaded = False

        if not force_refresh:
            try:
                cached_loaded = bool(
                    self.load_cached_hero_slides()
                )
            except Exception:
                cached_loaded = False

        # Ein vorhandener Cache wurde bereits von
        # load_cached_hero_slides() angezeigt.
        if cached_loaded:
            return

        # Ohne Cache sofort einen lokalen Platzhalter anzeigen.
        # Der Bildschirm bleibt dadurch niemals leer, während
        # Emby oder das Netzwerk langsam reagieren.
        if not getattr(self, "hero_slides", None):
            self.hero_slides = [
                {
                    "title": "EmbyFlow",
                    "meta": "",
                    "overview": "Inhalte werden im Hintergrund geladen.",
                    "backdrop": (
                        "/usr/lib/enigma2/python/Plugins/"
                        "Extensions/EmbyFlowE2/hero_bg.png"
                    ),
                }
            ]

        self.hero_index = 0

        try:
            self.show_hero_slide()
        except Exception:
            pass

        try:
            self.hero_timer.start(10000, False)
        except Exception:
            pass

        # Mehrfachstarts desselben Hintergrundabrufs verhindern.
        if getattr(self, "_hero_async_loading", False):
            return

        self._hero_async_loading = True
        self._hero_async_result = None
        self._hero_async_error = None

        try:
            generation = int(
                getattr(self, "_hero_async_generation", 0)
                + 1
            )
        except Exception:
            generation = 1

        self._hero_async_generation = generation

        # Der Poll-Timer läuft im Enigma2-Hauptthread und
        # übernimmt später sicher das Worker-Ergebnis.
        try:
            if not hasattr(self, "_hero_async_timer"):
                self._hero_async_timer = eTimer()

                try:
                    self._hero_async_timer.callback.append(
                        self._apply_async_hero_result
                    )
                except Exception:
                    pass

            self._hero_async_timer.start(
                250,
                False
            )
        except Exception:
            self._hero_async_loading = False
            return

        def hero_worker():
            try:
                slides = fetch_hero_slides(
                    HERO_STARTUP_LIMIT
                )

                if (
                    generation
                    == getattr(
                        self,
                        "_hero_async_generation",
                        -1
                    )
                ):
                    self._hero_async_result = (
                        list(slides or [])
                    )

            except Exception as error:
                self._hero_async_error = str(error)

            finally:
                self._hero_async_loading = False

        try:
            import threading

            worker = threading.Thread(
                target=hero_worker,
                name="EmbyFlowHeroFetch"
            )
            worker.daemon = True
            worker.start()

            try:
                with embyflow_open_log(
                    "/tmp/embyflow_hero_async.log",
                    "a"
                ) as log:
                    log.write(
                        "%s START generation=%s\n"
                        % (
                            time.strftime("%H:%M:%S"),
                            generation,
                        )
                    )
            except Exception:
                pass

        except Exception as error:
            self._hero_async_loading = False
            self._hero_async_error = str(error)


    def _apply_async_hero_result(self):
        """Worker-Ergebnis ausschließlich im GUI-Thread anwenden."""
        try:
            result = getattr(
                self,
                "_hero_async_result",
                None
            )

            loading = bool(
                getattr(
                    self,
                    "_hero_async_loading",
                    False
                )
            )

            if result is None:
                if loading:
                    try:
                        self._hero_async_timer.start(
                            250,
                            False
                        )
                    except Exception:
                        pass
                return

            self._hero_async_result = None

            if result:
                self.hero_slides = list(result)

                try:
                    write_json_file(
                        HERO_CACHE_DIR
                        + "/hero_slides.json",
                        {
                            "last_sync": time.strftime(
                                "%Y-%m-%d %H:%M"
                            ),
                            "last_sync_ts": int(
                                time.time()
                            ),
                            "slides": self.hero_slides,
                        }
                    )
                except Exception:
                    pass

                try:
                    self.shuffle_hero_round()
                except Exception:
                    self.hero_index = 0

                self.show_hero_slide()

                try:
                    self.hero_timer.start(
                        10000,
                        False
                    )
                except Exception:
                    pass

            try:
                with embyflow_open_log(
                    "/tmp/embyflow_hero_async.log",
                    "a"
                ) as log:
                    log.write(
                        "%s APPLY slides=%s error=%s\n"
                        % (
                            time.strftime("%H:%M:%S"),
                            len(result or []),
                            str(
                                getattr(
                                    self,
                                    "_hero_async_error",
                                    ""
                                )
                            ),
                        )
                    )
            except Exception:
                pass

        except Exception as error:
            try:
                with embyflow_open_log(
                    "/tmp/embyflow_hero_async_error.log",
                    "a"
                ) as log:
                    log.write(
                        "%s %s\n"
                        % (
                            time.strftime("%H:%M:%S"),
                            str(error),
                        )
                    )
            except Exception:
                pass


    def shuffle_hero_round(self, avoid_slide=None):
        if not self.hero_slides:
            self.hero_index = 0
            return

        try:
            random.shuffle(self.hero_slides)

            # Am Rundenwechsel nicht sofort dasselbe Bild erneut zeigen.
            if (
                avoid_slide is not None
                and len(self.hero_slides) > 1
                and self.hero_slides[0] is avoid_slide
            ):
                self.hero_slides.append(
                    self.hero_slides.pop(0)
                )
        except Exception as shuffle_error:
            try:
                with embyflow_open_log(
                    "/tmp/embyflow_hero_shuffle_error.log",
                    "a"
                ) as shuffle_log:
                    shuffle_log.write(
                        "%s\n" % str(shuffle_error)
                    )
            except:
                pass

        self.hero_index = 0

    def show_hero_slide(self):
        if not self.hero_slides:
            return
        slide = self.hero_slides[self.hero_index % len(self.hero_slides)]

        # HERO_SLIDESHOW_RUNTIME_LOG_V1
        try:
            hero_now = time.time()
            hero_previous = getattr(
                self,
                "_embyflow_hero_last_show_ts",
                None
            )

            if hero_previous is None:
                hero_delta = "START"
            else:
                hero_delta = "%.3f" % (
                    hero_now - hero_previous
                )

            self._embyflow_hero_last_show_ts = hero_now

            with embyflow_open_log(
                "/tmp/embyflow_hero_runtime.log",
                "a"
            ) as hero_log:
                hero_log.write(
                    "%s slide=%s/%s delta=%ss title=%s\n"
                    % (
                        time.strftime(
                            "%Y-%m-%d %H:%M:%S",
                            time.localtime(hero_now)
                        ),
                        (
                            self.hero_index
                            % len(self.hero_slides)
                        ) + 1,
                        len(self.hero_slides),
                        hero_delta,
                        str(slide.get("title", "")),
                    )
                )
        except Exception as hero_log_error:
            try:
                with embyflow_open_log(
                    "/tmp/embyflow_hero_runtime_error.log",
                    "a"
                ) as hero_error_log:
                    hero_error_log.write(
                        "%s\\n" % str(hero_log_error)
                    )
            except:
                pass

        self["hero_title"].setText(slide.get("title", ""))

        # HERO_META_MODERN_COLORS_V1
        # Einheitliche moderne Metazeile wie im Grid und auf der Startseite.
        hero_meta = str(
            slide.get("meta", "")
            or ""
        ).strip()

        hero_meta = re.sub(
            r"\s*\|\s*",
            " · ",
            hero_meta
        )

        hero_meta = re.sub(
            r"\s*·\s*",
            " · ",
            hero_meta
        )

        self["hero_meta"].setText(hero_meta)

        try:
            self["hero_meta"].instance.setForegroundColor(
                parseColor("#B8C0CC")
            )
        except Exception:
            pass

        overview = str(slide.get("overview", "") or "").strip()
        overview_limit = 145

        if len(overview) > overview_limit:
            shortened = overview[:overview_limit].rstrip()

            if " " in shortened:
                shortened = shortened.rsplit(" ", 1)[0]

            overview = shortened.rstrip(" .,:;-") + "..."

        self["hero_overview"].setText(overview)
        try:
            backdrop = slide.get("backdrop") or "/usr/lib/enigma2/python/Plugins/Extensions/EmbyFlowE2/hero_bg.png"
            pix = LoadPixmap(backdrop)
            if pix and self["hero_backdrop"].instance:
                if str(backdrop).startswith(CACHE_DIR):
                    embyflow_touch_cache_file(backdrop)
                self["hero_backdrop"].instance.setPixmap(pix)
                try:
                    self["hero_backdrop"].instance.setScale(1)
                except Exception:
                    pass
        except Exception as e:
            try:
                f = embyflow_open_log("/tmp/embyflow_hero_backdrop_error.log", "a")
                f.write("%s\\n" % str(e))
                f.close()
            except:
                pass

    def next_hero_slide(self):
        if not self.hero_slides:
            return
        previous_slide = self.hero_slides[
            self.hero_index % len(self.hero_slides)
        ]

        self.hero_index += 1

        if self.hero_index >= len(self.hero_slides):
            self.shuffle_hero_round(previous_slide)

        self.show_hero_slide()
        try:
            self.hero_timer.start(10000, False)
        except:
            pass


    def check_server_status(self):
        # EMBYFLOW_BETA84_SERVER_STATUS_AUTH_V2
        # Für die Statusprüfung den zentral gespeicherten Token nutzen.
        try:
            if not requests or not EMBY_SERVER or not EMBY_USERNAME:
                self.safe_set_label("server_state", "Server")
                self.safe_set_label("server_host", "-")
                self.safe_set_label("server_online", "Offline")
                return False

            server, token, user_id = get_emby_auth()

            self.safe_set_label("server_state", "Server")
            self.safe_set_label("server_host", "")

            if not server or not token or not user_id:
                self.safe_set_label("server_online", "Offline")
                return False

            self.safe_set_label("server_online", "Online")

            try:
                cached_status = read_json_file(
                    CACHE_DIR + "/server_status.json",
                    {}
                ) or {}

                username = (
                    cached_status.get("username")
                    or EMBY_USERNAME
                    or "User"
                )

                write_json_file(
                    CACHE_DIR + "/server_status.json",
                    {
                        "state": "verbunden",
                        "online": "Online",
                        "server": server,
                        "username": username,
                        "last_sync": time.strftime("%H:%M"),
                    }
                )
            except Exception:
                pass

            return True

        except Exception as error:
            self.safe_set_label("server_state", "Server")
            self.safe_set_label("server_online", "Offline")

            try:
                with embyflow_open_log(
                    "/tmp/embyflow_server_check.log",
                    "a"
                ) as log:
                    log.write("%s\n" % str(error))
            except Exception:
                pass

            return False

