    def _sidebar_main_rows_v24(self):
        return [
            ("Start", {"_sidebar_kind": "main", "_sidebar_name": "side_home"}),
            ("Weiterschauen", {"_sidebar_kind": "main", "_sidebar_name": "side_continue"}),
            ("Neu hinzugefügt", {"_sidebar_kind": "main", "_sidebar_name": "side_new"}),
            ("Filme", {"_sidebar_kind": "parent", "_sidebar_name": "side_movies", "_sidebar_mode": "movies"}),
            ("Serien", {"_sidebar_kind": "parent", "_sidebar_name": "side_series", "_sidebar_mode": "series"}),
            ("Doku", {"_sidebar_kind": "parent", "_sidebar_name": "side_doc", "_sidebar_mode": "docs"}),
            ("Favoriten", {"_sidebar_kind": "main", "_sidebar_name": "side_favorites"}),
            ("Bibliotheken", {"_sidebar_kind": "parent", "_sidebar_name": "side_local", "_sidebar_mode": "libraries"}),
            ("Suche", {"_sidebar_kind": "main", "_sidebar_name": "side_search"}),
            ("Nach Updates suchen", {"_sidebar_kind": "main", "_sidebar_name": "side_updates"}),
            ("Info / Einstellungen", {"_sidebar_kind": "main", "_sidebar_name": "side_settings"}),
        ]

    def _sidebar_rebuild_rows_v24(self):
        rows = []
        for label, data in self._sidebar_main_rows_v24():
            rows.append((label, dict(data)))
            if data.get("_sidebar_mode") == self.sidebar_mode:
                for child_label, child_data in self.sidebar_child_entries:
                    child_payload = dict(child_data or {})
                    child_payload["_sidebar_kind"] = "child"
                    child_payload["_sidebar_parent_mode"] = self.sidebar_mode
                    rows.append((child_label, child_payload))
        self.sidebar_entries = rows

    def _sidebar_row_text_v24(self, entry):
        try:
            label, data = entry
        except Exception:
            return ""
        data = data if isinstance(data, dict) else {}
        kind = data.get("_sidebar_kind")
        if kind == "child":
            return "    " + self._sidebar_display_label_v24(label, 19)
        if kind == "parent":
            arrow = "▾" if data.get("_sidebar_mode") == self.sidebar_mode else "▸"
            return "%s  %s" % (arrow, self._sidebar_display_label_v24(label, 18))
        return "   " + self._sidebar_display_label_v24(label, 19)

    def _sidebar_expand_v24(self, mode, title, entries, parent_focus):
        self.sidebar_mode = str(mode or "movies")
        self.sidebar_parent_title = str(title or "")
        self.sidebar_parent_focus = str(parent_focus or "side_movies")
        self.sidebar_child_entries = list(entries or [])
        self.sidebar_page_start = 0
        self._sidebar_rebuild_rows_v24()

        self.sidebar_cursor = 0
        for index, (_label, data) in enumerate(self.sidebar_entries):
            if isinstance(data, dict) and data.get("_sidebar_name") == self.sidebar_parent_focus:
                self.sidebar_cursor = index
                break

        self._sidebar_show_overlay_v24()
        self._sidebar_refresh_v24()

    def _sidebar_expand_movies_v24(self):
        self._sidebar_expand_v24(
            "movies",
            "Filme",
            self._sidebar_build_library_entries_v24("movies", "Movie"),
            "side_movies",
        )

    def _sidebar_expand_series_v24(self):
        self._sidebar_expand_v24(
            "series",
            "Serien",
            self._sidebar_build_library_entries_v24("tvshows", "Series"),
            "side_series",
        )

    def _sidebar_expand_doku_v24(self):
        self._sidebar_expand_v24(
            "docs",
            "Doku",
            self._sidebar_build_doku_entries_v24(),
            "side_doc",
        )

    def _sidebar_expand_libraries_ref11(self):
        self._sidebar_expand_v24(
            "libraries",
            "Bibliotheken",
            self._sidebar_build_all_server_views_ref11(),
            "side_local",
        )

    def _sidebar_refresh_v24(self):
        if self.sidebar_mode == "main":
            return

        total = len(self.sidebar_entries)
        page_size = int(self.sidebar_page_size or 18)
        self.sidebar_cursor = max(0, min(self.sidebar_cursor, max(0, total - 1)))

        if self.sidebar_cursor < self.sidebar_page_start:
            self.sidebar_page_start = self.sidebar_cursor
        elif self.sidebar_cursor >= self.sidebar_page_start + page_size:
            self.sidebar_page_start = self.sidebar_cursor - page_size + 1

        max_start = max(0, total - page_size)
        self.sidebar_page_start = max(0, min(self.sidebar_page_start, max_start))

        self["side_sub_title"].setText("NAVIGATION · %s" % self.sidebar_parent_title.upper())
        visible = self.sidebar_entries[
            self.sidebar_page_start:self.sidebar_page_start + page_size
        ]

        for i in range(page_size):
            label_widget = self["side_sub_%d" % i]
            if i < len(visible):
                label_widget.setText(self._sidebar_row_text_v24(visible[i]))
            else:
                label_widget.setText("")

        if total > page_size:
            first = self.sidebar_page_start + 1
            last = min(total, self.sidebar_page_start + page_size)
            self["side_sub_page"].setText("%d–%d / %d  ▲▼" % (first, last, total))
        else:
            self["side_sub_page"].setText("▲▼  OK auswählen")

        new_focus_items = []
        for visible_index, _entry in enumerate(visible):
            actual_index = self.sidebar_page_start + visible_index
            new_focus_items.append((
                "sub_item_%d" % visible_index,
                "sidebar_row",
                actual_index,
                44,
                224 + (34 * visible_index),
                198,
                30,
            ))

        self.focus_items = new_focus_items or list(self.home_focus_items)
        visible_pos = self.sidebar_cursor - self.sidebar_page_start
        self.focus_index = max(0, min(len(self.focus_items) - 1, visible_pos))
        self.update_focus()

    def _sidebar_collapse_v24(self):
        parent_focus = self.sidebar_parent_focus or "side_home"
        self.sidebar_mode = "main"
        self.sidebar_parent_title = ""
        self.sidebar_child_entries = []
        self.sidebar_entries = []
        self.sidebar_cursor = -1
        self.sidebar_page_start = 0
        self._sidebar_hide_overlay_v24()
        self.focus_items = list(self.home_focus_items)
        self.set_focus(parent_focus)

    def _sidebar_up_v24(self):
        if self.sidebar_cursor > 0:
            self.sidebar_cursor -= 1
            self._sidebar_refresh_v24()

    def _sidebar_down_v24(self):
        if self.sidebar_cursor < len(self.sidebar_entries) - 1:
            self.sidebar_cursor += 1
            self._sidebar_refresh_v24()

    def _sidebar_activate_main_v24(self, name):
        if name == "side_continue":
            self.open_continue_view()
        elif name == "side_new":
            self.open_new_menu()
        elif name == "side_favorites":
            self.open_favorites_view()
        elif name == "side_local":
            self.open_local_media_menu()
        elif name == "side_search":
            self.open_search_keyboard()
        elif name == "side_updates":
            self.session.open(EmbyFlowUpdateScreen)
        elif name == "side_settings":
            self.session.open(EmbyFlowInfoScreen)
        elif name == "side_home":
            # Already on Home; collapsing is the expected action.
            return

    def _sidebar_ok_v24(self):
        if not (0 <= self.sidebar_cursor < len(self.sidebar_entries)):
            return

        label, data = self.sidebar_entries[self.sidebar_cursor]
        data = data if isinstance(data, dict) else {}
        kind = data.get("_sidebar_kind")

        if kind == "child":
            self._sidebar_open_selection_v24(label, data)
            return

        name = data.get("_sidebar_name")
        mode = data.get("_sidebar_mode")
        if kind == "parent":
            if mode == self.sidebar_mode:
                self._sidebar_collapse_v24()
            elif mode == "movies":
                self._sidebar_expand_movies_v24()
            elif mode == "series":
                self._sidebar_expand_series_v24()
            elif mode == "docs":
                self._sidebar_expand_doku_v24()
            elif mode == "libraries":
                self._sidebar_expand_libraries_ref11()
            return

        self._sidebar_collapse_v24()
        self._sidebar_activate_main_v24(name)

    def _sidebar_open_selection_v24(self, label, data):
        if not isinstance(data, dict):
            return

        try:
            embyflow_acknowledge_library_count(label, data)
            embyflow_save_choice_last_opened(label, data)
        except Exception:
            pass

        if data.get("all_items"):
            include_types = data.get("include_types") or "Movie"
            lib_name = data.get("library_name") or label
            results = cached_emby_category_items(include_types, 120)
        elif data.get("genres"):
            include_types = data.get("include_types") or "Movie"
            lib_name = data.get("genre_name") or label
            results = cached_emby_genre_items(include_types, data.get("genres"), 120)
        else:
            lib_id = data.get("library_id")
            lib_name = data.get("library_name") or label
            include_types = data.get("include_types") or "Movie"
            collection_type = data.get("collection_type") or ""

            if data.get("dynamic_server_view"):
                results = cached_emby_dynamic_view_items(lib_id, collection_type, 120)
            else:
                results = cached_emby_library_items(lib_id, include_types, 120)

            if not results and include_types == "Series" and not data.get("dynamic_server_view"):
                results = cached_emby_category_items("Series", 120)

            for result_item in results or []:
                try:
                    result_item["_embyflow_parent_id"] = str(lib_id or "")
                    result_item["_embyflow_include_types"] = str(include_types or "Movie")
                    result_item["_embyflow_library_name"] = str(lib_name or "")
                except Exception:
                    pass

        # Open the selected library grid directly. When the grid closes the
        # user returns to Home with the left hierarchy still expanded.
        self.session.open(
            EmbyFlowGridScreen,
            "EmbyFlow E2 - %s" % lib_name,
            results or [],
        )

    def cancel_pressed(self):
        if getattr(self, "sidebar_mode", "main") != "main":
            self._sidebar_collapse_v24()
            return
        self.close()

    def current_focus(self):
        if self.focus_index < 0:
            self.focus_index = 0
        if self.focus_index >= len(self.focus_items):
            self.focus_index = len(self.focus_items) - 1
        return self.focus_items[self.focus_index]

    def focus_name(self):
        return self.current_focus()[0]

    def set_focus(self, name):
        for index, item in enumerate(self.focus_items):
            if item[0] == name:
                self.focus_index = index
                self.update_focus()
                return

    def nearest_focus_by_x(self, names):
        current = self.current_focus()
        cx = current[3] + current[5] / 2
        best_name = names[0]
        best_distance = 99999
        for name in names:
            for item in self.focus_items:
                if item[0] == name:
                    ix = item[3] + item[5] / 2
                    distance = abs(ix - cx)
                    if distance < best_distance:
                        best_distance = distance
                        best_name = name
        return best_name

    def update_grid_title_marker(self):
        try:
            for i in range(10):
                txt = self["t%d" % i].getText() or ""
                while txt.startswith(">"):
                    txt = txt[1:].strip()
                self["t%d" % i].setText(txt)

            if not self.az_mode:
                txt = self["t%d" % self.focus].getText() or ""
                while txt.startswith(">"):
                    txt = txt[1:].strip()
                self["t%d" % self.focus].setText("> " + txt)
        except Exception as e:
            try:
                f=embyflow_open_log("/tmp/embyflow_grid_marker_error.log","a")
                f.write("%s\n" % str(e))
                f.close()
            except:
                pass


    def update_focus(self):
        name, area, col, x, y, w, h = self.current_focus()

        if self["focus_top"].instance:
            self["focus_top"].instance.hide()
            self["focus_glow"].instance.hide()
            self["focus_bottom"].instance.hide()
            self["focus_left"].instance.hide()
            self["focus_right"].instance.hide()
            self["nav_focus_marker"].instance.hide()
            self["nav_focus_underline"].instance.hide()
            self["nav_focus_accent"].instance.hide()

            if name.startswith("nav_dyn_"):
                actual_index = int(col)
                focus_text = ""
                try:
                    if (
                        0 <= actual_index
                        < len(self.direct_nav_entries_ref12)
                    ):
                        focus_text = (
                            "   "
                            + self._sidebar_display_label_v24(
                                self.direct_nav_entries_ref12[
                                    actual_index
                                ][0],
                                20
                            )
                        )
                except Exception:
                    focus_text = ""

                self["nav_focus_marker"].setText(
                    focus_text
                )
                self["nav_focus_marker"].instance.move(
                    EFP(x, y)
                )
                self["nav_focus_marker"].instance.resize(
                    EFS(w, h)
                )
                self["nav_focus_marker"].instance.show()
                return

            if name.startswith("sub_item_"):
                actual_index = int(col)
                if 0 <= actual_index < len(self.sidebar_entries):
                    focus_text = self._sidebar_row_text_v24(
                        self.sidebar_entries[actual_index]
                    )
                else:
                    focus_text = ""

                self["nav_focus_marker"].setText(focus_text)
                self["nav_focus_marker"].instance.move(EFP(x, y))
                self["nav_focus_marker"].instance.resize(EFS(w, h))
                self["nav_focus_marker"].instance.show()

                # EMBYFLOW_HOME_SIDEBAR_V26_SOFTFOCUS
                # The filled cyan focus tile is the only navigation focus cue.
                # No pink side stripe and no cyan underline.
                return

            if name.startswith("side_"):
                nav_labels = {
                    "side_home": "Start",
                    "side_continue": "Weiterschauen",
                    "side_new": "Neu",
                    "side_movies": "Filme",
                    "side_series": "Serien",
                    "side_doc": "Doku",
                    "side_favorites": "Favoriten",
                    "side_local": "Bibliotheken",
                    "side_search": "Suche",
                    "side_updates": "Updates",
                    "side_settings": "Info",
                }

                self["nav_focus_marker"].setText(
                    "   " + nav_labels.get(name, "")
                )
                self["nav_focus_marker"].instance.move(
                    EFP(x, y)
                )
                self["nav_focus_marker"].instance.resize(
                    EFS(w, h)
                )
                self["nav_focus_marker"].instance.show()

                # EMBYFLOW_HOME_SIDEBAR_V26_SOFTFOCUS
                # Filled soft-cyan focus tile only; intentionally no focus stripes.
                return

            focus_x = x
            focus_w = w

            if name.startswith("poster_"):
                # Näher ans Poster und an beiden Seiten etwas kürzer.
                focus_y = y + h + 15
                focus_x = x + 7
                focus_w = max(20, w - 14)
            elif name.startswith("action_"):
                # ACTION_UNDERLINES_TEXT_WIDTH_V1
                # Jeder Unterstrich wird nur unter der jeweiligen
                # Beschriftung positioniert – nicht unter dem Farbfeld.
                focus_y = y + h + 16

                action_underline_geometry = {
                    # ACTION_UNDERLINES_TEXT_START_V2
                    # x entspricht bereits dem Anfang der Beschriftung.
                    "action_back": (0, 66),
                    "action_play": (24, 60),
                    "action_search": (0, 68),
                    "action_details": (34, 66),
                }

                action_offset, action_width = (
                    action_underline_geometry.get(
                        name,
                        (24, max(40, w - 48))
                    )
                )

                focus_x = x + action_offset
                focus_w = action_width
            else:
                focus_y = y + h + 2

            # Weicher, etwas großzügigerer Lichtschein.
            self["focus_glow"].instance.move(
                EFP(focus_x - 4, focus_y - 4)
            )
            self["focus_glow"].instance.resize(
                EFS(focus_w + 6, 6)
            )
            self["focus_glow"].instance.show()

            # Schmaler, klarer weißer Kern.
            self["focus_bottom"].instance.move(
                EFP(focus_x, focus_y)
            )
            self["focus_bottom"].instance.resize(
                EFS(focus_w, 1)
            )
            self["focus_bottom"].instance.show()

    def log_key(self, key):
        try:
            name, area, col, x, y, w, h = self.current_focus()
            f = embyflow_open_log("/tmp/embyflow_keys.log", "a")
            f.write("%s index=%d name=%s area=%s col=%d\n" % (key, self.focus_index, name, area, col))
            f.close()
        except:
            pass

    def left(self):
        self.log_key("LEFT")
        if getattr(self, "sidebar_mode", "main") != "main":
            self._sidebar_collapse_v24()
            return
        name = self.focus_name()

        if name.startswith("nav_dyn_"):
            return

        poster_order = ["poster_movie_1", "poster_movie_2", "poster_series_1", "poster_series_2", "poster_doc_1", "poster_doc_2"]
        action_order = ["action_back", "action_play", "action_search", "action_details"]

        if name in poster_order:
            pos = poster_order.index(name)
            if pos > 0:
                self.set_focus(poster_order[pos - 1])
            else:
                self._direct_nav_return_focus_ref12()
        elif name in action_order:
            pos = action_order.index(name)
            if pos > 0:
                self.set_focus(action_order[pos - 1])
            else:
                self._direct_nav_return_focus_ref12()
        elif name == "details_top":
            self.set_focus("play_top")
        elif name == "play_top":
            self._direct_nav_return_focus_ref12()

    def right(self):
        self.log_key("RIGHT")
        if getattr(self, "sidebar_mode", "main") != "main":
            return
        name = self.focus_name()

        if name.startswith("nav_dyn_"):
            self.set_focus("poster_movie_1")
            return
        try:
            f = embyflow_open_log("/tmp/embyflow_right_debug.log", "a")
            f.write("RIGHT focus=%s\n" % str(name))
            f.close()
        except:
            pass
        poster_order = ["poster_movie_1", "poster_movie_2", "poster_series_1", "poster_series_2", "poster_doc_1", "poster_doc_2"]
        action_order = ["action_back", "action_play", "action_search", "action_details"]
        if name.startswith("side_"):
            self.set_focus("poster_movie_1")
        elif name == "play_top":
            self.set_focus("details_top")
        elif name == "details_top":
            self.set_focus("poster_series_1")
        elif name in poster_order:
            pos = poster_order.index(name)
            self.set_focus(poster_order[pos + 1] if pos < len(poster_order) - 1 else "action_search")
        elif name in action_order:
            pos = action_order.index(name)
            if pos < len(action_order) - 1:
                self.set_focus(action_order[pos + 1])

    def up(self):
        self.log_key("UP")
        try:
            if self.focus_name().startswith("nav_dyn_"):
                self._direct_nav_move_ref12(-1)
                return
        except Exception:
            pass

        if getattr(self, "sidebar_mode", "main") != "main":
            self._sidebar_up_v24()
            return
        name = self.focus_name()
        side_order = ["side_home", "side_continue", "side_new", "side_movies", "side_series", "side_doc", "side_favorites", "side_local", "side_search", "side_updates", "side_settings"]
        action_order = ["action_back", "action_play", "action_search", "action_details"]
        poster_order = ["poster_movie_1", "poster_movie_2", "poster_series_1", "poster_series_2", "poster_doc_1", "poster_doc_2"]
        if name in side_order:
            pos = side_order.index(name)
            if pos > 0:
                self.set_focus(side_order[pos - 1])
        elif name in action_order:
            self.set_focus(self.nearest_focus_by_x(poster_order))
        elif name in poster_order:
            self.set_focus(self.nearest_focus_by_x(["play_top", "details_top"]))

    def down(self):
        self.log_key("DOWN")
        try:
            if self.focus_name().startswith("nav_dyn_"):
                self._direct_nav_move_ref12(1)
                return
        except Exception:
            pass

        if getattr(self, "sidebar_mode", "main") != "main":
            self._sidebar_down_v24()
            return
        name = self.focus_name()
        side_order = ["side_home", "side_continue", "side_new", "side_movies", "side_series", "side_doc", "side_favorites", "side_local", "side_search", "side_updates", "side_settings"]
        action_order = ["action_back", "action_play", "action_search", "action_details"]
        poster_order = ["poster_movie_1", "poster_movie_2", "poster_series_1", "poster_series_2", "poster_doc_1", "poster_doc_2"]
        if name in side_order:
            pos = side_order.index(name)
            if pos < len(side_order) - 1:
                self.set_focus(side_order[pos + 1])
        elif name in ["play_top", "details_top"]:
            self.set_focus(self.nearest_focus_by_x(poster_order))
        elif name in poster_order:
            self.set_focus(self.nearest_focus_by_x(action_order))

    def ok_pressed(self):
        try:
            if self.focus_name().startswith("nav_dyn_"):
                self._direct_nav_activate_ref12()
                return
        except Exception:
            pass

        if getattr(self, "sidebar_mode", "main") != "main":
            self._sidebar_ok_v24()
            return

        name, area, col, x, y, w, h = self.current_focus()

        if name == "side_movies":
            self._sidebar_expand_movies_v24()
        elif name == "side_continue":
            self.open_continue_view()
        elif name == "side_new":
            self.open_new_menu()
        elif name == "side_series":
            self._sidebar_expand_series_v24()
        elif name == "side_doc":
            self._sidebar_expand_doku_v24()
        elif name == "side_local":
            self._sidebar_expand_libraries_ref11()
        elif area == "local_media":
            self.open_local_media_menu()
        elif area == "favorites":
            self.open_favorites_view()
        elif area == "search":
            self.open_search_keyboard()
        elif area == "updates":
            self.session.open(EmbyFlowUpdateScreen)
        elif area == "settings":
            self.session.open(EmbyFlowInfoScreen)
        elif area == "back":
            self.close()
        else:
            self.open_selected()

    def load_search_history(self):
        try:
            if not os.path.exists(SEARCH_HISTORY_FILE):
                return []

            f = open(SEARCH_HISTORY_FILE, "r")
            data = json.loads(f.read())
            f.close()

            history = []

            if isinstance(data, list):
                for item in data:
                    if isinstance(item, str):
                        term = item.strip()

                        if term:
                            history.append({
                                "term": term,
                                "timestamp": "",
                            })

                    elif isinstance(item, dict):
                        term = str(item.get("term") or "").strip()
                        timestamp = str(
                            item.get("timestamp") or ""
                        ).strip()

                        if term:
                            history.append({
                                "term": term,
                                "timestamp": timestamp,
                            })

            return history

        except:
            pass

        return []

    def save_search_history(self, term):
        try:
            term = (term or "").strip()

            if not term:
                return

            history = self.load_search_history()
            cleaned = []

            for item in history:
                old_term = str(
                    item.get("term") or ""
                ).strip()

                if old_term and old_term.lower() != term.lower():
                    cleaned.append(item)

            timestamp = __import__("time").strftime(
                "%Y-%m-%dT%H:%M:%S",
                __import__("time").localtime()
            )

            cleaned.insert(0, {
                "term": term,
                "timestamp": timestamp,
            })

            cleaned = cleaned[:20]

            f = open(SEARCH_HISTORY_FILE, "w")
            f.write(json.dumps(cleaned))
            f.close()

        except Exception as e:
            try:
                f = embyflow_open_log(
                    "/tmp/embyflow_search_history_error.log",
                    "a"
                )
                f.write("%s\n" % str(e))
                f.close()
            except:
                pass

    def clear_search_history(self):
        try:
            f = open(SEARCH_HISTORY_FILE, "w")
            f.write("[]")
            f.close()
        except:
            pass
        self.open_native_list("EmbyFlow E2 - Suche", [("Suchverlauf geloescht", "deleted")])

    def open_search_keyboard(self):
        # EMBYFLOW_DISNEY_SEARCH_BASE3
        self.session.open(EmbyFlowDisneySearchScreen)


    def search_keyboard_callback(self, text):
        try:
            term = unicodedata.normalize(
                "NFC",
                str(text or "")
            ).strip()
        except Exception:
            term = str(text or "").strip()
        if not term:
            history = self.load_search_history()
            entries = [("Neue Suche", "new_search", "")]

            for item in history:
                term = str(item.get("term") or "").strip()
                timestamp = str(
                    item.get("timestamp") or ""
                ).strip()

                if term:
                    entries.append((
                        term,
                        "history:" + term,
                        timestamp,
                    ))

            if history:
                entries.append((
                    "Suchverlauf loeschen",
                    "clear_history",
                    "",
                ))
            self.session.openWithCallback(self.search_history_callback, EmbyFlowChoiceScreen, "EmbyFlow E2 - Suche", entries)
            return

        self.save_search_history(term)

        # EMBYFLOW_SEARCH_TYPE_SELECTOR_V1
        self.pending_search_term = term

        entries = [
            (
                "Filme und Serien",
                {
                    "term": term,
                    "include_types": "Movie,Series",
                    "result_label": "Filme und Serien",
                },
                "Standard",
            ),
            (
                "Nur Filme",
                {
                    "term": term,
                    "include_types": "Movie",
                    "result_label": "Filme",
                },
                "",
            ),
            (
                "Nur Serien",
                {
                    "term": term,
                    "include_types": "Series",
                    "result_label": "Serien",
                },
                "",
            ),

            # EMBYFLOW_SEARCH_GOOGLE_GAG_ENTRY_V1
            (
                "Kein Plan – Google fragen …",
                {
                    "term": term,
                    "action": "google_gag",
                },
                "",
            ),
        ]

        self.session.openWithCallback(
            self.search_type_callback,
            EmbyFlowChoiceScreen,
            "Was möchtest du suchen?",
            entries,
        )


    def search_type_callback(self, selection):
        # EMBYFLOW_SEARCH_TYPE_SELECTOR_V1
        if not selection:
            term = str(
                getattr(
                    self,
                    "pending_search_term",
                    "",
                )
                or ""
            ).strip()

            self.pending_search_term = ""

            if term:
                self.session.openWithCallback(
                    self.search_keyboard_callback,
                    EmbyFlowCurvedSearchKeyboard,
                    title="EmbyFlow Suche",
                    text=term,
                )

            return

        data = (
            selection[1]
            if len(selection) > 1
            else None
        )

        if not isinstance(data, dict):
            return

        try:
            term = unicodedata.normalize(
                "NFC",
                str(data.get("term") or ""),
            ).strip()
        except Exception:
            term = str(
                data.get("term") or ""
            ).strip()

        # EMBYFLOW_SEARCH_GOOGLE_GAG_ACTION_V1
        action = str(
            data.get("action") or ""
        ).strip()

        if action == "google_gag":
            self.pending_search_term = ""

            self.session.open(
                EmbyFlowGoogleGagScreen,
                term,
            )

            return

        include_types = str(
            data.get("include_types")
            or "Movie,Series"
        ).strip()

        allowed_types = (
            "Movie",
            "Series",
            "Movie,Series",
        )

        if include_types not in allowed_types:
            include_types = "Movie,Series"

        self.pending_search_term = ""

        if not term:
            return

        self.run_typed_search(
            term,
            include_types,
        )

    def run_typed_search(
        self,
        term,
        include_types
    ):
        # EMBYFLOW_SEARCH_TYPE_SELECTOR_V1
        labels = {
            "Movie": "Filme",
            "Series": "Serien",
            "Movie,Series": "Filme und Serien",
        }

        result_label = labels.get(
            include_types,
            "Filme und Serien",
        )

        results = emby_search_items(
            term,
            60,
            include_types,
        )

        self.open_results_view(
            "Suche %s: %s"
            % (
                result_label,
                term,
            ),
            results,
            "Keine Treffer in %s für: %s"
            % (
                result_label,
                term,
            ),
        )

    def search_history_callback(self, selection):
        if not selection:
            return

        label = selection[0]
        action = selection[1]

        if action == "new_search":
            self.open_search_keyboard()
            return
        if action == "clear_history":
            self.clear_search_history()
            return
        if isinstance(action, str) and action.startswith("history:"):
            term = action.split(":", 1)[1]
            self.search_keyboard_callback(term)

    def search_result_callback(self, selection):
        if not selection:
            return
        # EMBYFLOW_SELECTION_UNPACK_FIX_V1
        label = (
            selection[0]
            if len(selection) > 0
            else ""
        )
        data = (
            selection[1]
            if len(selection) > 1
            else None
        )
        if isinstance(data, dict):
            self.session.open(EmbyFlowDetailScreen, data)

