    def open_emby_library_menu(
        self,
        title,
        collection_type,
        include_types
    ):
        # DYNAMIC_SERVER_LIBRARY_MENU_DEV_V1
        # Keine festen Bibliotheksnamen oder IDs.
        # Immer die aktuellen Views des angemeldeten Servers verwenden.
        all_views = emby_library_views(None)

        # LIBRARY_MENU_COUNT_CONTEXT_V1
        library_view_counts = (
            emby_library_view_counts(
                all_views
            )
        )

        wanted_type = str(
            collection_type or ""
        ).strip().lower()

        entries = []

        if include_types == "Series":
            entries.append((
                "Alle Serien",
                {
                    "all_items": True,
                    "library_name": "Alle Serien",
                    "include_types": "Series",
                }
            ))

        primary = []
        additional = []

        for view in all_views:
            view_type = str(
                view.get("type") or ""
            ).strip().lower()

            if view_type == wanted_type:
                primary.append(view)

            elif (
                wanted_type == "movies"
                and view_type not in (
                    "movies",
                    "tvshows",
                )
            ):
                # Sammlungen, Web-Streams und unbekannte zukünftige
                # CollectionTypes bleiben sichtbar.
                additional.append(view)

        def append_view(view, prefix=""):
            label = str(
                view.get("name")
                or "Unbenannte Bibliothek"
            )

            if prefix:
                label = "%s: %s" % (
                    prefix,
                    label
                )

            entries.append((
                label,
                {
                    "library_id": view.get("id"),
                    "library_name": (
                        view.get("name")
                        or label
                    ),
                    "collection_type": (
                        view.get("type")
                        or ""
                    ),
                    "include_types": (
                        embyflow_collection_include_types(
                            view.get("type")
                        )
                        or include_types
                    ),
                    "dynamic_server_view": True,
                    "library_count": (
                        library_view_counts.get(
                            str(view.get("id") or "")
                        )
                    ),
                    "library_new_count": (
                        embyflow_library_new_count(
                            label,
                            view.get("id"),
                            (
                                embyflow_collection_include_types(
                                    view.get("type")
                                )
                                or include_types
                            ),
                            library_view_counts.get(
                                str(
                                    view.get("id")
                                    or ""
                                )
                            )
                        )
                    ),
                }
            ))

        for view in primary:
            append_view(view)

        for view in additional:
            view_type = str(
                view.get("type") or ""
            ).strip().lower()

            if view_type == "boxsets":
                prefix = "Sammlungen"

            elif view_type:
                prefix = view_type

            else:
                prefix = "Weitere"

            append_view(
                view,
                prefix
            )

        while len(entries) < 8:
            entries.append((
                "",
                None
            ))

        if include_types == "Series":
            genre_entries = [
                ("Krimi", ["Krimi", "Crime"]),
                (
                    "Comedy",
                    [
                        "Comedy",
                        "Komödie",
                        "Komodie",
                    ]
                ),
                ("Drama", ["Drama"]),
                ("Action", ["Action"]),
                ("Mystery", ["Mystery"]),
                (
                    "Sci-Fi",
                    [
                        "Science Fiction",
                        "Sci-Fi",
                        "SciFi",
                    ]
                ),
                ("Fantasy", ["Fantasy"]),
                (
                    "Animation",
                    [
                        "Animation",
                        "Anime",
                    ]
                ),
                (
                    "Kids",
                    [
                        "Kids",
                        "Kinder",
                        "Family",
                        "Familie",
                    ]
                ),
                (
                    "Doku",
                    [
                        "Documentary",
                        "Dokumentation",
                        "Doku",
                    ]
                ),
            ]

        else:
            genre_entries = [
                ("Krimi", ["Krimi", "Crime"]),
                (
                    "Comedy",
                    [
                        "Comedy",
                        "Komödie",
                        "Komodie",
                    ]
                ),
                ("Drama", ["Drama"]),
                ("Action", ["Action"]),
                ("Thriller", ["Thriller"]),
                ("Horror", ["Horror"]),
                (
                    "Sci-Fi",
                    [
                        "Science Fiction",
                        "Sci-Fi",
                        "SciFi",
                    ]
                ),
                ("Fantasy", ["Fantasy"]),
                (
                    "Abenteuer",
                    [
                        "Adventure",
                        "Abenteuer",
                    ]
                ),
                (
                    "Doku",
                    [
                        "Documentary",
                        "Dokumentation",
                        "Doku",
                    ]
                ),
            ]

        for label, genres in genre_entries:
            entries.append((
                "Genre: %s" % label,
                {
                    "genre_name": label,
                    "genres": genres,
                    "include_types": include_types,
                }
            ))

        if not entries:
            entries = [
                (
                    "Keine Emby-Bibliotheken",
                    None
                )
            ]

        entries = add_embyflow_library_timestamps(
            entries
        )

        self.session.openWithCallback(
            self.library_menu_callback,
            EmbyFlowChoiceScreen,
            title,
            entries
        )

    def library_menu_callback(self, selection):
        if not selection:
            return

        label = selection[0]
        data = selection[1] if len(selection) > 1 else None
        try:
            with embyflow_open_log("/tmp/embyflow_menu_path.log", "a") as log:
                log.write("label=%r data=%r\n" % (label, data))
        except:
            pass
        if not isinstance(data, dict):
            return

        # Neue Inhalte gelten nach dem Öffnen der
        # Bibliothek als gesehen.
        embyflow_acknowledge_library_count(
            label,
            data
        )

        # Öffnungszeitpunkt speichern, sobald eine Kategorie gewählt wird.
        embyflow_save_choice_last_opened(
            label,
            data
        )
        if data.get("all_items"):
            include_types = data.get("include_types") or "Movie"
            lib_name = data.get("library_name") or label
            results = cached_emby_category_items(include_types, 120)
            self.open_library_results_view(
                "EmbyFlow E2 - %s" % lib_name,
                results,
                "Keine Einträge",
                include_types
            )
            return
        if data.get("genres"):
            include_types = data.get("include_types") or "Movie"
            genre_name = data.get("genre_name") or label
            results = cached_emby_genre_items(include_types, data.get("genres"), 120)
            self.open_library_results_view(
                "EmbyFlow E2 - %s" % genre_name,
                results,
                "Keine Einträge für Genre: %s" % genre_name,
                include_types
            )
            return
        lib_id = data.get("library_id")
        lib_name = data.get("library_name") or label
        include_types = (
            data.get("include_types")
            or "Movie"
        )
        collection_type = (
            data.get("collection_type")
            or ""
        )

        if data.get("dynamic_server_view"):
            results = cached_emby_dynamic_view_items(
                lib_id,
                collection_type,
                120
            )
        else:
            results = cached_emby_library_items(
                lib_id,
                include_types,
                120
            )

        if (
            not results
            and include_types == "Series"
            and not data.get(
                "dynamic_server_view"
            )
        ):
            results = cached_emby_category_items(
                "Series",
                120
            )

        # SERVER_SIDE_AZ_CONTEXT_DEV_V1
        for result_item in results or []:
            try:
                result_item[
                    "_embyflow_parent_id"
                ] = str(lib_id or "")

                result_item[
                    "_embyflow_include_types"
                ] = str(
                    include_types or "Movie"
                )

                result_item[
                    "_embyflow_library_name"
                ] = str(lib_name or "")

            except Exception:
                pass

        self.open_library_results_view(
            "EmbyFlow E2 - %s" % lib_name,
            results,
            "Keine Einträge",
            include_types
        )

    def open_emby_library_by_name(self, title, library_name, include_types):
        views = emby_library_views(None)
        wanted = None
        for v in views:
            if (v.get("name") or "").lower() == library_name.lower():
                wanted = v
                break
        if not wanted:
            if library_name.lower() == "doku":
                self.open_doku_grid()
                return
            self.session.openWithCallback(lambda selection: None, EmbyFlowChoiceScreen, title, [("Bibliothek nicht gefunden: %s" % library_name, None)])
            return
        results = cached_emby_library_items(wanted.get("id"), include_types, 120)
        if not results and library_name.lower() == "doku":
            self.open_doku_grid()
            return
        self.open_results_view(title, results, "Keine Einträge")

