def _embyflow_v11_7_7_bif_header(data):
    if not isinstance(data, (bytes, bytearray)) or len(data) < 72:
        return None
    if bytes(data[:8]) != EMBYFLOW_V11_7_7_BIF_MAGIC:
        return None
    try:
        version = int.from_bytes(bytes(data[8:12]), "little")
        count = int.from_bytes(bytes(data[12:16]), "little")
        multiplier = int.from_bytes(bytes(data[16:20]), "little") or 1000
    except Exception:
        return None
    if version != 0 or count <= 0 or count > 100000:
        return None
    index_end = 64 + ((count + 1) * 8)
    if index_end > len(data):
        return None
    return count, multiplier


def _embyflow_v11_7_7_load_bif(self):
    existing = getattr(self, "_embyflow_v11_7_7_bif_data", None)
    if isinstance(existing, (bytes, bytearray)) and _embyflow_v11_7_7_bif_header(existing):
        return bytes(existing)

    cache_path = _embyflow_v11_7_7_bif_cache_path(self)
    if cache_path and os.path.isfile(cache_path):
        try:
            with open(cache_path, "rb") as handle:
                data = handle.read()
            header = _embyflow_v11_7_7_bif_header(data)
            if header:
                self._embyflow_v11_7_7_bif_data = data
                return data
        except Exception:
            pass
        try:
            os.remove(cache_path)
        except Exception:
            pass

    if not requests:
        return b""

    # One attempt per navigator/proxy instance. The existing global HTTP
    # in-flight de-duplication prevents duplicate concurrent GETs for the same URL.
    if bool(getattr(self, "_embyflow_v11_7_7_bif_attempted", False)):
        return b""
    self._embyflow_v11_7_7_bif_attempted = True

    try:
        server, token = self._preview_auth_context_v3()
    except Exception:
        server, token = "", ""

    item_id = str(getattr(self.player, "item_id", "") or "").strip()
    media_source_id = _embyflow_v11_7_7_media_source_id(self.player)
    if not server or not token or not item_id:
        return b""

    url = "%s/Videos/%s/index.bif" % (str(server).rstrip("/"), item_id)
    params = {"Width": str(EMBYFLOW_V11_7_7_BIF_WIDTH)}
    if media_source_id:
        params["MediaSourceId"] = media_source_id
    headers = {
        "X-Emby-Token": token,
        "X-Emby-Authorization": AUTH_HEADER,
        "Accept": "application/octet-stream,*/*;q=0.8",
    }

    started = time.time()
    try:
        self._preview_v6_log(
            "v11_7_7_bif_start",
            item=item_id,
            width=EMBYFLOW_V11_7_7_BIF_WIDTH,
            has_media_source=int(bool(media_source_id)),
        )
    except Exception:
        pass

    try:
        response = embyflow_http_get(
            url,
            headers=headers,
            params=params,
            timeout=EMBYFLOW_V11_7_7_BIF_TIMEOUT,
            verify=True,
        )
    except Exception as error:
        try:
            self._preview_v6_log(
                "v11_7_7_bif_http_error",
                item=item_id,
                elapsed_ms=int(max(0.0, time.time() - started) * 1000.0),
                error_type=type(error).__name__,
            )
        except Exception:
            pass
        return b""

    elapsed_ms = int(max(0.0, time.time() - started) * 1000.0)
    status = int(getattr(response, "status_code", 0) or 0)
    if status != 200:
        try:
            self._preview_v6_log(
                "v11_7_7_bif_miss",
                item=item_id,
                status=status,
                elapsed_ms=elapsed_ms,
                has_media_source=int(bool(media_source_id)),
            )
        except Exception:
            pass
        return b""

    data = getattr(response, "content", b"") or b""
    header = _embyflow_v11_7_7_bif_header(data)
    if not header:
        try:
            self._preview_v6_log(
                "v11_7_7_bif_invalid",
                item=item_id,
                bytes=len(data),
                elapsed_ms=elapsed_ms,
            )
        except Exception:
            pass
        return b""

    count, multiplier = header
    if cache_path:
        temporary = cache_path + ".tmp"
        try:
            with open(temporary, "wb") as handle:
                handle.write(data)
                handle.flush()
                try:
                    os.fsync(handle.fileno())
                except Exception:
                    pass
            try:
                os.replace(temporary, cache_path)
            except Exception:
                if os.path.exists(cache_path):
                    os.remove(cache_path)
                os.rename(temporary, cache_path)
        finally:
            try:
                if os.path.exists(temporary):
                    os.remove(temporary)
            except Exception:
                pass

    self._embyflow_v11_7_7_bif_data = bytes(data)
    try:
        self._preview_v6_log(
            "v11_7_7_bif_ok",
            item=item_id,
            frames=count,
            multiplier_ms=multiplier,
            bytes=len(data),
            elapsed_ms=elapsed_ms,
        )
    except Exception:
        pass
    return bytes(data)


def _embyflow_v11_7_7_extract_bif_frame(self, chapter, path):
    if not path:
        return ""
    if self._preview_file_valid(path):
        return path

    data = _embyflow_v11_7_7_load_bif(self)
    header = _embyflow_v11_7_7_bif_header(data)
    if not header:
        return ""
    count, multiplier = header

    try:
        target_ticks = max(0, int(chapter.get("StartPositionTicks") or 0))
    except Exception:
        target_ticks = 0
    target_ms = target_ticks // 10000

    best_index = -1
    best_distance = None
    best_timestamp_ms = 0
    best_start = 0
    best_end = 0

    for index in range(count):
        base = 64 + (index * 8)
        next_base = base + 8
        try:
            timestamp_raw = int.from_bytes(data[base:base + 4], "little")
            offset = int.from_bytes(data[base + 4:base + 8], "little")
            next_offset = int.from_bytes(data[next_base + 4:next_base + 8], "little")
        except Exception:
            continue
        timestamp_ms = int(timestamp_raw) * int(multiplier)
        if offset <= 0 or next_offset <= offset or next_offset > len(data):
            continue
        distance = abs(timestamp_ms - target_ms)
        if best_distance is None or distance < best_distance:
            best_index = index
            best_distance = distance
            best_timestamp_ms = timestamp_ms
            best_start = offset
            best_end = next_offset
        if timestamp_ms > target_ms and best_distance is not None and distance > best_distance:
            break

    if best_index < 0 or best_end <= best_start:
        return ""

    image = data[best_start:best_end]
    if len(image) <= 500 or not image.startswith(b"\xff\xd8"):
        try:
            self._preview_v6_log(
                "v11_7_7_bif_frame_invalid",
                item=str(getattr(self.player, "item_id", "") or ""),
                frame=best_index,
                bytes=len(image),
            )
        except Exception:
            pass
        return ""

    temporary = path + ".bif.v11_7_7.tmp"
    try:
        with open(temporary, "wb") as handle:
            handle.write(image)
            handle.flush()
            try:
                os.fsync(handle.fileno())
            except Exception:
                pass
        self._preview_atomic_replace(temporary, path)
        if self._preview_file_valid(path):
            try:
                self._preview_v6_log(
                    "v11_7_7_bif_frame_ok",
                    item=str(getattr(self.player, "item_id", "") or ""),
                    chapter=str(chapter.get("_embyflow_image_index") or 0),
                    target_ticks=target_ticks,
                    frame=best_index,
                    frame_ms=best_timestamp_ms,
                    bytes=len(image),
                )
            except Exception:
                pass
            return path
        return ""
    finally:
        try:
            if os.path.exists(temporary):
                os.remove(temporary)
        except Exception:
            pass


def _embyflow_v11_7_7_obtain_preview(self, chapter, path):
    if not path:
        return ""
    if self._preview_file_valid(path):
        return path

    # Primary path: Emby's prepared BIF archive. One archive serves every chapter.
    bif_frame = _embyflow_v11_7_7_extract_bif_frame(self, chapter, path)
    if self._preview_file_valid(bif_frame):
        return bif_frame

    # Only probe native Chapter artwork when Emby explicitly advertises it.
    # DEV-LIVE already proved untagged /Images/Chapter requests return 404 here.
    if str(chapter.get("ImageTag") or "").strip():
        native = _embyflow_v11_7_6_download_native_chapter(self, chapter, path)
        if self._preview_file_valid(native):
            return native

    # Never store a placeholder during background prewarm.
    if bool(getattr(self, "_embyflow_preview_background_prewarm_v11_6", False)):
        return ""
    return self._preview_v6_make_placeholder(chapter)


EmbyFlowChapterNavigator._obtain_preview = _embyflow_v11_7_7_obtain_preview
EmbyFlowChapterNavigator._load_bif_v11_7_7 = _embyflow_v11_7_7_load_bif
EmbyFlowChapterNavigator._extract_bif_frame_v11_7_7 = _embyflow_v11_7_7_extract_bif_frame
_EmbyFlowChapterPrewarmProxyV17_5_3._obtain_preview = _embyflow_v11_7_7_obtain_preview

# EMBYFLOW_ADMIN_SAFETY_V11_7_7_DIRECT_BIF_TRICKPLAY_DEVLIVE_RELEASE
# GET: /Videos/{itemId}/index.bif?Width=320&MediaSourceId=...
# One prepared BIF archive is cached and parsed locally for every chapter image.
# Native Chapter GET is attempted only when ImageTag is present.
# No ThumbnailSet dependency. No ffmpeg. No video stream seek. No POST/DELETE.
# EMBYFLOW_ADMIN_SAFETY_V11_7_7_DIRECT_BIF_TRICKPLAY_END

# EMBYFLOW_V11_7_8_FAST_DIRECT_RESTORE_START
# Live DEV evidence 2026-09-05:
#   item 54 chapter 0 -> fast_direct_ok in 3.193 s
#   item 54 chapter 1 -> fast_direct_ok in 1.679 s
#   item 55 chapter 0 -> fast_direct_ok in 1.675 s
#   item 55 chapter 3 -> fast_direct_ok in 3.047 s
#   item 55 chapter 4 -> fast_direct_ok in 2.597 s
#   item 55 chapter 5 -> fast_direct_ok in 2.795 s
# V11.7 disabled exactly this proven receiver-side Static=true direct-stream
# extraction path. Restore it as the real fallback and allow the existing
# visible-five prewarm worker to populate the persistent chapter cache.
#
# Architecture:
#   1) persistent chapter JPEG cache
#   2) receiver-local ffmpeg, one fast input-side seek against validated
#      Static=true DirectStreamUrl
#   3) foreground-only placeholder on failure
#
# No server transcode fallback, no Static=false, no StartTimeTicks in URL,
# no replacement PlaySessionId, no POST/DELETE, no retry cascade.

EMBYFLOW_ALLOW_SAFE_DIRECT_CHAPTER_FRAME_FALLBACK = True


def _embyflow_v11_7_8_obtain_preview_unlocked(self, chapter, path):
    if not path:
        return ""

    if self._preview_file_valid(path):
        return path

    # Proven path from V11.6: ffmpeg runs on the receiver and seeks a validated
    # Static=true direct source. _generate_preview_frame_safe_direct_v11_6()
    # performs exactly one fast attempt and writes the normal persistent cache.
    generated = self._generate_preview_frame_safe_direct_v11_6(
        chapter,
        path,
    )
    if self._preview_file_valid(generated):
        return generated

    # Background prewarm must never create/cache a placeholder.
    if bool(getattr(self, "_embyflow_preview_background_prewarm_v11_6", False)):
        return ""

    return self._preview_v6_make_placeholder(chapter)


def _embyflow_v11_7_8_obtain_preview(self, chapter, path):
    # Serialize receiver ffmpeg between the prewarm worker and the visible
    # chapter carousel. This is the same single-worker discipline used by
    # V17.5.3 and avoids two decoders fighting over the box at once.
    lock = _EMBYFLOW_CHAPTER_PREWARM_LOCK_V17_5_3
    if lock is None:
        return _embyflow_v11_7_8_obtain_preview_unlocked(self, chapter, path)
    with lock:
        return _embyflow_v11_7_8_obtain_preview_unlocked(self, chapter, path)


# Final precedence: both foreground chapter navigation and the already-restored
# visible-five prewarm worker use the proven fast-direct path.
EmbyFlowChapterNavigator._obtain_preview = _embyflow_v11_7_8_obtain_preview
_EmbyFlowChapterPrewarmProxyV17_5_3._obtain_preview = _embyflow_v11_7_8_obtain_preview

# Expose for diagnostics.
EmbyFlowChapterNavigator._obtain_preview_v11_7_8 = _embyflow_v11_7_8_obtain_preview

# EMBYFLOW_V11_7_8_FAST_DIRECT_RESTORE_DEVLIVE_RELEASE
# Expected live evidence: event=fast_direct_ok ...
# Persistent output: /etc/enigma2/embyflow_cache/chapters/<item>/chapter_*.jpg
# EMBYFLOW_V11_7_8_FAST_DIRECT_RESTORE_END

# EMBYFLOW_V11_7_9_SELECTION_AWARE_VISIBLE5_START
# Live DEV evidence 2026-09-05 (item 1548): fast-direct extraction itself
# succeeds, but V11.6.1 carousel policy only generated the selected center card.
# When the user moved away from the playback position, visible neighbours stayed
# blank until they later became selected. V11.7.9 keeps the proven fast-direct
# extractor and changes only scheduling:
#   - center card first;
#   - then the four currently visible neighbours, nearest first;
#   - stale generations are discarded when selection moves;
#   - receiver ffmpeg remains serialized by the existing V11.7.8 lock;
#   - player prewarm waits a little longer so resume-seek position can settle.

_EMBYFLOW_V11_7_9_REFRESH_BASE = EmbyFlowChapterNavigator._refresh_carousel_v17


def _embyflow_v11_7_9_maybe_start_carousel_preview(self):
    if (
        getattr(self, "_carousel_busy", False)
        or not list(getattr(self, "_carousel_queue", []) or [])
        or getattr(self, "_closing", False)
    ):
        return

    request = self._carousel_queue.pop(0)
    self._carousel_busy = True

    try:
        import threading

        def worker():
            generation, slot, chapter_index, chapter, path = request
            result_path = ""
            error_text = ""

            try:
                # Selection changes create a new generation. Do not spend a new
                # ffmpeg job on a card that is no longer in the visible slot.
                if generation != getattr(self, "_carousel_generation", -1):
                    self._carousel_result = (
                        generation, slot, chapter_index, "", ""
                    )
                    return

                expected = self._slot_chapter_index_v17(slot)
                if expected != chapter_index:
                    self._carousel_result = (
                        generation, slot, chapter_index, "", ""
                    )
                    return

                result_path = self._obtain_preview(chapter, path)
                if not result_path and slot == 2:
                    error_text = "Kapitelbild konnte nicht erzeugt werden."
            except Exception as error:
                if slot == 2:
                    error_text = (
                        "Kapitelbild konnte nicht erzeugt werden: %s"
                        % str(error)
                    )

            self._carousel_result = (
                generation,
                slot,
                chapter_index,
                result_path,
                error_text,
            )

        thread = threading.Thread(
            target=worker,
            name="EmbyFlowChapterVisible5V11_7_9",
        )
        thread.daemon = True
        thread.start()
    except Exception as error:
        self._carousel_busy = False
        self._carousel_result = (
            request[0],
            request[1],
            request[2],
            "",
            str(error) if int(request[1]) == 2 else "",
        )


def _embyflow_v11_7_9_refresh_carousel(self):
    # Existing renderer still owns labels, card placement, cache hits, and the
    # center-card request. Its call to _maybe_start... resolves to the V11.7.9
    # worker above, which permits any currently visible slot (not center-only).
    _EMBYFLOW_V11_7_9_REFRESH_BASE(self)

    if not getattr(self, "chapters", None) or getattr(self, "_closing", False):
        return

    generation = int(getattr(self, "_carousel_generation", 0) or 0)

    # Center is already queued/started by the base refresh. Add the neighbours
    # nearest-first. This makes the on-screen five cards self-filling even when
    # the user browses far away from the actual playback position.
    existing = set()
    for queued in list(getattr(self, "_carousel_queue", []) or []):
        try:
            existing.add((int(queued[1]), int(queued[2])))
        except Exception:
            pass

    for slot in (1, 3, 0, 4):
        chapter_index = self._slot_chapter_index_v17(slot)
        if chapter_index is None:
            continue

        try:
            chapter = self.chapters[chapter_index]
        except Exception:
            continue

        path = self._cache_path(chapter)
        if self._preview_file_valid(path):
            continue

        key = (int(slot), int(chapter_index))
        if key in existing:
            continue

        self._carousel_queue.append(
            (
                generation,
                int(slot),
                int(chapter_index),
                dict(chapter),
                path,
            )
        )
        existing.add(key)

    self._maybe_start_carousel_preview_v17()


# Resume-aware background prewarm. The old restored starter was called with
# 1.0 s from player init; on resume playback that can sample position 00:00
# before Enigma2 has completed the resume seek. Four seconds is still early in
# playback but lets the actual playback position settle on the real receiver.
_EMBYFLOW_V11_7_9_PREWARM_START_BASE = _embyflow_chapter_start_prewarm_v17_5_3


def _embyflow_v11_7_9_start_prewarm(player, delay_seconds=1.0):
    try:
        delay_seconds = max(4.0, float(delay_seconds or 0.0))
    except Exception:
        delay_seconds = 4.0
    return _EMBYFLOW_V11_7_9_PREWARM_START_BASE(player, delay_seconds)


EmbyFlowChapterNavigator._maybe_start_carousel_preview_v17 = (
    _embyflow_v11_7_9_maybe_start_carousel_preview
)
EmbyFlowChapterNavigator._refresh_carousel_v17 = (
    _embyflow_v11_7_9_refresh_carousel
)
_embyflow_chapter_start_prewarm_v17_5_3 = _embyflow_v11_7_9_start_prewarm

