# EMBYFLOW_RCDEV_ADMIN_CLEANUP_V1_START
# Admin submission invariant:
# - seek/replacement sessions keep the V11.1/V11.2 Playing-before-Progress guard;
# - EMBYFLOW_CHAPTER_SAFE_DIRECT_TIMEOUT has exactly one assignment.
# This block changes no playback policy; it documents the submitted RCDEV state.
# EMBYFLOW_RCDEV_ADMIN_CLEANUP_V1_RELEASE
# EMBYFLOW_RCDEV_ADMIN_CLEANUP_V1_END


# ============================================================================
# EMBYFLOW_GITHUB_UPDATER_V1_START
# Phase 1 updater: one plugin.py artifact only.
# - manifest + artifact via HTTPS
# - monotonic build comparison
# - SHA256 is mandatory
# - downloaded Python is compiled before replacement
# - payload identity is checked to avoid accidental non-EmbyFlow files
# - current plugin.py is backed up to /tmp
# - same-filesystem temporary target + os.replace for atomic activation
# - rollback on post-replacement validation failure
# - never writes /etc/enigma2 and never touches Emby credentials/config
# ============================================================================

EMBYFLOW_UPDATE_MANIFEST_MAX_BYTES = 131072
EMBYFLOW_UPDATE_ARTIFACT_MAX_BYTES = 16 * 1024 * 1024
EMBYFLOW_UPDATE_TIMEOUT_SECONDS = 20
EMBYFLOW_UPDATE_ALLOWED_INITIAL_HOSTS = (
    "raw.githubusercontent.com",
    "github.com",
)

# EMBYFLOW_UPDATER_TIMESTAMPS_V1
# Persistent updater-only metadata. Stored beside the plugin, never in Emby
# credentials/config. The file contains only local timestamps/version/build.
EMBYFLOW_UPDATE_STATE_FILE = os.path.join(
    str(PLUGIN_PATH),
    ".embyflow_update_state.json",
)


def _embyflow_update_load_state():
    try:
        with open(EMBYFLOW_UPDATE_STATE_FILE, "r") as handle:
            value = json.loads(handle.read())
        return value if isinstance(value, dict) else {}
    except Exception:
        return {}


def _embyflow_update_save_state(state):
    value = dict(state or {})
    target = str(EMBYFLOW_UPDATE_STATE_FILE)
    temporary = target + ".tmp"
    try:
        with open(temporary, "w") as handle:
            handle.write(json.dumps(value, sort_keys=True))
            handle.flush()
            try:
                os.fsync(handle.fileno())
            except Exception:
                pass
        os.replace(temporary, target)
        return True
    finally:
        try:
            if os.path.exists(temporary):
                os.remove(temporary)
        except Exception:
            pass


def _embyflow_update_timestamp_text(timestamp):
    try:
        timestamp = int(timestamp or 0)
        if timestamp <= 0:
            return "Noch nie"
        return time.strftime("%d.%m.%Y  %H:%M:%S", time.localtime(timestamp))
    except Exception:
        return "Unbekannt"


def _embyflow_update_install_time_fallback():
    # First run after introducing timestamp tracking: the active plugin.py mtime
    # accurately reflects the last atomic self-update/install operation.
    try:
        path = os.path.join(str(PLUGIN_PATH), "plugin.py")
        return int(os.path.getmtime(path)) if os.path.isfile(path) else 0
    except Exception:
        return 0


def _embyflow_update_mark_checked(manifest=None):
    state = _embyflow_update_load_state()
    state["last_checked_ts"] = int(time.time())
    if isinstance(manifest, dict):
        state["last_checked_version"] = str(manifest.get("version") or "")
        try:
            state["last_checked_build"] = int(manifest.get("build") or 0)
        except Exception:
            state["last_checked_build"] = 0
    _embyflow_update_save_state(state)
    return state


def _embyflow_update_mark_installed(version, build):
    state = _embyflow_update_load_state()
    state["last_installed_ts"] = int(time.time())
    state["last_installed_version"] = str(version or "")
    try:
        state["last_installed_build"] = int(build or 0)
    except Exception:
        state["last_installed_build"] = 0
    _embyflow_update_save_state(state)
    return state


def _embyflow_update_https_url(url, allowed_hosts=None):
    try:
        from urllib.parse import urlparse
        parsed = urlparse(str(url or "").strip())
        if parsed.scheme.lower() != "https":
            return False
        host = str(parsed.hostname or "").lower()
        if not host:
            return False
        if allowed_hosts and host not in tuple(allowed_hosts):
            return False
        return True
    except Exception:
        return False


def _embyflow_update_read_url(url, max_bytes, allowed_hosts=None):
    if not _embyflow_update_https_url(url, allowed_hosts):
        raise RuntimeError("Unsichere oder nicht erlaubte Update-URL")

    import urllib.request

    request = urllib.request.Request(
        str(url),
        headers={
            "User-Agent": "EmbyFlowE2-Updater/1",
            "Accept": "application/json, application/octet-stream, text/plain, */*",
        },
    )

    response = urllib.request.urlopen(
        request,
        timeout=int(EMBYFLOW_UPDATE_TIMEOUT_SECONDS),
    )
    try:
        status = getattr(response, "status", None)
        if status is None:
            try:
                status = response.getcode()
            except Exception:
                status = 200
        if int(status or 0) != 200:
            raise RuntimeError("HTTP %s" % str(status))

        content_length = response.headers.get("Content-Length")
        if content_length:
            try:
                if int(content_length) > int(max_bytes):
                    raise RuntimeError("Update-Datei ist zu groß")
            except ValueError:
                pass

        data = response.read(int(max_bytes) + 1)
        if len(data) > int(max_bytes):
            raise RuntimeError("Update-Datei überschreitet das Größenlimit")
        return data
    finally:
        try:
            response.close()
        except Exception:
            pass


def _embyflow_update_normalize_manifest(raw):
    try:
        manifest = json.loads(raw.decode("utf-8"))
    except Exception as error:
        raise RuntimeError("update.json ist ungültig: %s" % str(error))

    if not isinstance(manifest, dict):
        raise RuntimeError("update.json enthält kein JSON-Objekt")

    version = str(manifest.get("version") or "").strip()
    channel = str(manifest.get("channel") or "").strip().lower()
    download = str(manifest.get("download") or "").strip()
    sha256_value = str(manifest.get("sha256") or "").strip().upper()

    try:
        build = int(manifest.get("build"))
    except Exception:
        raise RuntimeError("Update-Build fehlt oder ist ungültig")

    if not version:
        raise RuntimeError("Update-Version fehlt")
    if channel != str(EMBYFLOW_UPDATE_CHANNEL).lower():
        raise RuntimeError(
            "Falscher Update-Kanal: %s" % (channel or "unbekannt")
        )
    if not _embyflow_update_https_url(
        download,
        EMBYFLOW_UPDATE_ALLOWED_INITIAL_HOSTS,
    ):
        raise RuntimeError("Download-URL ist nicht erlaubt")
    if not re.match(r"^[0-9A-F]{64}$", sha256_value):
        raise RuntimeError("SHA256 fehlt oder ist ungültig")

    changelog = manifest.get("changelog") or []
    if isinstance(changelog, str):
        changelog = [changelog]
    if not isinstance(changelog, list):
        changelog = []
    changelog = [str(item).strip() for item in changelog if str(item).strip()]

    # V2 accepts either the legacy single plugin.py payload or a tightly
    # validated EmbyFlow tar.gz bundle. Bundles may contain only plugin.py and
    # the two audio-control PNG assets required by the tested audiobook UI.
    clean_download = download.split("?", 1)[0].lower()
    target = str(manifest.get("target") or "plugin.py").strip()
    artifact_type = str(manifest.get("artifact_type") or "").strip().lower()
    legacy_plugin = bool(
        clean_download.endswith(".py")
        and target == "plugin.py"
        and artifact_type in ("", "plugin_py", "plugin.py")
    )
    bundle_tar_gz = bool(
        (clean_download.endswith(".tar.gz") or clean_download.endswith(".tgz"))
        and target in ("EmbyFlowE2", "bundle")
        and artifact_type in ("bundle_tar_gz", "tar.gz", "tgz")
    )
    installable = bool(legacy_plugin or bundle_tar_gz)

    return {
        "version": version,
        "build": build,
        "channel": channel,
        "download": download,
        "sha256": sha256_value,
        "changelog": changelog,
        "target": target,
        "artifact_type": artifact_type,
        "installable": installable,
        "bundle_tar_gz": bundle_tar_gz,
    }


def _embyflow_update_fetch_manifest():
    # REF4: force a fresh manifest lookup. The update payload URL remains immutable
    # and hash-verified; only update.json gets a per-check cache-buster.
    separator = "&" if "?" in EMBYFLOW_UPDATE_MANIFEST_URL else "?"
    manifest_url = (
        EMBYFLOW_UPDATE_MANIFEST_URL
        + separator
        + "_embyflow_ts=%d" % int(time.time())
    )

    if not _embyflow_update_https_url(
        manifest_url,
        ("raw.githubusercontent.com",),
    ):
        raise RuntimeError("Unsichere oder nicht erlaubte Manifest-URL")

    import urllib.request

    request = urllib.request.Request(
        manifest_url,
        headers={
            "User-Agent": "EmbyFlowE2-Updater/1",
            "Accept": "application/json, text/plain, */*",
            "Cache-Control": "no-cache, no-store, max-age=0",
            "Pragma": "no-cache",
        },
    )

    response = urllib.request.urlopen(
        request,
        timeout=int(EMBYFLOW_UPDATE_TIMEOUT_SECONDS),
    )
    try:
        status = getattr(response, "status", None)
        if status is None:
            try:
                status = response.getcode()
            except Exception:
                status = 200
        if int(status or 0) != 200:
            raise RuntimeError("HTTP %s" % str(status))

        data = response.read(int(EMBYFLOW_UPDATE_MANIFEST_MAX_BYTES) + 1)
        if len(data) > int(EMBYFLOW_UPDATE_MANIFEST_MAX_BYTES):
            raise RuntimeError("Manifest überschreitet das Größenlimit")
    finally:
        try:
            response.close()
        except Exception:
            pass

    return _embyflow_update_normalize_manifest(data)


def _embyflow_update_payload_identity_ok(data):
    # Compile catches syntax mistakes. These markers additionally protect against
    # accidentally uploading a different valid Python file as an update.
    if not isinstance(data, (bytes, bytearray)):
        return False
    if len(data) < 100000:
        return False
    markers = (
        b'PLUGIN_NAME = "EmbyFlow E2"',
        b"PLUGIN_NAME = 'EmbyFlow E2'",
    )
    if not any(marker in data for marker in markers):
        return False
    if b"PLUGIN_VERSION" not in data:
        return False
    if b"EmbyFlowE2" not in data:
        return False
    return True


def _embyflow_update_install_plugin(manifest):
    import hashlib
    import py_compile
    import shutil
    import stat
    import tempfile

    download_url = str(manifest.get("download") or "")
    expected_sha = str(manifest.get("sha256") or "").upper()

    if not bool(manifest.get("installable")):
        raise RuntimeError("Dieses Manifest enthält kein installierbares Update")

    data = _embyflow_update_read_url(
        download_url,
        EMBYFLOW_UPDATE_ARTIFACT_MAX_BYTES,
        EMBYFLOW_UPDATE_ALLOWED_INITIAL_HOSTS,
    )

    actual_sha = hashlib.sha256(data).hexdigest().upper()
    if actual_sha != expected_sha:
        raise RuntimeError(
            "SHA256 stimmt nicht überein\nErwartet: %s\nErhalten: %s"
            % (expected_sha, actual_sha)
        )

    target_dir = os.path.realpath(str(PLUGIN_PATH))
    target_path = os.path.join(target_dir, "plugin.py")
    if os.path.realpath(os.path.dirname(target_path)) != target_dir:
        raise RuntimeError("Ungültiges Plugin-Ziel")
    if os.path.islink(target_path):
        raise RuntimeError("plugin.py ist ein Symlink; Update abgebrochen")
    if not os.path.isfile(target_path):
        raise RuntimeError("Installierte plugin.py wurde nicht gefunden")

    # Keep the proven V1 single-file updater path fully compatible.
    if not bool(manifest.get("bundle_tar_gz")):
        if not _embyflow_update_payload_identity_ok(data):
            raise RuntimeError("Payload ist keine erkennbare EmbyFlow plugin.py")

        stage_path = "/tmp/embyflow_update_stage_plugin.py"
        backup_path = "/tmp/embyflow_update_backup_plugin.py"
        target_tmp = os.path.join(target_dir, ".plugin.py.embyflow-update.tmp")
        rollback_tmp = os.path.join(target_dir, ".plugin.py.embyflow-rollback.tmp")
        replaced = False
        rollback_done = False
        original_mode = stat.S_IMODE(os.stat(target_path).st_mode)
        try:
            with open(stage_path, "wb") as handle:
                handle.write(data)
                handle.flush()
                try:
                    os.fsync(handle.fileno())
                except Exception:
                    pass
            py_compile.compile(stage_path, doraise=True)
            shutil.copy2(target_path, backup_path)
            with open(target_tmp, "wb") as handle:
                handle.write(data)
                handle.flush()
                try:
                    os.fsync(handle.fileno())
                except Exception:
                    pass
            os.chmod(target_tmp, original_mode)
            os.replace(target_tmp, target_path)
            replaced = True
            py_compile.compile(target_path, doraise=True)
            _embyflow_update_mark_installed(str(manifest.get("version") or ""), int(manifest.get("build") or 0))
            return {"ok": True, "version": str(manifest.get("version") or ""), "build": int(manifest.get("build") or 0), "sha256": actual_sha, "backup": backup_path, "rollback": False}
        except Exception as error:
            if replaced and os.path.isfile(backup_path):
                try:
                    shutil.copy2(backup_path, rollback_tmp)
                    os.chmod(rollback_tmp, original_mode)
                    os.replace(rollback_tmp, target_path)
                    py_compile.compile(target_path, doraise=True)
                    rollback_done = True
                except Exception as rollback_error:
                    raise RuntimeError("Update fehlgeschlagen: %s; Rollback fehlgeschlagen: %s" % (str(error), str(rollback_error)))
            raise RuntimeError("%s%s" % (str(error), "; vorherige Version wiederhergestellt" if rollback_done else ""))
        finally:
            for cleanup_path in (stage_path, target_tmp, rollback_tmp):
                try:
                    if os.path.exists(cleanup_path):
                        os.remove(cleanup_path)
                except Exception:
                    pass

    # V2 bundle path: extract nothing blindly. Read exactly three approved files
    # from the tarball, validate them in a private staging directory, then
    # replace the live files with per-file backups and full rollback on failure.
    import io
    import tarfile

    allowed = {
        "EmbyFlowE2/plugin.py": "plugin.py",
        "EmbyFlowE2/images/audio_controls/ring.png": "images/audio_controls/ring.png",
        "EmbyFlowE2/images/audio_controls/ring_focus.png": "images/audio_controls/ring_focus.png",
    }
    staged = {}
    stage_dir = tempfile.mkdtemp(prefix="embyflow_update_v2_")
    backup_dir = "/tmp/embyflow_update_v2_backup"
    replaced = []
    try:
        archive = tarfile.open(fileobj=io.BytesIO(data), mode="r:gz")
        try:
            for member in archive.getmembers():
                name = str(member.name or "").replace("\\", "/").lstrip("./")
                if member.isdir():
                    continue
                if not member.isfile() or name not in allowed:
                    raise RuntimeError("Update-Paket enthält eine nicht erlaubte Datei: %s" % name)
                source = archive.extractfile(member)
                if source is None:
                    raise RuntimeError("Update-Datei kann nicht gelesen werden: %s" % name)
                payload = source.read()
                if name in staged:
                    raise RuntimeError("Doppelte Datei im Update-Paket: %s" % name)
                staged[name] = payload
        finally:
            archive.close()

        if set(staged.keys()) != set(allowed.keys()):
            raise RuntimeError("Update-Paket ist unvollständig")
        plugin_data = staged["EmbyFlowE2/plugin.py"]
        if not _embyflow_update_payload_identity_ok(plugin_data):
            raise RuntimeError("Paket enthält keine erkennbare EmbyFlow plugin.py")
        for png_name in ("EmbyFlowE2/images/audio_controls/ring.png", "EmbyFlowE2/images/audio_controls/ring_focus.png"):
            png = staged[png_name]
            if len(png) < 32 or not png.startswith(b"\x89PNG\r\n\x1a\n"):
                raise RuntimeError("Ungültige PNG-Datei im Update-Paket")

        stage_plugin = os.path.join(stage_dir, "plugin.py")
        with open(stage_plugin, "wb") as handle:
            handle.write(plugin_data)
        py_compile.compile(stage_plugin, doraise=True)

        if os.path.isdir(backup_dir):
            shutil.rmtree(backup_dir)
        os.makedirs(backup_dir)

        # Back up all existing targets before replacing the first byte live.
        for archive_name, relative in allowed.items():
            live = os.path.realpath(os.path.join(target_dir, relative))
            if not (live == target_dir or live.startswith(target_dir + os.sep)):
                raise RuntimeError("Ungültiges Paket-Ziel")
            if os.path.islink(live):
                raise RuntimeError("Symlink-Ziel im Update abgelehnt: %s" % relative)
            backup = os.path.join(backup_dir, relative)
            if os.path.isfile(live):
                parent = os.path.dirname(backup)
                if not os.path.isdir(parent):
                    os.makedirs(parent)
                shutil.copy2(live, backup)

        # Activate each staged payload via same-filesystem os.replace.
        for archive_name, relative in allowed.items():
            live = os.path.join(target_dir, relative)
            parent = os.path.dirname(live)
            if not os.path.isdir(parent):
                os.makedirs(parent)
            tmp = live + ".embyflow-update.tmp"
            with open(tmp, "wb") as handle:
                handle.write(staged[archive_name])
                handle.flush()
                try:
                    os.fsync(handle.fileno())
                except Exception:
                    pass
            if relative == "plugin.py":
                os.chmod(tmp, stat.S_IMODE(os.stat(target_path).st_mode))
            os.replace(tmp, live)
            replaced.append(relative)

        py_compile.compile(target_path, doraise=True)
        _embyflow_update_mark_installed(str(manifest.get("version") or ""), int(manifest.get("build") or 0))
        return {"ok": True, "version": str(manifest.get("version") or ""), "build": int(manifest.get("build") or 0), "sha256": actual_sha, "backup": backup_dir, "rollback": False}

    except Exception as error:
        rollback_errors = []
        for relative in reversed(replaced):
            live = os.path.join(target_dir, relative)
            backup = os.path.join(backup_dir, relative)
            try:
                if os.path.isfile(backup):
                    tmp = live + ".embyflow-rollback.tmp"
                    shutil.copy2(backup, tmp)
                    os.replace(tmp, live)
                elif os.path.exists(live):
                    os.remove(live)
            except Exception as rollback_error:
                rollback_errors.append("%s: %s" % (relative, str(rollback_error)))
        if rollback_errors:
            raise RuntimeError("Update fehlgeschlagen: %s; Rollback-Fehler: %s" % (str(error), "; ".join(rollback_errors)))
        raise RuntimeError("%s%s" % (str(error), "; vorherige Version wiederhergestellt" if replaced else ""))
    finally:
        try:
            shutil.rmtree(stage_dir)
        except Exception:
            pass
        for relative in allowed.values():
            for suffix in (".embyflow-update.tmp", ".embyflow-rollback.tmp"):
                try:
                    tmp = os.path.join(target_dir, relative) + suffix
                    if os.path.exists(tmp):
                        os.remove(tmp)
                except Exception:
                    pass


def _embyflow_update_display_version(value):
    value = str(value or "–").strip()
    if value.startswith("2026-"):
        value = value[5:]
    value = value.replace("LOGINREF", "REF")

    parts = [part.strip() for part in value.split("-") if part.strip()]
    compact = []
    for part in parts:
        upper = part.upper()
        if upper.startswith("RCDEV") or upper.startswith("SERVERSAFE"):
            continue
        compact.append(part)

    if compact:
        return " · ".join(compact[-3:])
    return value


