# EMBYFLOW_SEEK_BURST_V17_5_5_START
# RCDEV4 real-box result 05.09.2026:
# The 500 ms debounce was structurally correct (virtual base + accumulated
# delta + one absolute restart), but it fired too early. Once the first
# restart began, later remote events reached the ActionMap only after the
# service transition, creating one restart per key again.
#
# OpenATV's NumberZap uses a 1000 ms timer that is restarted after every
# additional digit. For EmbyFlow's much more expensive Emby stream restart
# we use 1200 ms after the LAST seek key. During that window only the virtual
# target changes; no service/ffmpeg restart is allowed. This gives a rapid
# 1/3/4/6/7/9 or direction-key burst time to arrive before the first restart.
#
# Expected diagnostic pattern for a successful burst:
#   QUEUE add=30 total=30
#   QUEUE add=30 total=60
#   ...
#   COMMIT delta=300
#   RESULT success=1
# i.e. many QUEUE lines and one COMMIT/RESULT pair.
EMBYFLOW_SEEK_BURST_MS_V17_5_5 = 1200

_EMBYFLOW_SEEK_BURST_ORIGINAL_START_V17_5_5 = (
    EmbyFlowMoviePlayer.tester_seek_to_start
)
_EMBYFLOW_SEEK_BURST_ORIGINAL_OPEN_CHAPTERS_V17_5_5 = (
    EmbyFlowMoviePlayer.open_chapter_navigation
)
_EMBYFLOW_SEEK_BURST_ORIGINAL_LEAVE_V17_5_5 = (
    EmbyFlowMoviePlayer.leave_player
)


def _embyflow_seek_burst_v17_5_5_timestamp():
    try:
        now = time.time()
        return "%s.%03d" % (
            time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(now)),
            int((now - int(now)) * 1000),
        )
    except Exception:
        return time.strftime("%Y-%m-%d %H:%M:%S")


def _embyflow_seek_burst_v17_5_5_log(message):
    try:
        with embyflow_open_log(
            "/tmp/embyflow_seek_burst_v17_5_5.log",
            "a",
            encoding="utf-8",
        ) as handle:
            handle.write(
                "%s %s\n"
                % (
                    _embyflow_seek_burst_v17_5_5_timestamp(),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_seek_burst_v17_5_5_timer(self):
    timer = getattr(self, "_embyflow_seek_burst_timer_v17_5_5", None)
    if timer is not None:
        return timer

    timer = eTimer()

    def callback():
        _embyflow_seek_burst_v17_5_5_commit(self)

    self._embyflow_seek_burst_callback_v17_5_5 = callback
    try:
        timer.callback.append(callback)
    except Exception:
        try:
            timer.timeout.connect(callback)
        except Exception:
            pass

    self._embyflow_seek_burst_timer_v17_5_5 = timer
    return timer


def _embyflow_seek_burst_v17_5_5_reset(self):
    self._embyflow_seek_burst_pending_v17_5_5 = False
    self._embyflow_seek_burst_base_v17_5_5 = 0
    self._embyflow_seek_burst_delta_v17_5_5 = 0
    self._embyflow_seek_burst_source_v17_5_5 = ""
    self._embyflow_seek_burst_target_v17_5_5 = 0
    self._embyflow_seek_burst_first_ts_v17_5_5 = 0.0
    self._embyflow_seek_burst_count_v17_5_5 = 0


def _embyflow_seek_burst_v17_5_5_cancel(self, reason="cancel"):
    timer = getattr(self, "_embyflow_seek_burst_timer_v17_5_5", None)
    if timer is not None:
        try:
            timer.stop()
        except Exception:
            pass

    pending = bool(
        getattr(self, "_embyflow_seek_burst_pending_v17_5_5", False)
    )
    if pending:
        _embyflow_seek_burst_v17_5_5_log(
            "CANCEL reason=%s item=%s count=%s delta=%s target=%s"
            % (
                str(reason),
                str(getattr(self, "item_id", "") or "-"),
                int(getattr(self, "_embyflow_seek_burst_count_v17_5_5", 0) or 0),
                int(getattr(self, "_embyflow_seek_burst_delta_v17_5_5", 0) or 0),
                int(getattr(self, "_embyflow_seek_burst_target_v17_5_5", 0) or 0),
            )
        )

    _embyflow_seek_burst_v17_5_5_reset(self)


def _embyflow_seek_burst_v17_5_5_queue(self, seconds, source):
    try:
        seconds = int(seconds)
    except Exception:
        return False

    try:
        pending = bool(
            getattr(self, "_embyflow_seek_burst_pending_v17_5_5", False)
        )

        if not pending:
            base_ticks = int(self.current_position_ticks() or 0)
            self._embyflow_seek_burst_base_v17_5_5 = base_ticks
            self._embyflow_seek_burst_delta_v17_5_5 = 0
            self._embyflow_seek_burst_first_ts_v17_5_5 = time.time()
            self._embyflow_seek_burst_count_v17_5_5 = 0
        else:
            base_ticks = int(
                getattr(self, "_embyflow_seek_burst_base_v17_5_5", 0)
                or 0
            )

        delta_seconds = int(
            getattr(self, "_embyflow_seek_burst_delta_v17_5_5", 0)
            or 0
        ) + seconds

        target_ticks = max(
            0,
            base_ticks + int(delta_seconds * 10000000),
        )

        duration_ticks = int(getattr(self, "duration_ticks", 0) or 0)
        if duration_ticks > 10000000:
            target_ticks = min(target_ticks, duration_ticks - 10000000)

        count = int(
            getattr(self, "_embyflow_seek_burst_count_v17_5_5", 0)
            or 0
        ) + 1

        self._embyflow_seek_burst_pending_v17_5_5 = True
        self._embyflow_seek_burst_delta_v17_5_5 = delta_seconds
        self._embyflow_seek_burst_source_v17_5_5 = str(source or "relative")
        self._embyflow_seek_burst_target_v17_5_5 = int(target_ticks)
        self._embyflow_seek_burst_count_v17_5_5 = count

        try:
            self.seek_has_been_used = True
        except Exception:
            pass

        timer = _embyflow_seek_burst_v17_5_5_timer(self)
        try:
            timer.stop()
        except Exception:
            pass
        timer.start(int(EMBYFLOW_SEEK_BURST_MS_V17_5_5), True)

        _embyflow_seek_burst_v17_5_5_log(
            "QUEUE source=%s count=%s add=%s total=%s base=%s target=%s item=%s"
            % (
                str(source),
                count,
                seconds,
                delta_seconds,
                base_ticks,
                target_ticks,
                str(getattr(self, "item_id", "") or "-"),
            )
        )

        # Keep the overlay responsive, but deliberately do NOT touch the
        # running service or synthetic playback clock here. The actual seek
        # happens only once in _commit() after the final key has been quiet
        # for EMBYFLOW_SEEK_BURST_MS_V17_5_5.
        try:
            self.show_overlay()
        except Exception:
            pass

        return True

    except Exception as error:
        _embyflow_seek_burst_v17_5_5_log(
            "QUEUE_ERROR source=%s seconds=%s type=%s message=%s"
            % (
                str(source),
                str(seconds),
                type(error).__name__,
                str(error).replace("\n", " ")[:240],
            )
        )
        return False


def _embyflow_seek_burst_v17_5_5_commit(self):
    if not bool(
        getattr(self, "_embyflow_seek_burst_pending_v17_5_5", False)
    ):
        return

    target_ticks = int(
        getattr(self, "_embyflow_seek_burst_target_v17_5_5", 0)
        or 0
    )
    delta_seconds = int(
        getattr(self, "_embyflow_seek_burst_delta_v17_5_5", 0)
        or 0
    )
    source = str(
        getattr(self, "_embyflow_seek_burst_source_v17_5_5", "relative")
        or "relative"
    )
    item_id = str(getattr(self, "item_id", "") or "-")
    count = int(
        getattr(self, "_embyflow_seek_burst_count_v17_5_5", 0)
        or 0
    )
    first_ts = float(
        getattr(self, "_embyflow_seek_burst_first_ts_v17_5_5", 0.0)
        or 0.0
    )
    burst_ms = max(0, int((time.time() - first_ts) * 1000)) if first_ts else 0

    # Snapshot and clear BEFORE entering the expensive restart path. This
    # prevents replay of the same burst if the service transition raises.
    _embyflow_seek_burst_v17_5_5_reset(self)

    try:
        _embyflow_seek_burst_v17_5_5_log(
            "COMMIT source=%s count=%s delta=%s target=%s burst_ms=%s item=%s"
            % (
                source,
                count,
                delta_seconds,
                target_ticks,
                burst_ms,
                item_id,
            )
        )

        success = bool(self.embyflow_seek_to_chapter(target_ticks))

        _embyflow_seek_burst_v17_5_5_log(
            "RESULT source=%s success=%s count=%s target=%s item=%s"
            % (source, int(success), count, target_ticks, item_id)
        )

        if not success:
            # Preserve the last known native fallback but never issue a second
            # Emby restart for this same target.
            try:
                return _EMBYFLOW_SEEK_V17_5_2_ORIGINAL_RELATIVE_SECONDS(
                    self,
                    delta_seconds,
                )
            except Exception:
                return None

    except Exception as error:
        _embyflow_seek_burst_v17_5_5_log(
            "COMMIT_ERROR source=%s count=%s delta=%s target=%s type=%s message=%s"
            % (
                source,
                count,
                delta_seconds,
                target_ticks,
                type(error).__name__,
                str(error).replace("\n", " ")[:240],
            )
        )
        return None


def _embyflow_seek_burst_v17_5_5_relative(self, seconds):
    if _embyflow_seek_burst_v17_5_5_queue(self, seconds, "relative"):
        return
    return _EMBYFLOW_SEEK_V17_5_2_ORIGINAL_RELATIVE_SECONDS(self, seconds)


def _embyflow_seek_burst_v17_5_5_tester(self, seconds):
    if _embyflow_seek_burst_v17_5_5_queue(
        self,
        seconds,
        "number_direction",
    ):
        return
    return _EMBYFLOW_SEEK_V17_5_2_ORIGINAL_TESTER_RELATIVE(self, seconds)


def _embyflow_seek_burst_v17_5_5_start(self):
    _embyflow_seek_burst_v17_5_5_cancel(self, "seek_to_start")
    return _EMBYFLOW_SEEK_BURST_ORIGINAL_START_V17_5_5(self)


def _embyflow_seek_burst_v17_5_5_open_chapters(self):
    _embyflow_seek_burst_v17_5_5_cancel(self, "open_chapters")
    return _EMBYFLOW_SEEK_BURST_ORIGINAL_OPEN_CHAPTERS_V17_5_5(self)


def _embyflow_seek_burst_v17_5_5_leave(self, *args, **kwargs):
    _embyflow_seek_burst_v17_5_5_cancel(self, "leave_player")
    return _EMBYFLOW_SEEK_BURST_ORIGINAL_LEAVE_V17_5_5(
        self,
        *args,
        **kwargs
    )


# Final precedence for all remote-control relative seek paths.
EmbyFlowMoviePlayer.seek_relative_seconds = (
    _embyflow_seek_burst_v17_5_5_relative
)
EmbyFlowMoviePlayer.tester_seek_relative = (
    _embyflow_seek_burst_v17_5_5_tester
)
EmbyFlowMoviePlayer.tester_seek_to_start = (
    _embyflow_seek_burst_v17_5_5_start
)
EmbyFlowMoviePlayer.open_chapter_navigation = (
    _embyflow_seek_burst_v17_5_5_open_chapters
)
EmbyFlowMoviePlayer.leave_player = (
    _embyflow_seek_burst_v17_5_5_leave
)

# EMBYFLOW_SEEK_BURST_V17_5_5_RELEASE
# EMBYFLOW_SEEK_BURST_V17_5_5_END



# EMBYFLOW_SEEK_ASYNC_RESTART_V17_5_6_START
#
# RCDEV6: keep the Enigma2 main loop responsive during Emby seek restarts.
#
# Real-box RCDEV5 evidence showed that the 1200 ms burst collector works,
# but a new key could appear immediately after RESULT because the restart
# path still performed synchronous HTTP cleanup/report traffic on the UI
# thread.  Native seekTo()/seekRelative() is deliberately NOT reintroduced
# here: earlier real-box diagnostics proved that the relevant direct/static
# service is not reliably moved by native Enigma2 seek.
#
# V17.5.6 therefore keeps the proven absolute Emby StartTimeTicks restart,
# but moves only network-only work off the Enigma2 main loop:
#   * DELETE of the previous ActiveEncoding -> daemon worker
#   * Playing + Progress reports -> daemon worker, with session/generation
#     guards so a superseded seek cannot resurrect a stale session
# The actual eServiceReference/playService transition remains on the Enigma2
# main thread.  No Enigma2 UI/service object is touched by the workers.


def _embyflow_seek_async_v17_5_6_timestamp():
    try:
        now = time.time()
        return "%s.%03d" % (
            time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(now)),
            int((now - int(now)) * 1000),
        )
    except Exception:
        return time.strftime("%Y-%m-%d %H:%M:%S")


def _embyflow_seek_async_v17_5_6_log(message):
    try:
        with embyflow_open_log(
            "/tmp/embyflow_seek_async_v17_5_6.log",
            "a",
            encoding="utf-8",
        ) as handle:
            handle.write(
                "%s %s\n"
                % (
                    _embyflow_seek_async_v17_5_6_timestamp(),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_seek_async_v17_5_6_cancel_worker(self, old_play_session_id, item_id, generation):
    try:
        if not old_play_session_id:
            _embyflow_seek_async_v17_5_6_log(
                "CANCEL_SKIP generation=%s item=%s reason=no_old_session"
                % (generation, item_id)
            )
            return

        started = time.time()
        ok = bool(self.cancel_active_encoding(old_play_session_id))
        elapsed_ms = int((time.time() - started) * 1000)
        _embyflow_seek_async_v17_5_6_log(
            "CANCEL_DONE generation=%s item=%s old_session=%s success=%s ms=%s"
            % (
                generation,
                item_id,
                old_play_session_id,
                int(ok),
                elapsed_ms,
            )
        )
    except Exception as error:
        _embyflow_seek_async_v17_5_6_log(
            "CANCEL_ERROR generation=%s item=%s type=%s message=%s"
            % (
                generation,
                item_id,
                type(error).__name__,
                str(error).replace("\n", " ")[:240],
            )
        )


def _embyflow_seek_async_v17_5_6_report_worker(
    self,
    generation,
    session_id,
    server,
    token,
    playing_payload,
    progress_payload,
    item_id,
):
    try:
        # Never let a delayed worker report a PlaySessionId that has already
        # been superseded by a newer seek/replacement.
        if int(getattr(self, "_embyflow_seek_async_generation_v17_5_6", 0) or 0) != int(generation):
            _embyflow_seek_async_v17_5_6_log(
                "REPORT_SKIP generation=%s item=%s session=%s reason=superseded_before_start"
                % (generation, item_id, session_id)
            )
            return
        if str(getattr(self, "play_session_id", "") or "") != str(session_id or ""):
            _embyflow_seek_async_v17_5_6_log(
                "REPORT_SKIP generation=%s item=%s session=%s reason=session_changed_before_start"
                % (generation, item_id, session_id)
            )
            return
        if bool(getattr(self, "closed", False)):
            return

        headers = {
            "X-Emby-Token": token,
            "X-Emby-Authorization": AUTH_HEADER,
        }

        started = time.time()
        playing_url = server.rstrip("/") + "/emby/Sessions/Playing?reqformat=json"
        response = embyflow_http_post(
            playing_url,
            headers=headers,
            json=playing_payload,
            timeout=5,
            verify=True,
        )
        playing_status = int(getattr(response, "status_code", 0) or 0)

        # Check again because another seek may have happened while the Playing
        # POST was in flight.
        if (
            int(getattr(self, "_embyflow_seek_async_generation_v17_5_6", 0) or 0) != int(generation)
            or str(getattr(self, "play_session_id", "") or "") != str(session_id or "")
            or bool(getattr(self, "closed", False))
        ):
            _embyflow_seek_async_v17_5_6_log(
                "REPORT_PARTIAL generation=%s item=%s session=%s playing_status=%s reason=superseded_after_playing"
                % (generation, item_id, session_id, playing_status)
            )
            return

        progress_url = server.rstrip("/") + "/emby/Sessions/Playing/Progress?reqformat=json"
        response = embyflow_http_post(
            progress_url,
            headers=headers,
            json=progress_payload,
            timeout=5,
            verify=True,
        )
        progress_status = int(getattr(response, "status_code", 0) or 0)
        elapsed_ms = int((time.time() - started) * 1000)

        _embyflow_seek_async_v17_5_6_log(
            "REPORT_DONE generation=%s item=%s session=%s playing=%s progress=%s ms=%s"
            % (
                generation,
                item_id,
                session_id,
                playing_status,
                progress_status,
                elapsed_ms,
            )
        )

    except Exception as error:
        _embyflow_seek_async_v17_5_6_log(
            "REPORT_ERROR generation=%s item=%s session=%s type=%s message=%s"
            % (
                generation,
                item_id,
                session_id,
                type(error).__name__,
                str(error).replace("\n", " ")[:240],
            )
        )


def _embyflow_seek_async_v17_5_6_restart_stream(
    self,
    target_ticks,
    subtitle_stream_index=None,
    subtitle_label=None,
):
    try:
        target_ticks = max(0, int(target_ticks or 0))
    except Exception:
        target_ticks = 0

    try:
        duration = int(getattr(self, "duration_ticks", 0) or 0)
        if duration > 10000000:
            target_ticks = min(target_ticks, duration - 10000000)
    except Exception:
        pass

    try:
        (
            server,
            token,
            item_id,
            media_source_id,
            audio_index,
        ) = self.embyflow_v10_stream_context()

        if not server or not token or not item_id:
            raise RuntimeError("Emby-Wiedergabekontext unvollständig")

        try:
            from urllib.parse import urlencode
        except Exception:
            from urllib import urlencode

        active_subtitle = None
        if subtitle_stream_index is not None:
            try:
                active_subtitle = int(subtitle_stream_index)
                if active_subtitle < 0:
                    active_subtitle = None
            except Exception:
                active_subtitle = None

        old_play_session_id = str(getattr(self, "play_session_id", "") or "")
        new_session_id = uuid4().hex
        params = [
            ("Static", "false"),
            ("StartTimeTicks", str(int(target_ticks))),
            ("PlaySessionId", new_session_id),
            ("DeviceId", "embyflowe2"),
        ]
        if media_source_id:
            params.append(("MediaSourceId", media_source_id))
        if audio_index is not None:
            params.append(("AudioStreamIndex", str(int(audio_index))))

        if active_subtitle is None:
            params.extend([
                ("VideoCodec", "copy"),
                ("AudioCodec", "copy"),
            ])
            endpoint = "stream.mkv"
        else:
            params.extend([
                ("VideoCodec", "h264"),
                ("AudioCodec", "aac"),
                ("VideoBitRate", "20000000"),
                ("AudioBitRate", "384000"),
                ("MaxAudioChannels", "6"),
                ("SubtitleStreamIndex", str(active_subtitle)),
                ("SubtitleMethod", "Encode"),
                ("CopyTimestamps", "true"),
            ])
            endpoint = "stream.mkv"

        params.append(("api_key", token))
        new_url = "%s/Videos/%s/%s?%s" % (
            server,
            item_id,
            endpoint,
            urlencode(params),
        )

        new_ref = eServiceReference(
            _embyflow_engine_v11_4_service_type(self),
            0,
            new_url,
        )
        new_ref.setName(self.title_text)

        self.play_session_id = new_session_id
        self.stream_url = new_url
        self.ref = new_ref
        self.embyflow_v10_stream_base_ticks = int(target_ticks)
        self.embyflow_v10_stream_started_monotonic = None
        self.embyflow_v10_stream_confirmed_playing = False
        self.embyflow_v10_stream_time_mode = None
        self.embyflow_v10_clock_wait_logged = False
        try:
            self.embyflow_v10_stream_restart_issued_monotonic = time.monotonic()
        except Exception:
            self.embyflow_v10_stream_restart_issued_monotonic = None

        try:
            with open(
                "/tmp/embyflow_chapter_clock_v16_1.log",
                "a",
                encoding="utf-8",
            ) as log:
                log.write(
                    "%s RESTART target=%s\n"
                    % (
                        time.strftime("%Y-%m-%d %H:%M:%S"),
                        int(target_ticks),
                    )
                )
        except Exception:
            pass

        self.embyflow_server_subtitle_stream_index = active_subtitle
        if subtitle_label is not None:
            self.embyflow_server_subtitle_label = str(subtitle_label or "Untertitel")

        self.pending_seek_started_ticks = None
        self.pending_seek_target_ticks = None
        self.initial_big_seek_target_ticks = None
        self.seek_has_been_used = True
        try:
            self.seek_fallback_timer.stop()
        except Exception:
            pass
        try:
            self.initial_big_seek_timer.stop()
        except Exception:
            pass

        generation = int(
            getattr(self, "_embyflow_seek_async_generation_v17_5_6", 0)
            or 0
        ) + 1
        self._embyflow_seek_async_generation_v17_5_6 = generation

        # Snapshot report payloads while the new session is current.  Workers
        # receive plain Python data only; they never inspect Enigma2 services.
        playing_payload = self.emby_report_payload(target_ticks)
        progress_payload = dict(playing_payload or {})
        progress_payload["EventName"] = "TimeUpdate"

        main_started = time.time()
        _embyflow_seek_async_v17_5_6_log(
            "RESTART_BEGIN generation=%s item=%s target=%s old_session=%s new_session=%s"
            % (
                generation,
                item_id,
                target_ticks,
                old_play_session_id or "-",
                new_session_id,
            )
        )

        # Start old-session cleanup without blocking Enigma2's ActionMap/eTimer
        # processing.  Brief overlap is preferable to serial UI-thread waits;
        # cleanup is still mandatory and logged.
        try:
            import threading
            cancel_thread = threading.Thread(
                target=_embyflow_seek_async_v17_5_6_cancel_worker,
                args=(self, old_play_session_id, str(item_id), generation),
                name="EmbyFlowSeekCancelV17_5_6",
            )
            cancel_thread.daemon = True
            cancel_thread.start()
        except Exception as error:
            # Thread creation failure: keep cleanup correctness over latency.
            _embyflow_seek_async_v17_5_6_log(
                "CANCEL_THREAD_ERROR generation=%s type=%s message=%s fallback=sync"
                % (
                    generation,
                    type(error).__name__,
                    str(error).replace("\n", " ")[:200],
                )
            )
            self.cancel_active_encoding(old_play_session_id)

        self._embyflow_stream_replacement_in_progress = True
        try:
            self.session.nav.playService(self.ref)
        finally:
            self._embyflow_stream_replacement_in_progress = False

        self.synthetic_position_ticks = int(target_ticks)
        self.paused = False
        try:
            self.play_started_ts = int(time.time()) - int(target_ticks // 10000000)
        except Exception:
            pass

        try:
            self.audio_retry_count = 0
            self.audio_timer.start(1200, True)
        except Exception:
            pass

        self.show_overlay()
        self.update_playback_overlay()

        # One Playing + one Progress, asynchronously and guarded.  This also
        # removes the duplicate synchronous Playing report that existed in the
        # older restart body.
        try:
            import threading
            report_thread = threading.Thread(
                target=_embyflow_seek_async_v17_5_6_report_worker,
                args=(
                    self,
                    generation,
                    new_session_id,
                    str(server),
                    str(token),
                    dict(playing_payload or {}),
                    dict(progress_payload or {}),
                    str(item_id),
                ),
                name="EmbyFlowSeekReportV17_5_6",
            )
            report_thread.daemon = True
            report_thread.start()
        except Exception as error:
            # Report failure must not turn a successful service replacement
            # into a second seek/restart.  Log it; normal periodic Progress
            # reporting remains active as a recovery path.
            _embyflow_seek_async_v17_5_6_log(
                "REPORT_THREAD_ERROR generation=%s type=%s message=%s"
                % (
                    generation,
                    type(error).__name__,
                    str(error).replace("\n", " ")[:200],
                )
            )

        main_ms = int((time.time() - main_started) * 1000)
        _embyflow_seek_async_v17_5_6_log(
            "RESTART_RETURN generation=%s item=%s target=%s main_ms=%s"
            % (generation, item_id, target_ticks, main_ms)
        )
        return True

    except Exception as error:
        _embyflow_seek_async_v17_5_6_log(
            "RESTART_ERROR target=%s subtitle=%s type=%s message=%s"
            % (
                int(target_ticks or 0),
                str(subtitle_stream_index),
                type(error).__name__,
                str(error).replace("\n", " ")[:300],
            )
        )
        return False


# Final precedence for absolute Emby seek/chapter restarts.  The public method
# contract and StartTimeTicks stream construction remain unchanged.
EmbyFlowMoviePlayer.embyflow_v10_restart_stream = (
    _embyflow_seek_async_v17_5_6_restart_stream
)

# EMBYFLOW_SEEK_ASYNC_RESTART_V17_5_6_RELEASE
# EMBYFLOW_SEEK_ASYNC_RESTART_V17_5_6_END

# EMBYFLOW_MARKER_USER_ENDPOINT_V17_5_4_RELEASE
# Removes invalid /Items/{id} marker fallback; only user-scoped item metadata is used.
# EMBYFLOW_SUBTITLE_TIMEOUT_120_V17_5_4_RELEASE
# Read timeout 120 s, GUI watchdog 150 s for large 4K subtitle extraction.


# ============================================================================
# EMBYFLOW_RCDEV7_SERVERSAFE1_START
# 06.09.2026
#
# Server-safety hotfix for the CLEAN2 seek/session regression:
#   1) A DirectPlay Static=true stream is NEVER converted into Static=false
#      merely because the user seeks/chapter-jumps.
#   2) On receivers with ServiceApp + exteplayer3, the first DirectPlay seek
#      keeps the SAME Static=true URL and SAME PlaySessionId, switches only the
#      local Enigma2 service backend to 5002, and restores the requested movie
#      position with receiver-local seekTo(). Subsequent seeks stay local.
#   3) If 5002 is unavailable, DirectPlay seek fails closed. It does NOT fall
#      back to a server-generated Static=false remux/transcode session.
#   4) Replacement-session cleanup sends Stopped for an OLD PlaySessionId before
#      ActiveEncodings DELETE. Main-thread cleanup is moved to a daemon worker.
#
# This block deliberately does not change true HLS/transcode policy. It only
# prevents a DirectPlay seek from creating transcoding-temp work and closes old
# replacement sessions more correctly.
# ============================================================================

_EMBYFLOW_RCDEV7_ORIGINAL_RESTART_STREAM = (
    EmbyFlowMoviePlayer.embyflow_v10_restart_stream
)
_EMBYFLOW_RCDEV7_ORIGINAL_CANCEL_ACTIVE_ENCODING = (
    EmbyFlowMoviePlayer.cancel_active_encoding
)


def _embyflow_rcdev7_log(message):
    try:
        with embyflow_open_log(
            "/tmp/embyflow_serversafe_v17_5_7.log",
            "a",
            encoding="utf-8",
        ) as log:
            log.write(
                "%s %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_rcdev7_static_direct(player):
    try:
        url = str(getattr(player, "stream_url", "") or "")
        if not url or not embyflow_is_static_stream_url(url):
            return False

        mode = str(
            getattr(player, "embyflow_playback_mode", "")
            or (getattr(player, "playback_info", None) or {}).get(
                "playback_mode",
                "",
            )
            or "direct"
        ).strip().lower()

        # Static=true is the decisive safety property. Reject known transcode
        # modes even if a malformed URL happened to contain Static=true.
        if "transcod" in mode or "quality" in mode:
            return False
        return True
    except Exception:
        return False


def _embyflow_rcdev7_native_seek_now(player, target_ticks):
    try:
        target_ticks = max(0, int(target_ticks or 0))
        service = player.session.nav.getCurrentService()
        seekable = service and service.seek()
        if not seekable:
            return False

        target_pts = int((target_ticks * 90000) // 10000000)
        result = seekable.seekTo(target_pts)
        accepted = result in (None, 0)
        _embyflow_rcdev7_log(
            "NATIVE_SEEK item=%s target=%s result=%r accepted=%s"
            % (
                str(getattr(player, "item_id", "") or "-"),
                target_ticks,
                result,
                int(bool(accepted)),
            )
        )
        if not accepted:
            return False

        player.embyflow_v10_stream_base_ticks = None
        player.embyflow_v10_stream_started_monotonic = None
        player.embyflow_v10_stream_confirmed_playing = False
        player.embyflow_v10_stream_time_mode = None
        player.synthetic_position_ticks = int(target_ticks)
        player.pending_seek_started_ticks = None
        player.pending_seek_target_ticks = None
        player.initial_big_seek_target_ticks = None
        player.seek_has_been_used = True
        player.paused = False
        try:
            player.play_started_ts = int(time.time()) - int(
                target_ticks // 10000000
            )
        except Exception:
            pass
        try:
            player.update_playback_overlay()
            player.show_overlay()
        except Exception:
            pass
        try:
            player.send_emby_playback_report("Progress", target_ticks)
        except Exception:
            pass
        return True
    except Exception as error:
        _embyflow_rcdev7_log(
            "NATIVE_SEEK_ERROR item=%s target=%s type=%s message=%s"
            % (
                str(getattr(player, "item_id", "") or "-"),
                str(target_ticks),
                type(error).__name__,
                str(error).replace("\n", " ")[:240],
            )
        )
        return False


def _embyflow_rcdev7_switch_static_to_ext(player, target_ticks):
    """Keep DirectPlay static; change only the local receiver backend."""
    try:
        target_ticks = max(0, int(target_ticks or 0))
        if not _embyflow_engine_v11_4_exteplayer3_available():
            _embyflow_rcdev7_log(
                "DIRECT_BLOCK item=%s target=%s reason=exteplayer3_unavailable"
                % (
                    str(getattr(player, "item_id", "") or "-"),
                    target_ticks,
                )
            )
            return False

        current_url = str(getattr(player, "stream_url", "") or "")
        if not current_url or not embyflow_is_static_stream_url(current_url):
            return False

        # No new PlaySessionId and no StartTimeTicks: the server continues to see
        # one DirectPlay session. Only the local player backend changes 4097->5002.
        old_session_id = str(
            getattr(player, "play_session_id", "") or ""
        )
        new_ref = eServiceReference(5002, 0, current_url)
        new_ref.setName(str(getattr(player, "title_text", "") or ""))

        # Supersede any old asynchronous seek-report generation. This direct path
        # creates no replacement server session and therefore starts no cleanup
        # worker.
        try:
            player._embyflow_seek_async_generation_v17_5_6 = int(
                getattr(
                    player,
                    "_embyflow_seek_async_generation_v17_5_6",
                    0,
                )
                or 0
            ) + 1
        except Exception:
            pass

        player.embyflow_engine_mode_v11_4 = "ext"
        player.embyflow_engine_service_type_v11_4 = 5002
        player.ref = new_ref
        player.embyflow_v10_stream_base_ticks = None
        player.embyflow_v10_stream_started_monotonic = None
        player.embyflow_v10_stream_confirmed_playing = False
        player.embyflow_v10_stream_time_mode = None
        player.embyflow_v10_clock_wait_logged = False

        try:
            player.playback_info["engine_mode"] = "ext"
            player.playback_info["service_type"] = 5002
            # URL/session intentionally unchanged.
            player.playback_info["url"] = current_url
            player.playback_info["play_session_id"] = old_session_id
        except Exception:
            pass

        _embyflow_rcdev7_log(
            "DIRECT_EXT_SWITCH_BEGIN item=%s target=%s session=%s static=1"
            % (
                str(getattr(player, "item_id", "") or "-"),
                target_ticks,
                old_session_id or "-",
            )
        )

        player._embyflow_stream_replacement_in_progress = True
        try:
            player.session.nav.playService(new_ref)
        finally:
            player._embyflow_stream_replacement_in_progress = False

        player.paused = False
        try:
            player.audio_retry_count = 0
            player.audio_timer.start(1200, True)
        except Exception:
            pass

        # ExtEplayer3 may need a short startup window before seekTo is accepted.
        # Reuse the already existing receiver-local retry timer; it performs no
        # HTTP stream restart and no ActiveEncodings operation.
        _embyflow_qs_v2_schedule_resume(player, target_ticks)

        try:
            player["state_label"].setText(
                "Direct Play · lokaler Seek (ExtEplayer3)"
            )
            player.show_overlay()
        except Exception:
            pass

        _embyflow_rcdev7_log(
            "DIRECT_EXT_SWITCH_RETURN item=%s target=%s session=%s"
            % (
                str(getattr(player, "item_id", "") or "-"),
                target_ticks,
                old_session_id or "-",
            )
        )
        return True

    except Exception as error:
        _embyflow_rcdev7_log(
            "DIRECT_EXT_SWITCH_ERROR item=%s target=%s type=%s message=%s"
            % (
                str(getattr(player, "item_id", "") or "-"),
                str(target_ticks),
                type(error).__name__,
                str(error).replace("\n", " ")[:240],
            )
        )
        return False


def _embyflow_rcdev7_restart_stream(
    self,
    target_ticks,
    subtitle_stream_index=None,
    subtitle_label=None,
):
    target_ticks = max(0, int(target_ticks or 0))

    if _embyflow_rcdev7_static_direct(self):
        # First try the currently active local backend. On 4097 CLEAN2 logs show
        # -1/no movement; on 5002 this should normally succeed immediately.
        if _embyflow_rcdev7_native_seek_now(self, target_ticks):
            return True

        # AUTO may promote a static DirectPlay stream to receiver-local 5002.
        # Explicit E2 mode is respected and fails closed rather than invoking a
        # Static=false server remux.
        requested_mode = _embyflow_engine_v11_4_mode(self)
        if requested_mode == "e2":
            _embyflow_rcdev7_log(
                "DIRECT_BLOCK item=%s target=%s reason=explicit_e2_mode"
                % (
                    str(getattr(self, "item_id", "") or "-"),
                    target_ticks,
                )
            )
            return False

        return _embyflow_rcdev7_switch_static_to_ext(
            self,
            target_ticks,
        )

    # A stream that is already a real HLS/transcode session keeps the existing
    # restart logic. Replacement cleanup is hardened separately below.
    return _EMBYFLOW_RCDEV7_ORIGINAL_RESTART_STREAM(
        self,
        target_ticks,
        subtitle_stream_index,
        subtitle_label,
    )


def _embyflow_rcdev7_send_stopped_old_session(self, play_session_id):
    try:
        psid = str(play_session_id or "").strip()
        if not psid:
            return "SKIP"

        info = getattr(self, "playback_info", None) or {}
        server = str(
            info.get("server")
            or EMBY_AUTH_CACHE.get("server")
            or EMBY_SERVER
            or ""
        ).rstrip("/")
        token = str(
            info.get("token")
            or EMBY_AUTH_CACHE.get("token")
            or ""
        )
        if not server or not token:
            return "SKIP"

        item = getattr(self, "item", None) or info.get("item") or {}
        item_id = str(
            getattr(self, "item_id", "")
            or item.get("Id")
            or item.get("id")
            or ""
        )
        media_source_id = str(
            getattr(self, "media_source_id", "") or ""
        )
        if not media_source_id:
            try:
                sources = item.get("MediaSources") or item.get("media_sources") or []
                if sources:
                    media_source_id = str(
                        sources[0].get("Id")
                        or sources[0].get("id")
                        or ""
                    )
            except Exception:
                pass

        # Do not touch Enigma2 service objects from this helper. The synthetic
        # position is plain player state and sufficient for ending the old server
        # session; the new session will report its own authoritative progress.
        try:
            position_ticks = max(
                0,
                int(getattr(self, "synthetic_position_ticks", 0) or 0),
            )
        except Exception:
            position_ticks = 0

        payload = {
            "ItemId": item_id,
            "PlaySessionId": psid,
            "PositionTicks": position_ticks,
            "IsPaused": True,
            "PlaybackRate": 1,
        }
        if media_source_id:
            payload["MediaSourceId"] = media_source_id

        response = embyflow_http_post(
            server + "/emby/Sessions/Playing/Stopped?reqformat=json",
            headers={
                "X-Emby-Token": token,
                "X-Emby-Authorization": AUTH_HEADER,
            },
            json=payload,
            timeout=5,
            verify=True,
        )
        return str(getattr(response, "status_code", "?"))
    except Exception as error:
        _embyflow_rcdev7_log(
            "OLD_STOPPED_ERROR session=%s type=%s message=%s"
            % (
                str(play_session_id or "-"),
                type(error).__name__,
                str(error).replace("\n", " ")[:240],
            )
        )
        return "ERROR"


def _embyflow_rcdev7_cancel_active_encoding(self, play_session_id=None):
    psid = str(
        play_session_id
        if play_session_id is not None
        else getattr(self, "play_session_id", "")
        or ""
    ).strip()
    current_psid = str(getattr(self, "play_session_id", "") or "").strip()

    # Exit already sends Stopped for the current session before calling cleanup.
    # Only replacement/old sessions need the additional Stopped here.
    is_old_session = bool(psid and current_psid and psid != current_psid)

    def stop_then_delete():
        stopped_status = "SKIP"
        if is_old_session:
            stopped_status = _embyflow_rcdev7_send_stopped_old_session(
                self,
                psid,
            )
        delete_ok = _EMBYFLOW_RCDEV7_ORIGINAL_CANCEL_ACTIVE_ENCODING(
            self,
            psid,
        )
        _embyflow_rcdev7_log(
            "OLD_SESSION_CLEANUP session=%s stopped=%s delete=%s"
            % (
                psid or "-",
                stopped_status,
                int(bool(delete_ok)),
            )
        )
        return bool(delete_ok)

    # Quality/stall replacement paths call cleanup from Enigma2's main thread.
    # Do not add another synchronous POST there; move the whole old-session
    # Stopped+DELETE sequence to a worker.
    if is_old_session:
        try:
            import threading
            if threading.current_thread() == threading.main_thread():
                worker = threading.Thread(
                    target=stop_then_delete,
                    name="EmbyFlowOldSessionCleanupV17_5_7",
                )
                worker.daemon = True
                worker.start()
                return True
        except Exception:
            pass

    return stop_then_delete()


# Final precedence.
EmbyFlowMoviePlayer.embyflow_v10_restart_stream = (
    _embyflow_rcdev7_restart_stream
)
EmbyFlowMoviePlayer.cancel_active_encoding = (
    _embyflow_rcdev7_cancel_active_encoding
)

