# EMBYFLOW_CLASSIC_SUBTITLES_RESTORED_0628_RELEASE

# EMBYFLOW_ALL_SUBTITLE_STREAMS_0629_RELEASE
# Selector inventory only: list every Subtitle MediaStream from the active
# MediaSource. Text subtitles keep the proven 0628 renderer. Bitmap tracks
# are visible but this selector never starts server-side video transcoding.
def _embyflow_subtitle_streams_0629(self):
    item = getattr(self, "item", None) or {}
    sources = item.get("MediaSources") or item.get("media_sources") or []
    if not sources:
        return []

    wanted = str(getattr(self, "media_source_id", "") or "")
    source = None
    if wanted:
        for candidate in sources:
            candidate_id = str(candidate.get("Id") or candidate.get("id") or "")
            if candidate_id == wanted:
                source = candidate
                break

    if source is None:
        source = sources[0]

    streams = source.get("MediaStreams") or source.get("media_streams") or []
    return [
        stream for stream in streams
        if str(stream.get("Type") or stream.get("type") or "").strip().lower() == "subtitle"
    ]


def _embyflow_subtitle_language_0629(self, stream, position):
    fallback = "Untertitel %d" % (int(position) + 1)
    value = (
        stream.get("Language")
        or stream.get("DisplayLanguage")
        or stream.get("DisplayTitle")
        or fallback
    )
    try:
        return self.embyflow_track_language_name(value, fallback)
    except Exception:
        return str(value or fallback)


def _embyflow_subtitle_codec_0629(self, stream):
    codec = str(stream.get("Codec") or "").strip()
    aliases = {
        "subrip": "SRT",
        "srt": "SRT",
        "pgssub": "PGS",
        "hdmv_pgs_subtitle": "PGS",
        "dvdsub": "DVDSUB",
        "dvd_subtitle": "DVDSUB",
        "dvbsub": "DVBSUB",
        "dvb_subtitle": "DVBSUB",
        "vobsub": "VOBSUB",
        "xsub": "XSUB",
    }
    if codec.lower() in aliases:
        return aliases[codec.lower()]
    try:
        value = self.embyflow_track_codec_name(codec)
        if value:
            return value
    except Exception:
        pass
    return codec.upper() or "UT"


def _embyflow_subtitle_flags_0629(stream):
    flags = []
    title_text = " ".join((
        str(stream.get("Title") or ""),
        str(stream.get("DisplayTitle") or ""),
    )).lower()
    if stream.get("IsForced") or "forced" in title_text or "erzw" in title_text:
        flags.append("Erzw.")
    if stream.get("IsHearingImpaired") or "sdh" in title_text or "hearing" in title_text:
        flags.append("SDH")
    return "/".join(flags)


def _embyflow_subtitle_open_0629(self):
    try:
        streams = _embyflow_subtitle_streams_0629(self)
        entries = [{
            "primary": "Untertitel aus",
            "secondary": "",
            "tertiary": "",
            "active": self.embyflow_active_subtitle_index is None,
            "payload": ("subtitle_off", None, "Aus", None),
        }]

        for position, stream in enumerate(streams):
            language = _embyflow_subtitle_language_0629(self, stream, position)
            codec = _embyflow_subtitle_codec_0629(self, stream)
            flags = _embyflow_subtitle_flags_0629(stream)
            try:
                is_text = bool(_embyflow_srt_v2_is_text_stream(stream))
            except Exception:
                is_text = bool(stream.get("IsTextSubtitleStream"))

            action = "subtitle" if is_text else "subtitle_bitmap_info_0629"
            entries.append({
                "primary": language,
                "secondary": codec,
                "tertiary": flags,
                "active": self.embyflow_active_subtitle_index == position,
                "payload": (action, stream, language, position),
            })

        if len(entries) == 1:
            raise RuntimeError("Keine Untertitelspuren in der aktiven MediaSource gefunden")

        active_index = 0
        for index, entry in enumerate(entries):
            if entry.get("active"):
                active_index = index
                break

        self.session.openWithCallback(
            self.subtitle_selection_finished,
            EmbyFlowTrackSelectionScreen,
            title="Untertitel auswählen",
            entries=entries,
            active_index=active_index,
        )
    except Exception as error:
        self.session.open(
            MessageBox,
            "Untertitelauswahl nicht verfügbar: %s" % str(error),
            MessageBox.TYPE_INFO,
            timeout=4,
        )


def _embyflow_subtitle_finished_0629(self, result):
    if not result:
        return

    try:
        action, stream, label, position = result

        if action == "subtitle_off":
            return _embyflow_srt_v2_selection_finished(
                self,
                ("subtitle_off", None, label, position),
            )

        if action == "subtitle":
            return _embyflow_srt_v2_selection_finished(
                self,
                ("subtitle", None, label, position),
            )

        if action == "subtitle_bitmap_info_0629":
            codec = _embyflow_subtitle_codec_0629(self, stream or {})
            delivery = str((stream or {}).get("DeliveryMethod") or "").strip()
            suffix = " (Emby: %s)" % delivery if delivery else ""
            self.session.open(
                MessageBox,
                "%s-Untertitel ist in Emby vorhanden%s, wird aber nicht automatisch transcodiert."
                % (codec, suffix),
                MessageBox.TYPE_INFO,
                timeout=5,
            )
            return
    except Exception as error:
        self.session.open(
            MessageBox,
            "Untertitel konnten nicht gewechselt werden: %s" % str(error),
            MessageBox.TYPE_ERROR,
            timeout=5,
        )


EmbyFlowMoviePlayer.open_subtitle_selection = _embyflow_subtitle_open_0629
EmbyFlowMoviePlayer.subtitle_selection_finished = _embyflow_subtitle_finished_0629

# EMBYFLOW_GERMAN_KEYBOARD_V22_0630_RELEASE

# EMBYFLOW_SERVER_MANAGER_V1_0631_RELEASE
# Vier Server-Slots bleiben kompatibel. MENU auf einer Serverkarte öffnet
# Verwenden / Bearbeiten / Löschen. Löschen ist bestätigt und löscht nur den
# gewählten Slot. Der aktive Runtime-Server wird nur dann zurückgesetzt, wenn
# genau dieser konfigurierte Server gelöscht wurde.
def _embyflow_server_manager_v1_selected_index(self):
    try:
        if int(getattr(self, "focus", -1)) in (0, 1, 2, 3):
            return int(self.focus)
    except Exception:
        pass
    try:
        return max(0, min(3, int(self.selected_server_index)))
    except Exception:
        return 0


def _embyflow_server_manager_v1_open(self):
    index = _embyflow_server_manager_v1_selected_index(self)
    current = str(self.server_slots[index] or "").strip()

    if not current:
        self.edit_server_slot(index)
        return

    choices = [
        ("Server verwenden", ("use", index)),
        ("Server bearbeiten", ("edit", index)),
        ("Server löschen", ("delete", index)),
        ("Abbrechen", ("cancel", index)),
    ]
    self.session.openWithCallback(
        self._embyflow_server_manager_v1_choice_done,
        ChoiceBox,
        title="Server %d verwalten" % (index + 1),
        list=choices,
    )


def _embyflow_server_manager_v1_choice_done(self, result=None):
    if result is None:
        return

    value = result
    if isinstance(result, (tuple, list)):
        value = result[1] if len(result) > 1 else result[0]

    try:
        action, index = value
        index = max(0, min(3, int(index)))
    except Exception:
        return

    if action == "cancel":
        return
    if action == "use":
        self._select_server(index)
        return
    if action == "edit":
        self.edit_server_slot(index)
        return
    if action != "delete":
        return

    current = str(self.server_slots[index] or "").strip()
    if not current:
        return

    self._embyflow_server_manager_v1_pending_delete = index
    self.session.openWithCallback(
        self._embyflow_server_manager_v1_delete_done,
        MessageBox,
        "Server %d wirklich löschen?\n\n%s" % (index + 1, current),
        MessageBox.TYPE_YESNO,
        default=False,
    )


def _embyflow_server_manager_v1_delete_done(self, answer=False):
    try:
        pending = getattr(self, "_embyflow_server_manager_v1_pending_delete", None)
        if pending is None:
            return
        index = max(0, min(3, int(pending)))
    except Exception:
        return

    self._embyflow_server_manager_v1_pending_delete = None
    if not answer:
        return

    removed = str(self.server_slots[index] or "").strip().rstrip("/")
    active = ""
    try:
        active = self._cfg(config.embyflow.server).strip().rstrip("/")
    except Exception:
        active = ""

    self._save_slot(index, "")
    self.server_runtime_states.pop(index, None)

    remaining = [
        slot_index
        for slot_index, value in enumerate(self.server_slots)
        if str(value or "").strip()
    ]
    self.selected_server_index = remaining[0] if remaining else 0
    self.focus = self.selected_server_index
    self._apply_selected_slot(clear_password=True)

    removed_was_active = bool(
        removed
        and active
        and removed.casefold() == active.casefold()
    )
    if removed_was_active:
        try:
            self._set_cfg(config.embyflow.server, "")
            config.embyflow.server.save()
            configfile.save()
        except Exception:
            pass
        try:
            apply_emby_runtime_config()
        except Exception:
            pass
        try:
            clear_emby_auth_cache()
        except Exception:
            pass
        try:
            EMBY_AUTH_CACHE["server"] = ""
            EMBY_AUTH_CACHE["token"] = ""
            EMBY_AUTH_CACHE["user_id"] = ""
            EMBY_AUTH_CACHE["ts"] = 0
        except Exception:
            pass

    if remaining:
        suffix = " Aktiver Login wurde zurückgesetzt; bitte neu anmelden." if removed_was_active else ""
        self["server_status"].setText(
            "Server %d gelöscht. Server %d ist ausgewählt.%s"
            % (index + 1, self.selected_server_index + 1, suffix)
        )
    else:
        suffix = " Aktiver Login wurde zurückgesetzt." if removed_was_active else ""
        self["server_status"].setText(
            "Server %d gelöscht. Kein Server eingerichtet.%s"
            % (index + 1, suffix)
        )

    self["login_status"].setText("")
    self.refresh_all()


EmbyFlowConnectionWizard.manage_server_slot = _embyflow_server_manager_v1_open
EmbyFlowConnectionWizard._embyflow_server_manager_v1_choice_done = _embyflow_server_manager_v1_choice_done
EmbyFlowConnectionWizard._embyflow_server_manager_v1_delete_done = _embyflow_server_manager_v1_delete_done

# EMBYFLOW_SERVER_MANAGER_UI_V2_0632_RELEASE
# Eigenes EmbyFlow-Menü statt Enigma2-ChoiceBox. Keine Playback-/Serverlogik
# geändert; nur Darstellung und Bedienung der vorhandenen vier Server-Slots.
class EmbyFlowServerManageScreenV2(Screen):
    skin = scale_skin("""
    <screen name="EmbyFlowServerManageScreenV2" position="0,0" size="1920,1080" flags="wfNoBorder" backgroundColor="#030811">
        <eLabel position="0,0" size="1920,1080" backgroundColor="#030811" />

        <eLabel text="EMBY" position="92,58" size="210,58" font="Bold;46" foregroundColor="#23E6E8" backgroundColor="#030811" transparent="1" />
        <eLabel text="FLOW" position="302,58" size="210,58" font="Bold;46" foregroundColor="#FF42B5" backgroundColor="#030811" transparent="1" />
        <eLabel text="SERVERVERWALTUNG" position="96,122" size="470,34" font="Regular;20" foregroundColor="#8D96A1" backgroundColor="#030811" transparent="1" />
        <eLabel text="0633" position="1640,66" size="190,34" font="Regular;20" foregroundColor="#23E6E8" backgroundColor="#030811" transparent="1" halign="right" />

        <eLabel position="90,184" size="1740,2" backgroundColor="#1689FF" />

        <eLabel position="190,235" size="1540,690" backgroundColor="#07111E" />
        <eLabel position="194,239" size="1532,682" backgroundColor="#050C16" />

        <widget name="title" position="260,278" size="900,52" font="Bold;38" foregroundColor="#F4F7FB" backgroundColor="#050C16" transparent="1" />
        <widget name="badge" position="1350,284" size="290,42" font="Bold;20" foregroundColor="#42E66B" backgroundColor="#050C16" transparent="1" halign="right" />
        <widget name="server_url" position="260,342" size="1380,42" font="Regular;24" foregroundColor="#AAB7C8" backgroundColor="#050C16" transparent="1" />
        <widget name="hint" position="260,395" size="1380,54" font="Regular;20" foregroundColor="#748297" backgroundColor="#050C16" transparent="1" />

        <widget name="row0" position="260,478" size="1380,76" font="Bold;27" foregroundColor="#F4F7FB" backgroundColor="#0B1521" transparent="0" valign="center" />
        <widget name="row1" position="260,570" size="1380,76" font="Bold;27" foregroundColor="#F4F7FB" backgroundColor="#0B1521" transparent="0" valign="center" />
        <widget name="row2" position="260,662" size="1380,76" font="Bold;27" foregroundColor="#F4F7FB" backgroundColor="#0B1521" transparent="0" valign="center" />
        <widget name="row3" position="260,754" size="1380,76" font="Bold;27" foregroundColor="#F4F7FB" backgroundColor="#0B1521" transparent="0" valign="center" />

        <eLabel text="ROT  Zurück" position="260,864" size="320,34" font="Regular;21" foregroundColor="#FF6B79" backgroundColor="#050C16" transparent="1" />
        <eLabel text="OK / GRÜN  Auswählen" position="600,864" size="430,34" font="Regular;21" foregroundColor="#42E66B" backgroundColor="#050C16" transparent="1" />
        <eLabel text="▲ / ▼  Navigieren" position="1170,864" size="470,34" font="Regular;21" foregroundColor="#8D96A1" backgroundColor="#050C16" transparent="1" halign="right" />
    </screen>
    """)

    def __init__(self, session, slot_index, server_url, active=False):
        Screen.__init__(self, session)
        self.slot_index = max(0, min(3, int(slot_index)))
        self.server_url = str(server_url or "").strip()
        self.active = bool(active)
        self.confirming = False
        self.index = 0
        self.entries = []

        # 0633: Inhalte bereits VOR dem ersten GUI-Layout setzen.
        # Manche Images führen onLayoutFinish für diesen Vollbild-Screen nicht zuverlässig aus.
        self["title"] = Label("SERVER %d VERWALTEN" % (self.slot_index + 1))
        self["badge"] = Label("● AKTIV" if self.active else "BEREIT")
        self["server_url"] = Label(self._display_url())
        self["hint"] = Label("Server auswählen, Adresse bearbeiten oder den gespeicherten Slot entfernen.")
        initial_rows = (
            "  ›  Server verwenden",
            "     Server bearbeiten",
            "     Server löschen",
            "     Zurück",
        )
        for row in range(4):
            self["row%d" % row] = Label(initial_rows[row])

        self["actions"] = ActionMap(
            ["OkCancelActions", "DirectionActions", "ColorActions"],
            {
                "cancel": self.go_back,
                "red": self.go_back,
                "ok": self.activate,
                "green": self.activate,
                "up": self.move_up,
                "down": self.move_down,
                "left": self.move_up,
                "right": self.move_down,
            },
            -1,
        )
        # Datenmodell sofort füllen; Styling wird nach dem Layout erneut gesetzt.
        self.refresh()
        self.onLayoutFinish.append(self.refresh)
        try:
            self.onShow.append(self.refresh)
        except Exception:
            pass

    def _display_url(self):
        value = str(self.server_url or "")
        try:
            value = re.sub(
                r"(?i)(https?://)[^/@\s]+:[^/@\s]+@",
                r"\1•••:•••@",
                value,
            )
        except Exception:
            pass
        if len(value) > 92:
            value = value[:89] + "..."
        return value

    def _set_row_style(self, row, selected):
        try:
            widget = self["row%d" % row]
            if widget.instance is not None:
                widget.instance.setBackgroundColor(
                    parseColor("#1689FF" if selected else "#0B1521")
                )
                widget.instance.setForegroundColor(
                    parseColor("#FFFFFF" if selected else "#F4F7FB")
                )
        except Exception:
            pass

    def _main_entries(self):
        return [
            ("Server verwenden", "use"),
            ("Server bearbeiten", "edit"),
            ("Server löschen", "delete_prompt"),
            ("Zurück", "cancel"),
        ]

    def _confirm_entries(self):
        return [
            ("Nein, Server behalten", "cancel_delete"),
            ("Ja, Server endgültig löschen", "delete"),
        ]

    def refresh(self):
        self.entries = self._confirm_entries() if self.confirming else self._main_entries()
        self.index = max(0, min(len(self.entries) - 1, int(self.index)))

        if self.confirming:
            self["title"].setText("SERVER %d LÖSCHEN" % (self.slot_index + 1))
            self["badge"].setText("SICHERHEITSABFRAGE")
            self["hint"].setText(
                "Nur dieser Server-Slot wird gelöscht. Ein aktiver Login wird bei Bedarf sicher zurückgesetzt."
            )
        else:
            self["title"].setText("SERVER %d VERWALTEN" % (self.slot_index + 1))
            self["badge"].setText("● AKTIV" if self.active else "BEREIT")
            self["hint"].setText(
                "Server auswählen, Adresse bearbeiten oder den gespeicherten Slot entfernen."
            )

        self["server_url"].setText(self._display_url())

        for row in range(4):
            label = self.entries[row][0] if row < len(self.entries) else ""
            prefix = "  ›  " if row == self.index and label else "     "
            self["row%d" % row].setText(prefix + label if label else "")
            self._set_row_style(row, row == self.index and bool(label))

    def move_up(self):
        if not self.entries:
            return
        self.index = (self.index - 1) % len(self.entries)
        self.refresh()

    def move_down(self):
        if not self.entries:
            return
        self.index = (self.index + 1) % len(self.entries)
        self.refresh()

    def go_back(self):
        if self.confirming:
            self.confirming = False
            self.index = 2
            self.refresh()
            return
        self.close(None)

    def activate(self):
        if not self.entries:
            return
        action = self.entries[self.index][1]
        if action == "delete_prompt":
            self.confirming = True
            self.index = 0
            self.refresh()
            return
        if action == "cancel_delete":
            self.confirming = False
            self.index = 2
            self.refresh()
            return
        if action == "cancel":
            self.close(None)
            return
        self.close((action, self.slot_index))


def _embyflow_server_manager_v2_open(self):
    index = _embyflow_server_manager_v1_selected_index(self)
    current = str(self.server_slots[index] or "").strip()
    if not current:
        self.edit_server_slot(index)
        return

    active = ""
    try:
        active = self._cfg(config.embyflow.server).strip().rstrip("/")
    except Exception:
        pass
    is_active = bool(
        active and current.rstrip("/").casefold() == active.casefold()
    )

    self.session.openWithCallback(
        self._embyflow_server_manager_v2_result,
        EmbyFlowServerManageScreenV2,
        index,
        current,
        is_active,
    )


def _embyflow_server_manager_v2_result(self, result=None):
    if not result:
        return
    try:
        action, index = result
        index = max(0, min(3, int(index)))
    except Exception:
        return

    if action == "use":
        self._select_server(index)
        return
    if action == "edit":
        self.edit_server_slot(index)
        return
    if action == "delete":
        self._embyflow_server_manager_v1_pending_delete = index
        self._embyflow_server_manager_v1_delete_done(True)
        return


EmbyFlowConnectionWizard.manage_server_slot = _embyflow_server_manager_v2_open
EmbyFlowConnectionWizard._embyflow_server_manager_v2_result = _embyflow_server_manager_v2_result


# EMBYFLOW_SERVER_MANAGER_UI_V2_PAINTFIX_0633_RELEASE


# EMBYFLOW_SERVER_MANAGER_UI_V3_MENULIST_0634_RELEASE
# 0632/0633 zeigten auf einzelnen OpenATV-Images zwar den statischen Skin,
# aber keine dynamischen Label-Komponenten. V3 verwendet deshalb für ALLE
# variablen Inhalte einen echten Enigma2-MenuList-Unterbau. Keine ChoiceBox,
# keine Playback-/Serverlogikänderung.
class EmbyFlowServerManageScreenV3List(Screen):
    skin = scale_skin("""
    <screen name="EmbyFlowServerManageScreenV3List" position="0,0" size="1920,1080" flags="wfNoBorder" backgroundColor="#030811">
        <eLabel position="0,0" size="1920,1080" zPosition="0" backgroundColor="#030811" />

        <eLabel text="EMBY" position="92,58" size="210,58" zPosition="30" font="Bold;46" foregroundColor="#23E6E8" backgroundColor="#030811" transparent="1" />
        <eLabel text="FLOW" position="302,58" size="210,58" zPosition="30" font="Bold;46" foregroundColor="#FF42B5" backgroundColor="#030811" transparent="1" />
        <eLabel text="SERVERVERWALTUNG" position="96,122" size="470,34" zPosition="30" font="Regular;20" foregroundColor="#8D96A1" backgroundColor="#030811" transparent="1" />
        <eLabel text="0635" position="1640,66" size="190,34" zPosition="30" font="Regular;20" foregroundColor="#23E6E8" backgroundColor="#030811" transparent="1" halign="right" />
        <eLabel position="90,184" size="1740,2" zPosition="30" backgroundColor="#1689FF" />

        <eLabel position="190,235" size="1540,690" zPosition="1" backgroundColor="#07111E" />
        <eLabel position="194,239" size="1532,682" zPosition="2" backgroundColor="#050C16" />

        <widget name="menu" position="260,286" size="1380,500" zPosition="20" font="Regular;30" itemHeight="92" foregroundColor="#EAF1F8" foregroundColorSelected="#FFFFFF" backgroundColor="#050C16" backgroundColorSelected="#1689FF" transparent="0" scrollbarMode="showNever" />

        <eLabel text="ROT  Zurück" position="260,864" size="320,34" zPosition="30" font="Regular;21" foregroundColor="#FF6B79" backgroundColor="#050C16" transparent="1" />
        <eLabel text="OK / GRÜN  Auswählen" position="600,864" size="430,34" zPosition="30" font="Regular;21" foregroundColor="#42E66B" backgroundColor="#050C16" transparent="1" />
        <eLabel text="▲ / ▼  Navigieren" position="1170,864" size="470,34" zPosition="30" font="Regular;21" foregroundColor="#8D96A1" backgroundColor="#050C16" transparent="1" halign="right" />
    </screen>
    """)

    def __init__(self, session, slot_index, server_url, active=False):
        Screen.__init__(self, session)
        self.slot_index = max(0, min(3, int(slot_index)))
        self.server_url = str(server_url or "").strip()
        self.active = bool(active)
        self.confirming = False
        self["menu"] = MenuList(
            self._main_entries(),
            enableWrapAround=True,
        )
        self["actions"] = ActionMap(
            ["OkCancelActions", "DirectionActions", "ColorActions"],
            {
                "cancel": self.go_back,
                "red": self.go_back,
                "ok": self.activate,
                "green": self.activate,
                "up": self.move_up,
                "down": self.move_down,
                "left": self.move_up,
                "right": self.move_down,
            },
            -1,
        )

    def _safe_url(self):
        value = str(self.server_url or "").strip()
        try:
            value = re.sub(
                r"(?i)(https?://)[^/@\s]+:[^/@\s]+@",
                r"\1•••:•••@",
                value,
            )
        except Exception:
            pass
        if len(value) > 58:
            value = value[:55] + "..."
        return value

    def _main_entries(self):
        number = self.slot_index + 1
        state = "AKTIV" if self.active else "BEREIT"
        url = self._safe_url() or "keine Adresse"
        return [
            "SERVER %d  •  %s  —  %s" % (number, state, url),
            "Server %d verwenden" % number,
            "Server %d bearbeiten" % number,
            "Server %d löschen" % number,
            "Zurück",
        ]

    def _confirm_entries(self):
        number = self.slot_index + 1
        return [
            "SERVER %d WIRKLICH LÖSCHEN?" % number,
            "Nein — Server behalten",
            "Ja — Server endgültig löschen",
        ]

    def _set_entries(self, entries, index=0):
        self["menu"].setList(list(entries or []))
        try:
            self["menu"].moveToIndex(max(0, int(index)))
        except Exception:
            pass

    def move_up(self):
        try:
            self["menu"].up()
        except Exception:
            pass

    def move_down(self):
        try:
            self["menu"].down()
        except Exception:
            pass

    def _selected_index(self):
        try:
            return int(self["menu"].getSelectedIndex())
        except Exception:
            return 0

    def go_back(self):
        if self.confirming:
            self.confirming = False
            self._set_entries(self._main_entries(), 3)
            return
        self.close(None)

    def activate(self):
        index = self._selected_index()
        if self.confirming:
            if index == 2:
                self.close(("delete", self.slot_index))
                return
            if index in (0, 1):
                self.confirming = False
                self._set_entries(self._main_entries(), 3)
                return
            return

        if index == 0:
            try:
                self["menu"].moveToIndex(1)
            except Exception:
                pass
            return
        if index == 1:
            self.close(("use", self.slot_index))
            return
        if index == 2:
            self.close(("edit", self.slot_index))
            return
        if index == 3:
            self.confirming = True
            self._set_entries(self._confirm_entries(), 1)
            return
        self.close(None)


# EMBYFLOW_SERVER_MANAGER_UI_V3_ZORDER_0635_RELEASE
# OpenATV: panel backgrounds live below the dynamic MenuList; header/footer
# stay above both. This fixes the invisible-but-populated 0634 menu.


def _embyflow_server_manager_v3_open(self):
    index = _embyflow_server_manager_v1_selected_index(self)
    current = str(self.server_slots[index] or "").strip()
    if not current:
        self.edit_server_slot(index)
        return

    active = ""
    try:
        active = self._cfg(config.embyflow.server).strip().rstrip("/")
    except Exception:
        pass
    is_active = bool(
        active and current.rstrip("/").casefold() == active.casefold()
    )

    self.session.openWithCallback(
        self._embyflow_server_manager_v3_result,
        EmbyFlowServerManageScreenV3List,
        index,
        current,
        is_active,
    )


def _embyflow_server_manager_v3_result(self, result=None):
    if not result:
        return
    try:
        action, index = result
        index = max(0, min(3, int(index)))
    except Exception:
        return

    if action == "use":
        self._select_server(index)
        return
    if action == "edit":
        self.edit_server_slot(index)
        return
    if action == "delete":
        self._embyflow_server_manager_v1_pending_delete = index
        self._embyflow_server_manager_v1_delete_done(True)
        return


EmbyFlowConnectionWizard.manage_server_slot = _embyflow_server_manager_v3_open
EmbyFlowConnectionWizard._embyflow_server_manager_v3_result = _embyflow_server_manager_v3_result


