EmbyFlowConnectionWizard.SERVER_CARD_POSITIONS = (
    (620, 300),
    (620, 380),
    (620, 460),
    (620, 540),
)


def _embyflow_login_plex_structure_v18_refresh_cards(self):
    for index in range(4):
        try:
            value = str(self.server_slots[index] or "").strip()
        except Exception:
            value = ""

        state = self.server_runtime_states.get(index)
        selected = index == self.selected_server_index

        if state == "online":
            state_text = "ONLINE"
        elif state == "error":
            state_text = "FEHLER"
        elif value:
            state_text = "BEREIT"
        else:
            state_text = "LEER"

        if selected and value:
            state_text = "✓ " + state_text

        try:
            self["server_name%d" % index].setText(
                "Server %d" % (index + 1)
            )
            self["server_brand%d" % index].setText(
                value or "Nicht eingerichtet"
            )
            self["server_state%d" % index].setText(state_text)
            self["server_icon%d" % index].setText("")
        except Exception:
            pass

    try:
        idx = (
            self.focus
            if self.focus in (0, 1, 2, 3)
            else self.selected_server_index
        )
        x, y = self.SERVER_CARD_POSITIONS[idx]
        self["server_focus_border"].instance.move(EFP(x, y))
        self["server_focus_border"].instance.resize(EFS(1215, 68))
        self["server_focus_inner"].instance.move(EFP(x + 4, y + 4))
        self["server_focus_inner"].instance.resize(EFS(1207, 60))
        self["server_focus_border"].show()
        self["server_focus_inner"].show()
    except Exception:
        pass

    try:
        if not self.server:
            status = "Kein Server ausgewählt · OK zum Einrichten"
        elif self.connection_ok:
            status = "● Verbindung OK · %s" % (
                self.server_name or self._selected_server_label()
            )
        else:
            status = "● Bereit · GRÜN prüft die Verbindung"
        self["server_status"].setText(status)
    except Exception:
        pass


EmbyFlowConnectionWizard._refresh_server_cards = (
    _embyflow_login_plex_structure_v18_refresh_cards
)


def _embyflow_login_plex_structure_v18_focus_marker(self):
    try:
        if self.focus < 4:
            self["focus_marker"].hide()
            return

        positions = {
            4: (805, 674),  # Benutzername
            5: (805, 744),  # Passwort
            6: (805, 808),  # Speichern
            7: (595, 866),  # Anmelden
        }

        x, y = positions.get(self.focus, (805, 674))
        self["focus_marker"].setText(">")
        self["focus_marker"].instance.move(EFP(x, y))
        self["focus_marker"].instance.resize(EFS(28, 34))
        self["focus_marker"].show()
    except Exception:
        pass


EmbyFlowConnectionWizard._refresh_focus_marker = (
    _embyflow_login_plex_structure_v18_focus_marker
)


