def _embyflow_login_left_nav_v19_nav_geometry(index):
    # x, y, width, height
    rows = (
        (48, 148, 484, 112),
        (48, 280, 484, 108),
        (48, 400, 484, 108),
    )
    return rows[max(0, min(2, int(index or 0)))]


def _embyflow_login_left_nav_v19_refresh_nav(self):
    area = str(
        getattr(self, "embyflow_login_area_v19", "nav")
        or "nav"
    )

    names = (
        "nav_focus_top_v19",
        "nav_focus_bottom_v19",
        "nav_focus_left_v19",
        "nav_focus_right_v19",
        "nav_focus_arrow_v19",
    )

    if area != "nav":
        for name in names:
            try:
                self[name].hide()
            except Exception:
                pass
        return

    index = max(
        0,
        min(
            2,
            int(
                getattr(
                    self,
                    "embyflow_login_nav_index_v19",
                    0,
                )
                or 0
            ),
        ),
    )
    self.embyflow_login_nav_index_v19 = index

    x, y, width, height = _embyflow_login_left_nav_v19_nav_geometry(index)

    try:
        self["nav_focus_top_v19"].instance.move(EFP(x, y))
        self["nav_focus_top_v19"].instance.resize(EFS(width, 4))
        self["nav_focus_top_v19"].show()

        self["nav_focus_bottom_v19"].instance.move(
            EFP(x, y + height - 4)
        )
        self["nav_focus_bottom_v19"].instance.resize(EFS(width, 4))
        self["nav_focus_bottom_v19"].show()

        self["nav_focus_left_v19"].instance.move(EFP(x, y))
        self["nav_focus_left_v19"].instance.resize(EFS(4, height))
        self["nav_focus_left_v19"].show()

        self["nav_focus_right_v19"].instance.move(
            EFP(x + width - 4, y)
        )
        self["nav_focus_right_v19"].instance.resize(EFS(4, height))
        self["nav_focus_right_v19"].show()

        self["nav_focus_arrow_v19"].setText("›")
        self["nav_focus_arrow_v19"].instance.move(
            EFP(x + width - 46, y + ((height - 38) // 2))
        )
        self["nav_focus_arrow_v19"].instance.resize(EFS(30, 38))
        self["nav_focus_arrow_v19"].show()
    except Exception:
        pass


def _embyflow_login_left_nav_v19_refresh(self):
    _EMBYFLOW_LOGIN_LEFT_NAV_V19_PREV_REFRESH(self)

    area = str(
        getattr(self, "embyflow_login_area_v19", "nav")
        or "nav"
    )

    # Nie zwei Fokusrahmen gleichzeitig zeigen.
    if area == "nav":
        try:
            self["server_focus_border"].hide()
            self["server_focus_inner"].hide()
        except Exception:
            pass
        try:
            self["focus_marker"].hide()
        except Exception:
            pass

    _embyflow_login_left_nav_v19_refresh_nav(self)


EmbyFlowConnectionWizard.refresh_all = _embyflow_login_left_nav_v19_refresh


def _embyflow_login_left_nav_v19_enter_content(self):
    self.embyflow_login_area_v19 = "content"
    try:
        self.focus = max(
            0,
            min(3, int(self.selected_server_index)),
        )
    except Exception:
        self.focus = 0
    self.refresh_all()


def _embyflow_login_left_nav_v19_add_server(self):
    empty_index = None
    try:
        for index, value in enumerate(list(self.server_slots or [])):
            if not str(value or "").strip():
                empty_index = index
                break
    except Exception:
        empty_index = None

    if empty_index is not None:
        self.edit_server_slot(empty_index)
        return

    # Alle vier Plätze belegt: bestehende sichere Verwaltung verwenden.
    self.manage_server_slot()


def _embyflow_login_left_nav_v19_activate_nav(self):
    index = max(
        0,
        min(
            2,
            int(
                getattr(
                    self,
                    "embyflow_login_nav_index_v19",
                    0,
                )
                or 0
            ),
        ),
    )

    if index == 0:
        _embyflow_login_left_nav_v19_enter_content(self)
    elif index == 1:
        _embyflow_login_left_nav_v19_add_server(self)
    else:
        self.open_advanced_settings()


def _embyflow_login_left_nav_v19_up(self):
    if str(
        getattr(self, "embyflow_login_area_v19", "nav")
        or "nav"
    ) == "nav":
        self.embyflow_login_nav_index_v19 = max(
            0,
            int(getattr(self, "embyflow_login_nav_index_v19", 0) or 0) - 1,
        )
        self.refresh_all()
        return

    # Rechte Serverliste ist optisch vertikal: auch Navigation vertikal.
    if self.focus in (0, 1, 2, 3):
        if self.focus > 0:
            self.focus -= 1
        self.refresh_all()
        return

    _EMBYFLOW_LOGIN_LEFT_NAV_V19_PREV_UP(self)


def _embyflow_login_left_nav_v19_down(self):
    if str(
        getattr(self, "embyflow_login_area_v19", "nav")
        or "nav"
    ) == "nav":
        self.embyflow_login_nav_index_v19 = min(
            2,
            int(getattr(self, "embyflow_login_nav_index_v19", 0) or 0) + 1,
        )
        self.refresh_all()
        return

    # Server 1 -> 2 -> 3 -> 4 -> Benutzername.
    if self.focus in (0, 1, 2):
        self.focus += 1
        self.refresh_all()
        return
    if self.focus == 3:
        self.focus = 4
        self.refresh_all()
        return

    _EMBYFLOW_LOGIN_LEFT_NAV_V19_PREV_DOWN(self)


def _embyflow_login_left_nav_v19_left(self):
    if str(
        getattr(self, "embyflow_login_area_v19", "nav")
        or "nav"
    ) == "nav":
        return

    self.embyflow_login_area_v19 = "nav"
    self.embyflow_login_nav_index_v19 = 0
    self.refresh_all()


def _embyflow_login_left_nav_v19_right(self):
    if str(
        getattr(self, "embyflow_login_area_v19", "nav")
        or "nav"
    ) == "nav":
        # Nur "Weiter zu Emby" besitzt den rechten Hauptbereich.
        if int(
            getattr(self, "embyflow_login_nav_index_v19", 0)
            or 0
        ) == 0:
            _embyflow_login_left_nav_v19_enter_content(self)
        return

    # Im rechten Bereich brauchen LINKS/RECHTS keine horizontale
    # Servernavigation mehr; die Server stehen sichtbar untereinander.
    self.refresh_all()


def _embyflow_login_left_nav_v19_activate(self):
    if str(
        getattr(self, "embyflow_login_area_v19", "nav")
        or "nav"
    ) == "nav":
        _embyflow_login_left_nav_v19_activate_nav(self)
        return

    _EMBYFLOW_LOGIN_LEFT_NAV_V19_PREV_ACTIVATE(self)


def _embyflow_login_left_nav_v19_next(self):
    if str(
        getattr(self, "embyflow_login_area_v19", "nav")
        or "nav"
    ) == "nav":
        _embyflow_login_left_nav_v19_activate_nav(self)
        return

    _EMBYFLOW_LOGIN_LEFT_NAV_V19_PREV_NEXT(self)


