def _embyflow_login_v20_refresh(self):
    _EMBYFLOW_LOGIN_V20_PREV_REFRESH(self)

    # Fokus auf Eingaben als kompletter Rahmen statt nur kleinem Marker.
    _embyflow_login_v20_hide_field_focus(self)
    try:
        area = str(
            getattr(self, "embyflow_login_area_v19", "nav")
            or "nav"
        )
        if area == "content" and self.focus == 4:
            _embyflow_login_v20_show_field_focus(self, 662)
            self["focus_marker"].hide()
        elif area == "content" and self.focus == 5:
            _embyflow_login_v20_show_field_focus(self, 732)
            self["focus_marker"].hide()
    except Exception:
        pass

    # Keine Funktion vortaeuschen: bei leerem Slot fuehrt der Hauptbutton
    # zur Einrichtung und nicht zu einem unmoeglichen Login.
    try:
        if not str(self.server or "").strip():
            self["login_button"].setText("SERVER EINRICHTEN")
        else:
            self["login_button"].setText("ANMELDEN")
    except Exception:
        pass


EmbyFlowConnectionWizard.refresh_all = _embyflow_login_v20_refresh


def _embyflow_login_v20_classify_connection_error(detail):
    low = str(detail or "").lower()

    if "timed out" in low or "timeout" in low:
        return "Zeitüberschreitung beim Serverkontakt."
    if "name or service not known" in low or "getaddrinfo" in low:
        return "Servername konnte nicht aufgelöst werden."
    if "connection refused" in low:
        return "Verbindung wurde vom Server abgelehnt."
    if "certificate" in low or "ssl" in low:
        return "HTTPS-Zertifikat konnte nicht geprüft werden."
    if "http 401" in low or "http 403" in low:
        return "Server hat den Zugriff abgelehnt."
    if "http 404" in low:
        return "Emby-Endpunkt wurde auf diesem Server nicht gefunden."
    return "Server nicht erreichbar."


def _embyflow_login_v20_test_connection(self, automatic=False):
    index = int(self.selected_server_index)

    # Kein Request bei leerem Slot.
    if not str(self.server or "").strip():
        self.server_runtime_states[index] = ""
        self.connection_ok = False
        self.refresh_all()
        return False

    self.server_runtime_states[index] = "checking"
    self.connection_ok = False
    self.refresh_all()

    result = _EMBYFLOW_LOGIN_V20_PREV_TEST(
        self,
        automatic=automatic,
    )

    if result:
        try:
            name = str(self.server_name or "").strip()
            if name and not name.lower().startswith("server "):
                self.embyflow_server_names_v20[index] = name
        except Exception:
            pass

        self.server_runtime_states[index] = "online"
        self.connection_ok = True
        _embyflow_login_v20_log(
            "TEST_OK slot=%d name=%s"
            % (
                index + 1,
                _embyflow_login_v20_server_name(self, index)
                or "-",
            )
        )
    else:
        # Der alte Test hat die technische Ursache in server_status gesetzt.
        # Sie wird ins Debuglog uebernommen, aber nicht dem Endnutzer zugemutet.
        try:
            detail = self["server_status"].getText()
        except Exception:
            detail = ""

        self.server_runtime_states[index] = "error"
        self.connection_ok = False

        friendly = _embyflow_login_v20_classify_connection_error(detail)
        _embyflow_login_v20_log(
            "TEST_FAIL slot=%d detail=%s"
            % (index + 1, detail)
        )
        try:
            self["server_status"].setText(
                "● FEHLER · %s" % friendly
            )
        except Exception:
            pass

    self.refresh_all()
    return bool(result)


EmbyFlowConnectionWizard.test_connection = (
    _embyflow_login_v20_test_connection
)


def _embyflow_login_v20_classify_login_error(detail):
    low = str(detail or "").lower()

    if "http 401" in low or "unauthorized" in low:
        return "Benutzername oder Passwort ist nicht korrekt."
    if "http 403" in low or "forbidden" in low:
        return "Anmeldung wurde vom Server abgelehnt."
    if "timed out" in low or "timeout" in low:
        return "Zeitüberschreitung bei der Anmeldung."
    if "requests fehlt" in low:
        return "Benötigtes Netzwerkmodul ist nicht verfügbar."
    if "server und benutzername fehlen" in low:
        return "Bitte Server und Benutzername angeben."
    return "Anmeldung nicht möglich. Bitte Zugangsdaten und Server prüfen."


def _embyflow_login_v20_login(self):
    _EMBYFLOW_LOGIN_V20_PREV_LOGIN(self)

    # Der bestehende Login bleibt vollständig zuständig für Auth/Token/Config.
    # Hier wird ausschliesslich sein sichtbarer Fehlertext benutzerfreundlich.
    try:
        current = str(self["login_status"].getText() or "")
    except Exception:
        current = ""

    if current.startswith("Login fehlgeschlagen:"):
        _embyflow_login_v20_log(
            "LOGIN_FAIL detail=%s" % current
        )
        try:
            self["login_status"].setText(
                _embyflow_login_v20_classify_login_error(current)
            )
        except Exception:
            pass


EmbyFlowConnectionWizard.login = _embyflow_login_v20_login


def _embyflow_login_v20_activate(self):
    area = str(
        getattr(self, "embyflow_login_area_v19", "nav")
        or "nav"
    )

    # Nur der sichtbare Hauptbutton bekommt bei einem leeren Slot ein
    # sinnvolles Verhalten. Alle anderen V19-Aktionen bleiben unveraendert.
    if (
        area == "content"
        and self.focus == 7
        and not str(self.server or "").strip()
    ):
        self.edit_server_slot(self.selected_server_index)
        return

    _EMBYFLOW_LOGIN_V20_PREV_ACTIVATE(self)


EmbyFlowConnectionWizard.activate = _embyflow_login_v20_activate


