        '<widget name="context_cover_v21" position="589,129" size="1297,797" '
        'zPosition="40" backgroundColor="#07111E" transparent="0" />'

        '<widget name="context_title_v21" position="640,174" size="1040,52" '
        'zPosition="42" font="Bold;31" foregroundColor="#23E6E8" '
        'backgroundColor="#07111E" transparent="1" />'

        '<widget name="context_subtitle_v21" position="640,235" size="1080,40" '
        'zPosition="42" font="Regular;20" foregroundColor="#F5F7FA" '
