        '<widget name="context_body_v21" position="640,320" size="1080,210" '
        'zPosition="42" font="Regular;20" foregroundColor="#8D96A1" '
        'backgroundColor="#07111E" transparent="1" />'

        '<widget name="context_info_v21" position="640,570" size="1080,76" '
        'zPosition="42" font="Regular;19" foregroundColor="#4EA4FF" '
        'backgroundColor="#07111E" transparent="1" />'

        '<widget name="context_action_bg_v21" position="640,730" size="1110,82" '
