# ============================================================================
# EMBYFLOW_FAVORITE_RESOLUTION_V25_START
# 10.09.2026
#
# V25 – Dialog nach der bestätigten Vorschau:
# - kompletter Cyan-Fokusrahmen + dezente Vollzeilen-Hervorhebung
# - eigener großer Radio-Indikator links
# - Text bleibt weiß; Cyan ist Fokus-/Radio-Akzent
# - kompakte gelbe Qualitäts-Badges rechts
# - Info-Bereich mit Hinweistext
# - Trennlinie + sichtbare OK/EXIT-Aktionsleiste im Dialog
# - untere Mini-Hilfe entfällt
#
# Auflösung:
# - explizite Qualitätsangaben aus DisplayTitle/Resolution/Name/Path
# - danach echte Width/Height
# - 1920x800/804/816 usw. = 1080p-Klasse
# - 3840er Breite / 2160er Höhe = 4K/UHD
# - Detailabruf fordert Path zusätzlich an
#
# Keine Änderungen an Login, Playback oder Untertiteln.
# ============================================================================


def _embyflow_favres_v25_quality_tokens(item):
    values = []

    def add(value):
        value = str(value or "").strip()
        if value:
            values.append(value)

    for key in (
        "VideoResolution",
        "video_resolution",
        "DisplayTitle",
        "display_title",
        "Path",
        "path",
        "Name",
        "name",
        "title",
    ):
        add((item or {}).get(key))

    try:
        for stream in _embyflow_favres_v22_top_media_streams(item):
            if str((stream or {}).get("Type") or "").casefold() != "video":
                continue
            for key in (
                "DisplayTitle",
                "Title",
                "VideoResolution",
                "Name",
            ):
                add((stream or {}).get(key))
    except Exception:
        pass

    try:
        for source in _embyflow_favres_v22_media_sources(item):
            for key in (
                "Name",
                "DisplayTitle",
                "Path",
                "VideoResolution",
            ):
                add((source or {}).get(key))

            try:
                for stream in list((source or {}).get("MediaStreams") or []):
                    if str((stream or {}).get("Type") or "").casefold() != "video":
                        continue
                    for key in (
                        "DisplayTitle",
                        "Title",
                        "VideoResolution",
                        "Name",
                    ):
                        add((stream or {}).get(key))
            except Exception:
                pass
    except Exception:
        pass

    return " | ".join(values).casefold()


def _embyflow_favres_v22_resolution(item):
    max_w = 0
    max_h = 0

    def absorb_stream(stream):
        nonlocal max_w, max_h

        if str((stream or {}).get("Type") or "").casefold() != "video":
            return

        try:
            max_w = max(max_w, int((stream or {}).get("Width") or 0))
        except Exception:
            pass

        try:
            max_h = max(max_h, int((stream or {}).get("Height") or 0))
        except Exception:
            pass

    try:
        for stream in _embyflow_favres_v22_top_media_streams(item):
            absorb_stream(stream)
    except Exception:
        pass

    try:
        for source in _embyflow_favres_v22_media_sources(item):
            try:
                for stream in list((source or {}).get("MediaStreams") or []):
                    absorb_stream(stream)
            except Exception:
                pass

            try:
                max_w = max(max_w, int((source or {}).get("Width") or 0))
            except Exception:
                pass

            try:
                max_h = max(max_h, int((source or {}).get("Height") or 0))
            except Exception:
                pass
    except Exception:
        pass

    try:
        max_w = max(max_w, int((item or {}).get("Width") or 0))
    except Exception:
        pass

    try:
        max_h = max(max_h, int((item or {}).get("Height") or 0))
    except Exception:
        pass

    tokens = _embyflow_favres_v25_quality_tokens(item)

    explicit_4k = bool(
        re.search(
            r"(^|[^0-9])(2160p?|4k|uhd)([^0-9]|$)",
            tokens,
            re.IGNORECASE,
        )
    )
    explicit_1080 = bool(
        re.search(
            r"(^|[^0-9])1080[pi]?([^0-9]|$)",
            tokens,
            re.IGNORECASE,
        )
    )
    explicit_720 = bool(
        re.search(
            r"(^|[^0-9])720[pi]?([^0-9]|$)",
            tokens,
            re.IGNORECASE,
        )
    )

    if explicit_4k or max_w >= 3840 or max_h >= 2160:
        key = "2160"
        label = "4K/UHD"
        short = "4K UHD"
        combo = "4K"
        rank = 2160
    elif explicit_1080 or max_w >= 1920 or max_h >= 1080:
        key = "1080"
        label = "1080p"
        short = "1080p"
        combo = "1080p"
        rank = 1080
    elif explicit_720 or max_w >= 1280 or max_h >= 720:
        key = "720"
        label = "720p"
        short = "720p"
        combo = "720p"
        rank = 720
    elif max_h > 0 or max_w > 0:
        effective = max_h or max_w
        key = str(effective)
        label = "%dp" % effective if max_h else "%d px" % max_w
        short = label
        combo = label
        rank = effective
    else:
        key = "unknown"
        label = "Unbekannte Auflösung"
        short = "?"
        combo = "?"
        rank = 0

    return {
        "key": key,
        "label": label,
        "short": short,
        "combo": combo,
        "rank": rank,
        "width": max_w,
        "height": max_h,
        "tokens": tokens[:240],
    }


def _embyflow_favres_v22_raw_to_item(raw):
    title = str((raw or {}).get("Name") or "").strip()

    return {
        "title": title,
        "Name": title,
        "search_term": title,
        "id": (raw or {}).get("Id"),
        "Id": (raw or {}).get("Id"),
        "type": (raw or {}).get("Type"),
        "Type": (raw or {}).get("Type"),
        "ProductionYear": (raw or {}).get("ProductionYear"),
        "RunTimeTicks": (raw or {}).get("RunTimeTicks"),
        "runtime_ticks": (raw or {}).get("RunTimeTicks"),
        "MediaSources": (raw or {}).get("MediaSources") or [],
        "media_sources": (raw or {}).get("MediaSources") or [],
        "MediaStreams": (raw or {}).get("MediaStreams") or [],
        "media_streams": (raw or {}).get("MediaStreams") or [],
        "Width": (raw or {}).get("Width"),
        "Height": (raw or {}).get("Height"),
        "VideoResolution": (raw or {}).get("VideoResolution"),
        "DisplayTitle": (raw or {}).get("DisplayTitle"),
        "Path": (raw or {}).get("Path"),
        "path": (raw or {}).get("Path"),
        "ProviderIds": (raw or {}).get("ProviderIds") or {},
        "user_data": (raw or {}).get("UserData") or {},
        "UserData": (raw or {}).get("UserData") or {},
        "overview": (raw or {}).get("Overview") or "",
    }


def _embyflow_favres_v24_fetch_detail(server, headers, user_id, item_id):
    if not server or not user_id or not item_id:
        return None

    response = embyflow_http_get(
        server + "/Users/%s/Items/%s" % (user_id, item_id),
        headers=headers,
        params={
            "Fields": (
                "Path,ProductionYear,RunTimeTicks,"
                "MediaSources,MediaStreams,"
                "ProviderIds,UserData,Overview"
            ),
        },
        timeout=10,
        verify=True,
    )

    if response.status_code != 200:
        return None

    try:
        payload = response.json() or {}
    except Exception:
        return None

    return payload if isinstance(payload, dict) else None


