# EMBYFLOW_DYNAMIC_NAV_REFRESH_V29_START
# 10.09.2026
#
# Fix fuer frische/erstmalige Logins:
# - Die direkte linke Navigation wird beim ersten Layout aufgebaut, waehrend
#   der Emby-Auth-/Startup-Sync auf manchen Boxen noch nicht fertig ist.
# - Ergebnis war dort: nur die festen Punkte (Start/Weiter/.../Favoriten),
#   obwohl die Bibliotheken kurz danach bereits verfuegbar waren.
# - V29 holt die echten /Users/{UserId}/Views asynchron nach und baut nur die
#   Navigation im GUI-Thread neu auf.
# - Kein Hardcoding von Bibliotheksnamen, IDs, Servern, Benutzern oder Boxen.
# - Keine Aenderung an Playback oder Untertiteln.
# ============================================================================

_EMBYFLOW_NAVFIX_V29_LOG = "/tmp/embyflow_dynamic_nav_v29.log"
_EMBYFLOW_NAVFIX_V29_PREV_INIT = EmbyFlowE2Screen._direct_nav_init_ref12
_EMBYFLOW_NAVFIX_V29_PREV_SYNC_APPLY = EmbyFlowE2Screen._apply_startup_sync_result


def _embyflow_navfix_v29_log(message):
    try:
        with embyflow_open_log(_EMBYFLOW_NAVFIX_V29_LOG, "a") as handle:
            handle.write(
                "%s %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_navfix_v29_normalize_views(payload):
    result = []
    seen_ids = set()

    try:
        items = (payload or {}).get("Items", []) or []
    except Exception:
        items = []

    for item in items:
        if not isinstance(item, dict):
            continue

        view_id = str(item.get("Id") or "").strip()
        name = str(item.get("Name") or "").strip()
        if not view_id or not name or view_id in seen_ids:
            continue

        seen_ids.add(view_id)
        collection_type = str(item.get("CollectionType") or "").strip()

        server_count = None
        view_type = collection_type.lower()
        if view_type == "movies":
            count_keys = ("MovieCount", "ChildCount", "RecursiveItemCount")
        elif view_type == "tvshows":
            count_keys = ("SeriesCount", "ChildCount", "RecursiveItemCount")
        else:
            count_keys = ("ChildCount", "RecursiveItemCount")

        for key in count_keys:
            if item.get(key) is None:
                continue
            try:
                server_count = int(item.get(key))
                break
            except Exception:
                pass

        result.append({
            "id": view_id,
            "name": name,
            "type": collection_type,
            "server_count": server_count,
        })

    return result


def _embyflow_navfix_v29_entries(views):
    entries = [
        ("Start", {"_direct_action_ref12": "home"}),
        ("Weiterschauen", {"_direct_action_ref12": "continue"}),
        ("Neu hinzugefügt", {"_direct_action_ref12": "new"}),
    ]

    for view in list(views or []):
        try:
            name = str(view.get("name") or "").strip()
            view_id = str(view.get("id") or "").strip()
            collection_type = str(view.get("type") or "").strip()
        except Exception:
            continue

        if not name or not view_id:
            continue

        entries.append((
            name,
            {
                "_direct_action_ref12": "server_view",
                "library_id": view_id,
                "library_name": name,
                "collection_type": collection_type,
                "include_types": (
                    embyflow_collection_include_types(collection_type)
                    or ""
                ),
                "dynamic_server_view": True,
            },
        ))

    entries.extend([
        ("Favoriten", {"_direct_action_ref12": "favorites"}),
        ("Suche", {"_direct_action_ref12": "search"}),
        ("Updates", {"_direct_action_ref12": "updates"}),
        ("Info / Einstellungen", {"_direct_action_ref12": "settings"}),
    ])
    return entries


def _embyflow_navfix_v29_current_key(self):
    try:
        entries = list(getattr(self, "direct_nav_entries_ref12", None) or [])
        index = int(getattr(self, "direct_nav_cursor_ref12", 0) or 0)
        if not (0 <= index < len(entries)):
            return None
        _label, data = entries[index]
        if not isinstance(data, dict):
            return None
        action = str(data.get("_direct_action_ref12") or "")
        library_id = str(data.get("library_id") or "")
        return (action, library_id)
    except Exception:
        return None


def _embyflow_navfix_v29_apply_views(self, views):
    views = list(views or [])
    if not views:
        return False

    old_key = _embyflow_navfix_v29_current_key(self)
    new_entries = _embyflow_navfix_v29_entries(views)

    self.direct_nav_entries_ref12 = new_entries

    target_index = None
    if old_key:
        for index, entry in enumerate(new_entries):
            try:
                data = entry[1] if isinstance(entry[1], dict) else {}
                key = (
                    str(data.get("_direct_action_ref12") or ""),
                    str(data.get("library_id") or ""),
                )
                if key == old_key:
                    target_index = index
                    break
            except Exception:
                pass

    if target_index is None:
        try:
            target_index = max(
                0,
                min(
                    int(getattr(self, "direct_nav_cursor_ref12", 0) or 0),
                    len(new_entries) - 1,
                ),
            )
        except Exception:
            target_index = 0

    self.direct_nav_cursor_ref12 = int(target_index)
    self.direct_nav_page_start_ref12 = max(
        0,
        min(
            int(getattr(self, "direct_nav_page_start_ref12", 0) or 0),
            max(0, len(new_entries) - int(getattr(self, "direct_nav_page_size_ref12", 18) or 18)),
        ),
    )

    try:
        self._direct_nav_refresh_ref12(keep_content_focus=True)
    except TypeError:
        self._direct_nav_refresh_ref12()

    _embyflow_navfix_v29_log("APPLY views=%d" % len(views))
    return True


def _embyflow_navfix_v29_poll(self):
    result = getattr(self, "_embyflow_navfix_v29_result", None)
    if result is None:
        if getattr(self, "_embyflow_navfix_v29_running", False):
            try:
                self._embyflow_navfix_v29_timer.start(200, True)
            except Exception:
                pass
        return

    self._embyflow_navfix_v29_result = None
    self._embyflow_navfix_v29_running = False

    views = list(result.get("views") or [])
    error = str(result.get("error") or "")

    if views:
        try:
            _embyflow_navfix_v29_apply_views(self, views)
        except Exception as apply_error:
            _embyflow_navfix_v29_log(
                "APPLY_ERROR type=%s" % type(apply_error).__name__
            )
    else:
        _embyflow_navfix_v29_log(
            "NO_VIEWS error_type=%s"
            % (error or "none")
        )


def _embyflow_navfix_v29_start(self, reason="layout"):
    if getattr(self, "_embyflow_navfix_v29_running", False):
        return

    self._embyflow_navfix_v29_running = True
    self._embyflow_navfix_v29_result = None

    if not hasattr(self, "_embyflow_navfix_v29_timer"):
        self._embyflow_navfix_v29_timer = eTimer()
        try:
            self._embyflow_navfix_v29_timer.callback.append(
                self._embyflow_navfix_v29_poll
            )
        except Exception:
            try:
                self._embyflow_navfix_v29_timer.timeout.connect(
                    self._embyflow_navfix_v29_poll
                )
            except Exception:
                pass

    def worker():
        result = {"views": [], "error": ""}
        try:
            server = str(EMBY_AUTH_CACHE.get("server") or EMBY_SERVER or "").rstrip("/")
            token = str(EMBY_AUTH_CACHE.get("token") or "")
            user_id = str(EMBY_AUTH_CACHE.get("user_id") or "")

            if not server or not token or not user_id:
                auth_server, auth_token, auth_user_id = get_emby_auth(False)
                server = str(auth_server or server or "").rstrip("/")
                token = str(auth_token or token or "")
                user_id = str(auth_user_id or user_id or "")

            if not server or not token or not user_id:
                raise RuntimeError("auth_not_ready")

            response = embyflow_http_get(
                server + "/Users/%s/Views" % user_id,
                headers={
                    "X-Emby-Token": token,
                    "X-Emby-Authorization": AUTH_HEADER,
                },
                timeout=10,
                verify=True,
            )

            if int(getattr(response, "status_code", 0) or 0) != 200:
                raise RuntimeError(
                    "views_http_%s" % getattr(response, "status_code", "?")
                )

            result["views"] = _embyflow_navfix_v29_normalize_views(
                response.json() or {}
            )
        except Exception as error:
            result["error"] = type(error).__name__

        self._embyflow_navfix_v29_result = result

    try:
        import threading
        thread = threading.Thread(
            target=worker,
            name="EmbyFlowDynamicNavV29",
        )
        thread.daemon = True
        thread.start()
        self._embyflow_navfix_v29_timer.start(200, True)
        _embyflow_navfix_v29_log("START reason=%s" % str(reason or ""))
    except Exception as error:
        self._embyflow_navfix_v29_running = False
        self._embyflow_navfix_v29_result = None
        _embyflow_navfix_v29_log(
            "START_ERROR type=%s" % type(error).__name__
        )


def _embyflow_navfix_v29_init(self):
    _EMBYFLOW_NAVFIX_V29_PREV_INIT(self)
    _embyflow_navfix_v29_start(self, "layout")


def _embyflow_navfix_v29_sync_apply(self):
    snapshot = dict(
        getattr(self, "_startup_sync_worker_result", None)
        or {}
    )
    result = _EMBYFLOW_NAVFIX_V29_PREV_SYNC_APPLY(self)
    if snapshot.get("success"):
        _embyflow_navfix_v29_start(self, "startup-sync")
    return result


EmbyFlowE2Screen._embyflow_navfix_v29_poll = _embyflow_navfix_v29_poll
EmbyFlowE2Screen._embyflow_navfix_v29_start = _embyflow_navfix_v29_start
EmbyFlowE2Screen._direct_nav_init_ref12 = _embyflow_navfix_v29_init
EmbyFlowE2Screen._apply_startup_sync_result = _embyflow_navfix_v29_sync_apply

# EMBYFLOW_DYNAMIC_NAV_REFRESH_V29_END

# EMBYFLOW_NAV_GROUPS_V30_START
# 11.09.2026
#
# Einklappbare Server-Bibliotheken in der Home-Navigation:
# - Movie-Views werden unter dem primaeren Filme-Eintrag gruppiert.
# - TV-Views werden unter dem primaeren Serien-Eintrag gruppiert.
# - RECHTS klappt eine geschlossene Gruppe auf.
# - LINKS klappt eine offene Gruppe bzw. einen Kind-Eintrag wieder zu.
# - OK auf Filme/Serien oeffnet weiterhin die jeweilige Hauptbibliothek.
# - Unterbibliotheken werden mit Radio-Punkten dargestellt (○ / ●).
# - Der Auf-/Zu-Zustand wird in /etc/enigma2 gespeichert.
# - Andere CollectionTypes und Server-Views bleiben unveraendert.
#
# EMBYFLOW_NAV_GROUPS_V30_LOCALTEST
# EMBYFLOW_NAV_GROUPS_V30_1_LOCALTEST
# EMBYFLOW_NAV_GROUPS_V30_2_TRIANGLES_LOCALTEST
# EMBYFLOW_NAV_GROUPS_V30_3_YELLOW_TRIANGLES_PUBLIC
# V30.1: name-safe grouping + reliable parent arrow in focused row.
# ============================================================================

_EMBYFLOW_NAV_GROUPS_V30_STATE_FILE = "/etc/enigma2/embyflow_nav_groups_v30.json"


def _embyflow_nav_groups_v30_load_state():
    state = read_json_file(_EMBYFLOW_NAV_GROUPS_V30_STATE_FILE, {}) or {}
    if not isinstance(state, dict):
        state = {}
    return {
        "movies": bool(state.get("movies", False)),
        "tvshows": bool(state.get("tvshows", False)),
    }


_EMBYFLOW_NAV_GROUPS_V30_STATE = _embyflow_nav_groups_v30_load_state()


def _embyflow_nav_groups_v30_save_state():
    try:
        ensure_dir(os.path.dirname(_EMBYFLOW_NAV_GROUPS_V30_STATE_FILE))
        write_json_file(
            _EMBYFLOW_NAV_GROUPS_V30_STATE_FILE,
            dict(_EMBYFLOW_NAV_GROUPS_V30_STATE),
        )
    except Exception:
        pass


def _embyflow_nav_groups_v30_collection_key(data):
    try:
        value = str((data or {}).get("collection_type") or "").strip().lower()
    except Exception:
        value = ""

    if value in ("movies", "movie"):
        return "movies"
    if value in ("tvshows", "series", "tvshow"):
        return "tvshows"
    return ""


def _embyflow_nav_groups_v30_primary_index(entries, indices, group_key):
    preferred_names = {
        "movies": ("filme", "movies", "movie"),
        "tvshows": ("serien", "series", "tv shows", "tvshows"),
    }.get(group_key, ())

    for index in indices:
        try:
            name = str(entries[index][0] or "").strip().lower()
        except Exception:
            name = ""
        if name in preferred_names:
            return index

    return indices[0] if indices else None


def _embyflow_nav_groups_v30_name_matches_group(label, group_key):
    """Keep only explicitly named movie/series families in collapsible groups.

    Some Emby libraries such as concert collections can report CollectionType=movies.
    They must stay standalone instead of being swallowed by the Filme group.
    """
    try:
        name = " ".join(str(label or "").strip().lower().split())
    except Exception:
        name = ""

    prefixes = {
        "movies": ("filme", "movies", "movie"),
        "tvshows": ("serien", "series", "tv shows", "tvshows"),
    }.get(group_key, ())

    for prefix in prefixes:
        if name == prefix or name.startswith(prefix + " "):
            return True
    return False


def _embyflow_nav_groups_v30_transform(flat_entries):
    entries = list(flat_entries or [])
    groups = {"movies": [], "tvshows": []}

    for index, entry in enumerate(entries):
        try:
            data = entry[1] if isinstance(entry[1], dict) else {}
        except Exception:
            data = {}

        if str(data.get("_direct_action_ref12") or "") != "server_view":
            continue

        group_key = _embyflow_nav_groups_v30_collection_key(data)
        if group_key and _embyflow_nav_groups_v30_name_matches_group(entry[0], group_key):
            groups[group_key].append(index)

    group_info = {}
    for group_key in ("movies", "tvshows"):
        indices = list(groups.get(group_key) or [])
        # Nur dann als Gruppe darstellen, wenn wirklich Unterkategorien existieren.
        if len(indices) < 2:
            continue
        primary_index = _embyflow_nav_groups_v30_primary_index(
            entries,
            indices,
            group_key,
        )
        if primary_index is None:
            continue
        group_info[group_key] = {
            "indices": indices,
            "primary": primary_index,
            "first": min(indices),
        }

    if not group_info:
        return entries

    result = []
    emitted_groups = set()
    grouped_indices = set()
    for info in group_info.values():
        grouped_indices.update(info["indices"])

    for index, entry in enumerate(entries):
        if index not in grouped_indices:
            result.append(entry)
            continue

        current_group = ""
        current_info = None
        for group_key, info in group_info.items():
            if index in info["indices"]:
                current_group = group_key
                current_info = info
                break

        if not current_group or current_group in emitted_groups:
            continue

        # Gruppe genau an der Position des ersten zugehoerigen Server-Views einfuegen.
        if index != current_info["first"]:
            continue

        emitted_groups.add(current_group)
        primary_index = current_info["primary"]
        primary_label, primary_data = entries[primary_index]
        parent_data = dict(primary_data or {})
        parent_data["_nav_group_v30"] = current_group
        parent_data["_nav_group_role_v30"] = "parent"
        parent_data["_nav_group_expanded_v30"] = bool(
            _EMBYFLOW_NAV_GROUPS_V30_STATE.get(current_group, False)
        )
        result.append((primary_label, parent_data))

        if not _EMBYFLOW_NAV_GROUPS_V30_STATE.get(current_group, False):
            continue

        for child_index in current_info["indices"]:
            if child_index == primary_index:
                continue
            child_label, child_data = entries[child_index]
            payload = dict(child_data or {})
            payload["_nav_group_v30"] = current_group
            payload["_nav_group_role_v30"] = "child"
            result.append((child_label, payload))

    return result


def _embyflow_nav_groups_v30_display_label(self, entry, focused=False):
    try:
        label, data = entry
    except Exception:
        return ""

    data = data if isinstance(data, dict) else {}
    label = self._sidebar_display_label_v24(str(label or ""), 19)
    role = str(data.get("_nav_group_role_v30") or "")
    group_key = str(data.get("_nav_group_v30") or "")

    if role == "parent":
        # Arrow is rendered by a separate yellow Label so only the disclosure
        # triangle is colored; the parent text keeps the normal menu color.
        return "   " + label

    if role == "child":
        # Der Fokus-Tile entspricht dem ausgewaehlten Radio-Eintrag.
        return "   %s %s" % ("●" if focused else "○", label)

    return "   " + self._sidebar_display_label_v24(str(entry[0] or ""), 20)



# EMBYFLOW_NAV_YELLOW_PARENT_ARROWS_V1_START
# Separate yellow disclosure triangles for Filme/Serien parent rows.  This is
# deliberately implemented inside the V30 feature pack so the public RCDEV9
# baseline is not replaced by a local test plugin.
def _embyflow_nav_groups_v30_arrow_text(entry):
    try:
        _label, data = entry
    except Exception:
        return ""
    data = data if isinstance(data, dict) else {}
    if str(data.get("_nav_group_role_v30") or "") != "parent":
        return ""
    group_key = str(data.get("_nav_group_v30") or "")
    if group_key not in ("movies", "tvshows"):
        return ""
    return "▾" if bool(_EMBYFLOW_NAV_GROUPS_V30_STATE.get(group_key, False)) else "▸"


def _embyflow_nav_groups_v30_install_arrow_skin():
    try:
        skin_text = str(getattr(EmbyFlowE2Screen, "skin", "") or "")
        if 'name="side_sub_arrow_0"' in skin_text:
            return
        widgets = []
        for index in range(18):
            widgets.append(
                '<widget name="side_sub_arrow_%d" position="%d,%d" size="%d,%d" '
                'zPosition="210" font="Regular;%d" foregroundColor="#FFD400" '
                'backgroundColor="#050A12" halign="left" valign="center" transparent="1" />'
                % (
                    index,
                    sx(48), sy(224 + (34 * index)), sx(24), sy(30), sf(17),
                )
            )
        marker = "\n        <!-- EMBYFLOW_NAV_YELLOW_PARENT_ARROWS_V1 -->\n        " + "\n        ".join(widgets) + "\n"
        if "</screen>" not in skin_text:
            raise RuntimeError("home skin closing tag missing")
        EmbyFlowE2Screen.skin = skin_text.replace("</screen>", marker + "</screen>", 1)
    except Exception:
        pass


_embyflow_nav_groups_v30_install_arrow_skin()
_EMBYFLOW_NAV_GROUPS_V30_PREV_INIT = EmbyFlowE2Screen.__init__


def _embyflow_nav_groups_v30_init(self, *args, **kwargs):
    _EMBYFLOW_NAV_GROUPS_V30_PREV_INIT(self, *args, **kwargs)
    for index in range(18):
        try:
            self["side_sub_arrow_%d" % index] = Label("")
        except Exception:
            pass
    # The original __init__ may already have performed its first navigation
    # refresh before these extra Labels existed. Repaint once now that all
    # yellow-arrow components are registered.
    try:
        self._direct_nav_refresh_ref12()
    except Exception:
        pass


EmbyFlowE2Screen.__init__ = _embyflow_nav_groups_v30_init
# EMBYFLOW_NAV_YELLOW_PARENT_ARROWS_V1_END


_EMBYFLOW_NAV_GROUPS_V30_PREV_BUILD = EmbyFlowE2Screen._direct_nav_build_entries_ref12
_EMBYFLOW_NAV_GROUPS_V30_PREV_REFRESH = EmbyFlowE2Screen._direct_nav_refresh_ref12
_EMBYFLOW_NAV_GROUPS_V30_PREV_UPDATE_FOCUS = EmbyFlowE2Screen.update_focus
_EMBYFLOW_NAV_GROUPS_V30_PREV_LEFT = EmbyFlowE2Screen.left
_EMBYFLOW_NAV_GROUPS_V30_PREV_RIGHT = EmbyFlowE2Screen.right
_EMBYFLOW_NAV_GROUPS_V30_PREV_V29_ENTRIES = _embyflow_navfix_v29_entries
_EMBYFLOW_NAV_GROUPS_V30_PREV_V29_APPLY = _embyflow_navfix_v29_apply_views


def _embyflow_nav_groups_v30_build(self):
    flat_entries = list(_EMBYFLOW_NAV_GROUPS_V30_PREV_BUILD(self) or [])
    self._nav_groups_v30_flat_entries = list(flat_entries)
    return _embyflow_nav_groups_v30_transform(flat_entries)


def _embyflow_nav_groups_v30_v29_entries(views):
    flat_entries = list(_EMBYFLOW_NAV_GROUPS_V30_PREV_V29_ENTRIES(views) or [])
    return _embyflow_nav_groups_v30_transform(flat_entries)


def _embyflow_nav_groups_v30_v29_apply(self, views):
    try:
        self._nav_groups_v30_flat_entries = list(
            _EMBYFLOW_NAV_GROUPS_V30_PREV_V29_ENTRIES(views) or []
        )
    except Exception:
        pass
    return _EMBYFLOW_NAV_GROUPS_V30_PREV_V29_APPLY(self, views)


def _embyflow_nav_groups_v30_refresh(self, keep_content_focus=False):
    try:
        result = _EMBYFLOW_NAV_GROUPS_V30_PREV_REFRESH(
            self,
            keep_content_focus=keep_content_focus,
        )
    except TypeError:
        result = _EMBYFLOW_NAV_GROUPS_V30_PREV_REFRESH(self)

    entries = list(getattr(self, "direct_nav_entries_ref12", None) or [])
    page_start = int(getattr(self, "direct_nav_page_start_ref12", 0) or 0)
    page_size = int(getattr(self, "direct_nav_page_size_ref12", 18) or 18)
    visible = entries[page_start:page_start + page_size]

    for visible_index in range(page_size):
        try:
            widget = self["side_sub_%d" % visible_index]
            arrow_widget = self["side_sub_arrow_%d" % visible_index]
            if visible_index < len(visible):
                widget.setText(
                    _embyflow_nav_groups_v30_display_label(
                        self,
                        visible[visible_index],
                        False,
                    )
                )
                arrow_widget.setText(
                    _embyflow_nav_groups_v30_arrow_text(visible[visible_index])
                )
            else:
                widget.setText("")
                arrow_widget.setText("")
        except Exception:
            pass

    # PREV_REFRESH ruft update_focus bereits auf; nach dem Umschreiben der
    # Zeilentexte den Fokus-Text sicherheitshalber nochmals angleichen.
    try:
        self.update_focus()
    except Exception:
        pass

    return result


def _embyflow_nav_groups_v30_update_focus(self):
    result = _EMBYFLOW_NAV_GROUPS_V30_PREV_UPDATE_FOCUS(self)
    try:
        if self.focus_name().startswith("nav_dyn_"):
            # direct_nav_cursor_ref12 is the authoritative navigation index.
            # Using current_focus().col here can point at a visual slot rather
            # than the actual dynamic entry and caused the parent arrow to vanish.
            actual_index = int(getattr(self, "direct_nav_cursor_ref12", 0) or 0)
            entries = list(getattr(self, "direct_nav_entries_ref12", None) or [])
            if 0 <= actual_index < len(entries):
                self["nav_focus_marker"].setText(
                    _embyflow_nav_groups_v30_display_label(
                        self,
                        entries[actual_index],
                        True,
                    )
                )
    except Exception:
        pass
    return result


def _embyflow_nav_groups_v30_current(self):
    try:
        index = int(getattr(self, "direct_nav_cursor_ref12", 0) or 0)
        entries = list(getattr(self, "direct_nav_entries_ref12", None) or [])
        if 0 <= index < len(entries):
            label, data = entries[index]
            return label, (data if isinstance(data, dict) else {})
    except Exception:
        pass
    return "", {}


def _embyflow_nav_groups_v30_rebuild(self, group_key, target_role="parent", target_library_id=""):
    flat_entries = list(getattr(self, "_nav_groups_v30_flat_entries", None) or [])
    if not flat_entries:
        try:
            flat_entries = list(_EMBYFLOW_NAV_GROUPS_V30_PREV_BUILD(self) or [])
            self._nav_groups_v30_flat_entries = list(flat_entries)
        except Exception:
            flat_entries = []

    new_entries = _embyflow_nav_groups_v30_transform(flat_entries)
    if not new_entries:
        return False

    target_index = None
    for index, entry in enumerate(new_entries):
        try:
            data = entry[1] if isinstance(entry[1], dict) else {}
        except Exception:
            data = {}
        if str(data.get("_nav_group_v30") or "") != str(group_key or ""):
            continue
        if str(data.get("_nav_group_role_v30") or "") != str(target_role or ""):
            continue
        if target_library_id and str(data.get("library_id") or "") != str(target_library_id):
            continue
        target_index = index
        break

    if target_index is None:
        for index, entry in enumerate(new_entries):
            try:
                data = entry[1] if isinstance(entry[1], dict) else {}
            except Exception:
                data = {}
            if (
                str(data.get("_nav_group_v30") or "") == str(group_key or "")
                and str(data.get("_nav_group_role_v30") or "") == "parent"
            ):
                target_index = index
                break

    if target_index is None:
        target_index = max(
            0,
            min(
                int(getattr(self, "direct_nav_cursor_ref12", 0) or 0),
                len(new_entries) - 1,
            ),
        )

    self.direct_nav_entries_ref12 = new_entries
    self.direct_nav_cursor_ref12 = int(target_index)

    page_size = int(getattr(self, "direct_nav_page_size_ref12", 18) or 18)
    page_start = int(getattr(self, "direct_nav_page_start_ref12", 0) or 0)
    if target_index < page_start:
        page_start = target_index
    elif target_index >= page_start + page_size:
        page_start = target_index - page_size + 1
    self.direct_nav_page_start_ref12 = max(
        0,
        min(page_start, max(0, len(new_entries) - page_size)),
    )

    self._direct_nav_refresh_ref12()
    return True


def _embyflow_nav_groups_v30_set_expanded(self, group_key, expanded, target_role="parent", target_library_id=""):
    if group_key not in ("movies", "tvshows"):
        return False
    _EMBYFLOW_NAV_GROUPS_V30_STATE[group_key] = bool(expanded)
    _embyflow_nav_groups_v30_save_state()
    return _embyflow_nav_groups_v30_rebuild(
        self,
        group_key,
        target_role,
        target_library_id,
    )


def _embyflow_nav_groups_v30_right(self):
    try:
        if self.focus_name().startswith("nav_dyn_"):
            _label, data = _embyflow_nav_groups_v30_current(self)
            group_key = str(data.get("_nav_group_v30") or "")
            role = str(data.get("_nav_group_role_v30") or "")
            if role == "parent" and group_key:
                if not _EMBYFLOW_NAV_GROUPS_V30_STATE.get(group_key, False):
                    _embyflow_nav_groups_v30_set_expanded(
                        self,
                        group_key,
                        True,
                        "parent",
                        str(data.get("library_id") or ""),
                    )
                    return
    except Exception:
        pass
    return _EMBYFLOW_NAV_GROUPS_V30_PREV_RIGHT(self)


def _embyflow_nav_groups_v30_left(self):
    try:
        if self.focus_name().startswith("nav_dyn_"):
            _label, data = _embyflow_nav_groups_v30_current(self)
            group_key = str(data.get("_nav_group_v30") or "")
            role = str(data.get("_nav_group_role_v30") or "")
            if group_key and _EMBYFLOW_NAV_GROUPS_V30_STATE.get(group_key, False):
                # Bei LINKS aus einem Kind oder vom offenen Parent immer sauber
                # auf den Parent zurueck und die Gruppe schliessen.
                _embyflow_nav_groups_v30_set_expanded(
                    self,
                    group_key,
                    False,
                    "parent",
                    "",
                )
                return
    except Exception:
        pass
    return _EMBYFLOW_NAV_GROUPS_V30_PREV_LEFT(self)


# Runtime-Patches bewusst nach V29 registrieren, damit sowohl der erste
# Home-Aufbau als auch der asynchrone /Views-Refresh gruppiert werden.
EmbyFlowE2Screen._direct_nav_build_entries_ref12 = _embyflow_nav_groups_v30_build
EmbyFlowE2Screen._direct_nav_refresh_ref12 = _embyflow_nav_groups_v30_refresh
EmbyFlowE2Screen.update_focus = _embyflow_nav_groups_v30_update_focus
EmbyFlowE2Screen.left = _embyflow_nav_groups_v30_left
EmbyFlowE2Screen.right = _embyflow_nav_groups_v30_right
_embyflow_navfix_v29_entries = _embyflow_nav_groups_v30_v29_entries
_embyflow_navfix_v29_apply_views = _embyflow_nav_groups_v30_v29_apply

# EMBYFLOW_NAV_GROUPS_V30_END

