# EMBYFLOW_THEME_SONGS_TEST_V1_START
# 22.09.2026
# Conservative first-stage Emby theme support for the poster grid:
# - uses Emby's authenticated /Items/{Id}/ThemeSongs endpoint
# - waits 2 seconds after a stable poster selection
# - API work runs outside the Enigma2 GUI thread
# - starts only an audio theme; normal movie/series playback is untouched
# - selection change / OK / screen close stops the theme immediately
# - restores the service that was active before the theme started
# ============================================================================

import urllib.parse
import urllib.request
# -*- coding: utf-8 -*-
"""Theme and trailer lookup. Call resolve_theme_and_trailer from a worker thread."""

THEMERR_BASE = 'https://app.lizardbyte.dev/ThemerrDB'


def _json(url, token=None, timeout=8):
    headers = {'User-Agent': 'EmbyFlowE2/1.0'}
    if token:
        headers['X-Emby-Token'] = token
    request = urllib.request.Request(url, headers=headers)
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return json.loads(response.read(2 * 1024 * 1024).decode('utf-8'))
    except (OSError, ValueError, UnicodeError) as error:
        print('[EmbyFlow][ThemeMedia] Lookup failed: %s' % error)
        return None


class ThemeMediaManager(object):
    """Network calls are synchronous; use from a background worker only."""

    def __init__(self, yt_dlp_module=None):
        if yt_dlp_module is None:
            try:
                import yt_dlp as yt_dlp_module
            except ImportError:
                pass
        self.yt_dlp = yt_dlp_module

    @staticmethod
    def _stream(base, token, media_id, kind):
        return '%s/%s/%s/stream?%s' % (
            base.rstrip('/'), kind, urllib.parse.quote(str(media_id), safe=''),
            urllib.parse.urlencode({'Static': 'true', 'api_key': token}))

    def official(self, server_url, api_key, item_id):
        result = {'theme_song_url': None, 'trailer_url': None}
        if not all((server_url, api_key, item_id)):
            return result
        base = server_url.rstrip('/')
        quoted = urllib.parse.quote(str(item_id), safe='')
        songs = _json('%s/Items/%s/ThemeSongs?InheritFromParent=true' % (base, quoted), api_key)
        entries = (songs or {}).get('Items', []) if isinstance(songs, dict) else []
        if entries and isinstance(entries[0], dict) and entries[0].get('Id'):
            result['theme_song_url'] = self._stream(base, api_key, entries[0]['Id'], 'Audio')
        trailers = _json('%s/Items/%s/LocalTrailers' % (base, quoted), api_key)
        entries = trailers if isinstance(trailers, list) else (trailers or {}).get('Items', []) if isinstance(trailers, dict) else []
        if entries and isinstance(entries[0], dict) and entries[0].get('Id'):
            result['trailer_url'] = self._stream(base, api_key, entries[0]['Id'], 'Videos')
        return result

    def theme_from_themerr(self, tmdb_id, media_type):
        if not tmdb_id or not re.fullmatch(r'[0-9]+', str(tmdb_id)):
            return None
        kind = 'tv_shows' if str(media_type).lower() == 'series' else 'movies'
        info = _json('%s/%s/themoviedb/%s.json' % (THEMERR_BASE, kind, tmdb_id))
        url = info.get('youtube_theme_url') if isinstance(info, dict) else None
        if not url or not self.yt_dlp:
            return None
        return self._youtube_stream(url, 'bestaudio[ext=m4a]/bestaudio')

    def _youtube_stream(self, url, fmt):
        try:
            with self.yt_dlp.YoutubeDL({'quiet': True, 'no_warnings': True,
                                        'format': fmt, 'noplaylist': True,
                                        'socket_timeout': 8}) as ydl:
                info = ydl.extract_info(url, download=False)
                stream = info.get('url') if isinstance(info, dict) else None
                return stream if stream and stream.startswith(('http://', 'https://')) else None
        except Exception as error:
            print('[EmbyFlow][ThemeMedia] Stream unavailable: %s' % error)
            return None

    def resolve_theme_and_trailer(self, server_url, api_key, item):
        item = item or {}
        result = self.official(server_url, api_key, item.get('Id') or item.get('id'))
        source = {'theme_song': 'server' if result['theme_song_url'] else None,
                  'trailer': 'server' if result['trailer_url'] else None}
        if not result['theme_song_url']:
            providers = item.get('ProviderIds') or {}
            tmdb = next((value for key, value in providers.items()
                         if str(key).lower() == 'tmdb'), None)
            result['theme_song_url'] = self.theme_from_themerr(tmdb, item.get('Type'))
            if result['theme_song_url']:
                source['theme_song'] = 'ThemerrDB'
        result['source'] = source
        return result


EMBYFLOW_THEME_SONGS_ENABLED = True
EMBYFLOW_THEME_SONG_DELAY_MS = 2000


def _embyflow_theme_log_v1(message):
    try:
        with open("/tmp/embyflow_theme_test.log", "a") as handle:
            handle.write(
                "%s %s\n"
                % (
                    time.strftime("%Y-%m-%d %H:%M:%S"),
                    str(message or ""),
                )
            )
    except Exception:
        pass


def _embyflow_theme_selected_item_v1(screen):
    try:
        if getattr(screen, "az_mode", False):
            return None
        items = screen.page_items() or []
        focus = int(getattr(screen, "focus", 0) or 0)
        if focus < 0 or focus >= len(items):
            return None
        item = items[focus]
        if not isinstance(item, dict):
            return None
        item_id = str(item.get("Id") or item.get("id") or "").strip()
        item_type = str(item.get("Type") or item.get("type") or "").strip().lower()
        if not item_id or item_type not in ("movie", "series", "season"):
            return None
        return item
    except Exception:
        return None


def _embyflow_theme_stop_v1(screen, restore=True):
    try:
        timer = getattr(screen, "_theme_delay_timer_v1", None)
        if timer is not None:
            timer.stop()
    except Exception:
        pass

    was_playing = bool(getattr(screen, "_theme_playing_v1", False))
    screen._theme_playing_v1 = False
    screen._theme_playing_id_v1 = ""

    if not was_playing:
        return

    try:
        screen.session.nav.stopService()
    except Exception:
        pass

    previous = getattr(screen, "_theme_previous_service_v1", None)
    screen._theme_previous_service_v1 = None

    if restore and previous is not None:
        try:
            screen.session.nav.playService(previous)
        except Exception:
            pass


def _embyflow_theme_schedule_v1(screen):
    try:
        if not EMBYFLOW_THEME_SONGS_ENABLED:
            return

        item = _embyflow_theme_selected_item_v1(screen)
        item_id = str((item or {}).get("Id") or (item or {}).get("id") or "").strip()
        old_id = str(getattr(screen, "_theme_selected_id_v1", "") or "")

        # refresh_grid() is also used for cosmetic refreshes. Do not restart the
        # two-second delay unless the actual selected Emby item changed.
        if item_id == old_id:
            return

        screen._theme_selected_id_v1 = item_id
        screen._theme_generation_v1 = int(getattr(screen, "_theme_generation_v1", 0) or 0) + 1
        _embyflow_theme_stop_v1(screen, restore=True)

        if not item_id:
            return

        timer = getattr(screen, "_theme_delay_timer_v1", None)
        if timer is not None:
            try:
                timer.stop()
            except Exception:
                pass
            try:
                timer.start(EMBYFLOW_THEME_SONG_DELAY_MS, True)
            except Exception:
                timer.start(EMBYFLOW_THEME_SONG_DELAY_MS)
    except Exception as error:
        _embyflow_theme_log_v1("SCHEDULE_ERROR %s" % str(error))


def _embyflow_theme_begin_lookup_v1(screen):
    item = _embyflow_theme_selected_item_v1(screen)
    if not item:
        return

    item_id = str(item.get("Id") or item.get("id") or "").strip()
    if not item_id or item_id != str(getattr(screen, "_theme_selected_id_v1", "") or ""):
        return

    generation = int(getattr(screen, "_theme_generation_v1", 0) or 0)
    screen._theme_lookup_result_v1 = None

    try:
        import threading

        def worker():
            result = {
                "generation": generation,
                "owner_id": item_id,
                "theme": None,
                "error": "",
            }
            try:
                server, token, user_id = get_emby_auth()
                if not server or not token:
                    raise RuntimeError("Emby authentication unavailable")

                response = embyflow_http_get(
                    server.rstrip("/") + "/Items/%s/ThemeSongs" % item_id,
                    headers={
                        "X-Emby-Token": token,
                        "X-Emby-Authorization": AUTH_HEADER,
                    },
                    params={"InheritFromParent": "true"},
                    timeout=8,
                    verify=True,
                )

                if int(getattr(response, "status_code", 0) or 0) != 200:
                    raise RuntimeError(
                        "ThemeSongs HTTP %s"
                        % str(getattr(response, "status_code", "?"))
                    )

                payload = response.json() or {}
                themes = payload.get("Items") or []
                if themes and isinstance(themes[0], dict):
                    result["theme"] = themes[0]
                else:
                    # Only a missing server theme triggers ThemerrDB. This code
                    # runs on the existing worker thread, never the TV UI thread.
                    providers = item.get("ProviderIds") or {}
                    tmdb = next((v for k, v in providers.items()
                                 if str(k).lower() == "tmdb"), None)
                    if not tmdb:
                        details = embyflow_http_get(
                            server.rstrip("/") + "/Users/%s/Items/%s" % (user_id, item_id),
                            headers={"X-Emby-Token": token,
                                     "X-Emby-Authorization": AUTH_HEADER},
                            timeout=8, verify=True)
                        if int(getattr(details, "status_code", 0) or 0) == 200:
                            providers = (details.json() or {}).get("ProviderIds") or {}
                            tmdb = next((v for k, v in providers.items()
                                         if str(k).lower() == "tmdb"), None)
                    if tmdb:
                        result["theme_url"] = ThemeMediaManager().theme_from_themerr(
                            tmdb, item.get("Type") or item.get("type"))

            except Exception as error:
                result["error"] = str(error)

            screen._theme_lookup_result_v1 = result

        thread = threading.Thread(
            target=worker,
            name="EmbyFlowThemeSongLookupV1",
        )
        thread.daemon = True
        thread.start()

        poll = getattr(screen, "_theme_poll_timer_v1", None)
        if poll is not None:
            try:
                poll.stop()
            except Exception:
                pass
            try:
                poll.start(100, True)
            except Exception:
                poll.start(100)

    except Exception as error:
        _embyflow_theme_log_v1("LOOKUP_START_ERROR %s" % str(error))


def _embyflow_theme_poll_lookup_v1(screen):
    result = getattr(screen, "_theme_lookup_result_v1", None)
    if result is None:
        poll = getattr(screen, "_theme_poll_timer_v1", None)
        if poll is not None:
            try:
                poll.start(100, True)
            except Exception:
                try:
                    poll.start(100)
                except Exception:
                    pass
        return

    screen._theme_lookup_result_v1 = None

    generation = int(result.get("generation", -1) or -1)
    if generation != int(getattr(screen, "_theme_generation_v1", 0) or 0):
        return

    selected = _embyflow_theme_selected_item_v1(screen)
    selected_id = str((selected or {}).get("Id") or (selected or {}).get("id") or "").strip()
    if selected_id != str(result.get("owner_id") or ""):
        return

    if result.get("error"):
        _embyflow_theme_log_v1(
            "LOOKUP_ERROR item=%s error=%s"
            % (selected_id, result.get("error"))
        )
        return

    theme = result.get("theme") or {}
    theme_id = str(theme.get("Id") or theme.get("id") or "").strip()
    fallback_url = str(result.get("theme_url") or "")
    if not theme_id and not fallback_url:
        _embyflow_theme_log_v1("NO_THEME item=%s" % selected_id)
        return

    try:
        if theme_id:
            server, token, user_id = get_emby_auth()
            if not server or not token:
                return

        container = ""
        if theme_id:
            media_sources = theme.get("MediaSources") or []
            source = media_sources[0] if media_sources and isinstance(media_sources[0], dict) else {}
            container = str(source.get("Container") or theme.get("Container") or "").strip().lower().lstrip(".")
            safe_container = container if container.replace("_", "").replace("-", "").isalnum() else ""
            extension = ("." + safe_container) if safe_container else ""
            stream_url = "%s/Audio/%s/stream%s?Static=true&api_key=%s" % (
                server.rstrip("/"), theme_id, extension, token,
            )
        else:
            stream_url = fallback_url

        try:
            previous = screen.session.nav.getCurrentlyPlayingServiceReference()
        except Exception:
            previous = None

        screen._theme_previous_service_v1 = previous
        screen._theme_playing_v1 = True
        screen._theme_playing_id_v1 = theme_id or "themerr:" + selected_id

        reference = eServiceReference(STREAM_SERVICE_TYPE, 0, stream_url)
        reference.setName(
            "Theme · %s"
            % str(theme.get("Name") or (selected or {}).get("title") or "Emby")
        )
        screen.session.nav.playService(reference)
        _embyflow_theme_log_v1(
            "PLAY item=%s theme=%s container=%s"
            % (selected_id, theme_id, container or "unknown")
        )

    except Exception as error:
        screen._theme_playing_v1 = False
        _embyflow_theme_log_v1(
            "PLAY_ERROR item=%s error=%s" % (selected_id, str(error))
        )


# Install the test layer only after the complete plugin has defined and patched
# EmbyFlowGridScreen. This keeps all existing navigation/player code intact.
try:
    _EMBYFLOW_THEME_V1_GRID_INIT = EmbyFlowGridScreen.__init__
    _EMBYFLOW_THEME_V1_GRID_REFRESH = EmbyFlowGridScreen.refresh_grid
    _EMBYFLOW_THEME_V1_GRID_OPEN = EmbyFlowGridScreen.open_current

    def _embyflow_theme_grid_init_v1(self, *args, **kwargs):
        _EMBYFLOW_THEME_V1_GRID_INIT(self, *args, **kwargs)
        self._theme_selected_id_v1 = ""
        self._theme_generation_v1 = 0
        self._theme_lookup_result_v1 = None
        self._theme_playing_v1 = False
        self._theme_playing_id_v1 = ""
        self._theme_previous_service_v1 = None

        self._theme_delay_timer_v1 = eTimer()
        self._theme_poll_timer_v1 = eTimer()

        try:
            self._theme_delay_timer_v1.callback.append(
                lambda: _embyflow_theme_begin_lookup_v1(self)
            )
            self._theme_poll_timer_v1.callback.append(
                lambda: _embyflow_theme_poll_lookup_v1(self)
            )
        except Exception:
            pass

        def theme_close_v1():
            self._theme_generation_v1 += 1
            _embyflow_theme_stop_v1(self, restore=True)
            try:
                self._theme_poll_timer_v1.stop()
            except Exception:
                pass

        self.onClose.append(theme_close_v1)

    def _embyflow_theme_grid_refresh_v1(self, *args, **kwargs):
        result = _EMBYFLOW_THEME_V1_GRID_REFRESH(self, *args, **kwargs)
        _embyflow_theme_schedule_v1(self)
        return result

    def _embyflow_theme_grid_open_v1(self, *args, **kwargs):
        self._theme_generation_v1 += 1
        self._theme_selected_id_v1 = ""
        _embyflow_theme_stop_v1(self, restore=True)
        return _EMBYFLOW_THEME_V1_GRID_OPEN(self, *args, **kwargs)

    EmbyFlowGridScreen.__init__ = _embyflow_theme_grid_init_v1
    EmbyFlowGridScreen.refresh_grid = _embyflow_theme_grid_refresh_v1
    EmbyFlowGridScreen.open_current = _embyflow_theme_grid_open_v1

except Exception as error:
    _embyflow_theme_log_v1("INSTALL_ERROR %s" % str(error))

# EMBYFLOW_THEME_SONGS_TEST_V1_END

# EMBYFLOW_SEASON_EPISODE_NUMBER_JUMP_V1_START
# The number keys in other grids retain their existing T9 letter navigation.
class EmbyFlowEpisodeNumberJumpV1(Screen):
    skin = scale_skin("""
    <screen name="EmbyFlowEpisodeNumberJumpV1" position="540,340" size="840,380"
        flags="wfNoBorder" backgroundColor="layer-b-background">
        <eLabel position="0,0" size="840,4" backgroundColor="layer-a-accent1" />
        <widget name="heading" position="52,36" size="736,55" font="Regular;37"
            foregroundColor="layer-a-accent1" backgroundColor="layer-b-background"
            transparent="1" halign="center" />
        <widget name="number" position="52,113" size="736,100" font="Regular;78"
            foregroundColor="layer-a-foreground" backgroundColor="layer-b-background"
            transparent="1" halign="center" valign="center" />
        <widget name="status" position="52,226" size="736,40" font="Regular;23"
            foregroundColor="layer-a-foreground" backgroundColor="layer-b-background"
            transparent="1" halign="center" />
        <widget name="hint" position="52,308" size="736,40" font="Regular;22"
            foregroundColor="layer-a-accent1" backgroundColor="layer-b-background"
            transparent="1" halign="center" />
    </screen>
    """)

    def __init__(self, session, first_digit, available_numbers):
        Screen.__init__(self, session)
        self.number_text = str(first_digit)
        self.available_numbers = set(int(number) for number in available_numbers)
        self["heading"] = Label("Folge direkt wählen")
        self["number"] = Label("")
        self["status"] = Label("")
        self["hint"] = Label("OK Auswählen   GELB Löschen   EXIT Abbrechen")
        actions = {
            "ok": self.confirm,
            "green": self.confirm,
            "cancel": self.close_without_selection,
            "red": self.close_without_selection,
            "yellow": self.backspace,
        }
        for digit in range(10):
            actions[str(digit)] = (
                lambda value=str(digit): self.add_digit(value)
            )
        self["actions"] = ActionMap(
            ["OkCancelActions", "ColorActions", "NumberActions"],
            actions,
            -1
        )
        self.update_number()

    def update_number(self):
        self["number"].setText(self.number_text or "–")
        try:
            number = int(self.number_text)
        except (TypeError, ValueError):
            number = 0
        self["status"].setText(
            "Folge %d vorhanden" % number
            if number in self.available_numbers
            else "Folge nicht in dieser Staffel vorhanden"
        )

    def add_digit(self, digit):
        if len(self.number_text) >= 4:
            return
        self.number_text += digit
        self.update_number()

    def backspace(self):
        self.number_text = self.number_text[:-1]
        self.update_number()

    def confirm(self):
        try:
            number = int(self.number_text)
        except (TypeError, ValueError):
            return
        if number in self.available_numbers:
            self.close(number)

    def close_without_selection(self):
        self.close(None)


def _embyflow_episode_number_v1(item):
    if not isinstance(item, dict):
        return None
    if str(item.get("type") or item.get("Type") or "").lower() != "episode":
        return None
    try:
        number = int(
            item.get("episode_number")
            if item.get("episode_number") is not None
            else item.get("IndexNumber")
        )
    except (TypeError, ValueError):
        return None
    return number if number > 0 else None


_EMBYFLOW_EPISODE_JUMP_ORIGINAL_T9_V1 = EmbyFlowGridScreen.t9_number_pressed


def _embyflow_episode_jump_select_v1(screen, number):
    if number is None or not getattr(screen, "episode_jump_season", False):
        return
    for index, item in enumerate(screen.grid_items or []):
        if _embyflow_episode_number_v1(item) == number:
            screen.az_mode = False
            screen.page = index // 10
            screen.focus = index % 10
            screen.refresh_grid()
            screen.update_focus()
            return


def _embyflow_episode_jump_t9_v1(screen, number_key):
    if not getattr(screen, "episode_jump_season", False):
        return _EMBYFLOW_EPISODE_JUMP_ORIGINAL_T9_V1(screen, number_key)
    numbers = [
        value for value in (
            _embyflow_episode_number_v1(item)
            for item in (screen.grid_items or [])
        )
        if value is not None
    ]
    if not numbers:
        return
    screen.session.openWithCallback(
        lambda selected: _embyflow_episode_jump_select_v1(screen, selected),
        EmbyFlowEpisodeNumberJumpV1,
        str(number_key),
        numbers
    )


EmbyFlowGridScreen.t9_number_pressed = _embyflow_episode_jump_t9_v1


# EMBYFLOW_SERIES_PROGRESS_V1
def _embyflow_series_progress_text(episodes, scope="Serie"):
    """Build the series/season indicator from Emby's per-user episode state."""
    ordered = []
    for item in episodes or []:
        if str(item.get("type") or item.get("Type") or "").lower() != "episode":
            continue
        try:
            season = int(item.get("season_number"))
            number = int(item.get("episode_number"))
        except (TypeError, ValueError):
            continue
        if number < 1:
            continue
        ordered.append((season, number, item))
    normal = [episode for episode in ordered if episode[0] > 0]
    ordered = sorted(normal or ordered, key=lambda episode: (episode[0], episode[1]))
    if not ordered:
        return "Serienstand", "Keine nummerierten Folgen verfügbar"

    def user_data(episode):
        return episode[2].get("user_data") or episode[2].get("UserData") or {}

    def played(episode):
        value = user_data(episode).get("Played", False)
        return value is True or value == 1 or str(value).lower() == "true"

    def label(episode):
        title = str(episode[2].get("title") or episode[2].get("Name") or "").strip()
        if len(title) > 25:
            title = title[:24].rstrip() + "…"
        return "S%02dE%02d%s" % (episode[0], episode[1], (" " + title) if title else "")

    seen = [episode for episode in ordered if played(episode)]
    unseen = [episode for episode in ordered if not played(episode)]
    heading = "Serienstand · %s · %d von %d Folgen gesehen" % (
        scope, len(seen), len(ordered)
    )
    if not seen:
        partial = []
        for episode in unseen:
            try:
                if int(user_data(episode).get("PlaybackPositionTicks") or 0) > 0:
                    partial.append(episode)
            except (ValueError, TypeError):
                pass
        if partial:
            return heading, "Angefangen: %s   •   Hier weiterschauen" % label(partial[0])
        return heading, "Noch keine Folge gesehen   •   Start: %s" % label(ordered[0])

    last = max(
        seen,
        key=lambda episode: (
            str(user_data(episode).get("LastPlayedDate") or ""),
            episode[0], episode[1],
        ),
    )
    if not unseen:
        return heading, "Zuletzt: %s   •   Alle verfügbaren Folgen gesehen" % label(last)

    # An unfinished episode takes precedence over the next untouched one.
    in_progress = []
    for episode in unseen:
        try:
            if int(user_data(episode).get("PlaybackPositionTicks") or 0) > 0:
                in_progress.append(episode)
        except (ValueError, TypeError):
            pass
    after_last = [episode for episode in unseen if episode[:2] > last[:2]]
    next_episode = (in_progress or after_last or unseen)[0]
    return heading, "Zuletzt: %s   •   Nächste: %s" % (label(last), label(next_episode))
# EMBYFLOW_SEASON_EPISODE_NUMBER_JUMP_V1_END

