def _party_qr_png(link):
    # QR encoder below is a bundled, MIT licensed pure Python implementation.
    qr = QRCode(None, QRErrorCorrectLevel.M)
    qr.addData(link)
    qr.make()
    count = qr.getModuleCount()
    scale, quiet = 6, 4
    side = (count + quiet * 2) * scale
    rows = bytearray()
    for y in range(side):
        rows.append(0)
        module_y = y // scale - quiet
        for x in range(side):
            module_x = x // scale - quiet
            dark = (0 <= module_x < count and 0 <= module_y < count
                    and qr.isDark(module_y, module_x))
            rows.append(0 if dark else 255)

    def chunk(kind, data):
        return (_party_struct.pack('!I', len(data)) + kind + data
                + _party_struct.pack('!I', _party_zlib.crc32(kind + data) & 0xffffffff))

    return (b'\x89PNG\r\n\x1a\n'
            + chunk(b'IHDR', _party_struct.pack('!2I5B', side, side, 8, 0, 0, 0, 0))
            + chunk(b'IDAT', _party_zlib.compress(bytes(rows), 9))
            + chunk(b'IEND', b''))

