_party_player_original_start = EmbyFlowMoviePlayer.start_playback
def _party_player_start(self, *args, **kwargs):
    global _party_active_player, _party_context
    result = _party_player_original_start(self, *args, **kwargs)
    context = _party_context
    if context and context.get("item_id") == str(self.item_id):
        _party_context = None
        _party_active_player = self
        self.party_context = context
        self.party_poll_pending = False
        self.party_poll_state = None
        self.party_last_seek = 0
        self.party_timer = eTimer()
        self.party_timer.callback.append(lambda: _party_player_tick(self))
        if context["role"] == "guest":
            self.pause_playback()
        self.party_timer.start(1200, True)
    return result
EmbyFlowMoviePlayer.start_playback = _party_player_start


def _party_player_tick(player):
    if getattr(player, "closed", False) or _party_active_player is not player:
        return
    context = getattr(player, "party_context", None)
    if not context:
        return
    if context["role"] == "host":
        room = _party_room
        if room is None or room.closed:
            return
        with room.lock:
            room.position = max(0, int(player.current_position_ticks() or 0))
            room.paused = bool(player.paused)
            room.updated = time.time()
    else:
        state = player.party_poll_state
        if state is not None:
            player.party_poll_state = None
            player.party_poll_pending = False
            if state.get("closed"):
                player.leave_player()
                return
            if state.get("started") and state.get("item_id") == context["item_id"]:
                desired_pause = bool(state.get("paused"))
                if desired_pause != bool(player.paused):
                    (player.pause_playback if desired_pause else player.resume_playback)()
                target = int(state.get("position") or 0)
                if not desired_pause:
                    target += int(max(0, min(3, time.time() - float(state.get("updated") or time.time()))) * 10000000)
                drift = abs(int(player.current_position_ticks() or 0) - target)
                if drift > 30000000 and time.time() - player.party_last_seek > 8:
                    player.party_last_seek = time.time()
                    try:
                        # The existing chapter seek path supports static Emby streams.
                        player.embyflow_seek_to_chapter(target)
                        if desired_pause:
                            player.pause_playback()
                    except Exception:
                        pass
        if not player.party_poll_pending:
            player.party_poll_pending = True
            def worker():
                try:
                    player.party_poll_state = _party_request(context["host"], "/state", dict(code=context["code"]))
                except Exception:
                    player.party_poll_state = {"error": "Verbindung unterbrochen"}
            _party_threading.Thread(target=worker, daemon=True).start()
    if not getattr(player, "closed", False):
        player.party_timer.start(1200, True)


_party_player_original_leave = EmbyFlowMoviePlayer.leave_player
def _party_player_leave(self, *args, **kwargs):
    global _party_active_player
    try:
        self.party_timer.stop()
    except Exception:
        pass
    if _party_active_player is self:
        _party_active_player = None
    if getattr(self, "party_context", {}).get("role") == "host" and _party_room is not None:
        with _party_room.lock:
            _party_room.closed = True
    return _party_player_original_leave(self, *args, **kwargs)
EmbyFlowMoviePlayer.leave_player = _party_player_leave


# Home navigation: put the Party hub immediately below Updates, including
# when Emby's library list refreshes asynchronously.
def _party_nav_insert(entries):
    rows = [row for row in list(entries or []) if
            str((row[1] if len(row) > 1 and isinstance(row[1], dict) else {}).get("_direct_action_ref12") or "") != "party"]
    for index, row in enumerate(rows):
        data = row[1] if len(row) > 1 and isinstance(row[1], dict) else {}
        if data.get("_direct_action_ref12") == "updates":
            rows.insert(index + 1, ("Watch Party", {"_direct_action_ref12": "party"}))
            break
    return rows


_party_nav_build_original = EmbyFlowE2Screen._direct_nav_build_entries_ref12
def _party_nav_build(self):
    return _party_nav_insert(_party_nav_build_original(self))
EmbyFlowE2Screen._direct_nav_build_entries_ref12 = _party_nav_build

