def _party_nav_async(views):
    return _party_nav_insert(_party_nav_async_original(views))
_embyflow_navfix_v29_entries = _party_nav_async


def _party_home_join(screen, value):
    if not value:
        return
    try:
        fields = str(value).replace(":", " ").split()
        if len(fields) != 2 or not fields[1].isdigit() or len(fields[1]) != 6:
            raise ValueError("Bitte Host-IP und sechsstelligen Code eingeben")
        host, code = fields
        state = _party_request(host, "/state", {"code": code})
        if state.get("closed") or state.get("started"):
            raise ValueError("Die Party ist bereits gestartet oder beendet")
        item_id = str(state.get("item_id") or "")
        title = str(state.get("title") or "")
        if not item_id or not title:
            raise ValueError("Der Party fehlt ein Filmtitel")
        server, token, user_id = get_emby_auth()
        response = embyflow_http_get(
            "%s/Users/%s/Items/%s" % (str(server).rstrip("/"), user_id, item_id),
            headers={"X-Emby-Token": token, "X-Emby-Authorization": AUTH_HEADER},
            timeout=6, verify=True)
        if getattr(response, "status_code", 0) != 200:
            raise ValueError("Dieser Film ist bei deinem Emby-Zugang nicht verfügbar")
        item = response.json() or {}
        if str(item.get("Name") or "").strip().casefold() != title.strip().casefold():
            raise ValueError("Emby-ID bezeichnet auf dieser Box einen anderen Film")
        class DetailProxy(object):
            pass
        detail = DetailProxy()
        detail.session = screen.session
        detail.data = {"id": item_id, "title": title, "Type": item.get("Type"), "_embyflow_lazy_library": True}
        _party_join(detail, value)
    except Exception as error:
        _party_notice(screen.session, "Beitritt fehlgeschlagen: %s" % error)


def _party_home_hub(screen):
    def picked(choice):
        action = choice and choice[1]
        if action == "create":
            _party_notice(screen.session, "Film suchen, Details öffnen, dann rechts Watch Party wählen.")
            screen.open_search_keyboard()
        elif action == "join":
            if VirtualKeyBoard is None:
                _party_notice(screen.session, "Texteingabe fehlt auf dieser Box")
            else:
                screen.session.openWithCallback(
                    lambda value: _party_home_join(screen, value), VirtualKeyBoard,
                    title="Host-IP und Party-Code (192.168.1.11 123456)", text="")
    screen.session.openWithCallback(picked, ChoiceBox,
        title="EmbyFlow Watch Party · Heimnetz", list=[
            ("Watch Party erstellen · Film auswählen", "create"),
            ("Mit IP und Code beitreten", "join")])


